  ["40:4615"] = "Bom dia!\nBem-vindo ao nosso\011CENTRO #MON.",
  ["40:4640"] = "Olá!\nBem-vindo ao nosso\011CENTRO #MON.",
  ["40:4664"] = "Boa noite!\nVocê veio tarde.\012Bem-vindo ao nosso\nCENTRO #MON.",
  ["40:469f"] = "Podemos curar seus\n#MON deixando-\011os com saúde per-\011feita.\012Podemos curar\nseu(s) #MON(S)?",
  ["40:46e2"] = "Certo, deixe-me\nver seu(s)\011#MON(S).",
  ["40:46fc"] = "Obrigado por\naguardar.\012Seu(s) #MON(S)\nestão totalmente\011curados.",
  ["40:4730"] = "We hope to see you\nagain.",
  ["40:4766"] = "Your POKéMON ap-\npear to have tiny\012life forms stuck\nto them.\012Your POKéMON are\nhealthy and seem\011to be fine.\012But we can't tell\nyou anything more\012at a POKéMON\nCENTER.",
  ["40:4801"] = "Está cheio de\nlivros difíceis.",
  ["40:481f"] = "Uma coleção in-\nteira de livros\011de figuras de\011#MON!",
  ["40:484a"] = "REVISTAS #MON…\nJOGOS DE #MON,\012MANUAIS #MON,\nGRÁFICOS #MON…",
  ["40:4880"] = "JURAMENTO DA\nEQUIPE ROCKET\012Roubar #MON\npor lucro!\012Explorar #MON\npor lucro!\012Todos #MON\nexistem para a\011glória da EQUIPE\011ROCKET!",
  ["40:48ef"] = "O que é isso?\012Oh, é um porta\nincensos!",
  ["40:4919"] = "Muitos produtos\npara #MON!",
  ["40:4934"] = "It's the TOWN MAP.",
  ["40:4947"] = "Meu reflexo!\nEu pareço ótimo!",
  ["40:4965"] = "É uma televisão.",
  ["40:4970"] = "HOME PAGE do\n#MON JORNAL…\012Não foi atuali-\nzada…",
  ["40:49cd"] = "Não há nada\naqui…",
  ["40:4a26"] = "Cure os Seus\n#MON!\012CENTRO #MON.",
  ["40:4a43"] = "Agora julgaremos\no #MON que\011você capturou.\012…\n…\012Nós escolhemos os\nvencedores!\012Você está pronto\npara isso?",
  ["40:4a66"] = "We will now judge\nthe POKéMON you've\011caught.\012……\n……\012We have chosen the\nwinners!\012Are you ready for\nthis?",
  ["40:4ac8"] = "Wow! You're pretty\ntough.\012Could I get your\nphone number?\012I'll call you for\na rematch.",
  ["40:4b1d"] = "Register the phone\nnumber?",
  ["40:4b39"] = "{PLAYER} registered\n{STRBUF}'s number.",
  ["40:4b56"] = "I'll call you if\nanything comes up.",
  ["40:4b7a"] = "Oh, OK…\nJust talk to me if\012you want to get my\nphone number.",
  ["40:4bb7"] = "Seu telefone não\ntem memória sufi-\011ciente para mais\011números.",
  ["40:4bef"] = "Eu estava espe-\nrando por você.\011Vamos batalhar!",
  ["40:4c14"] = "Wow, you're good\nat battling.\012Want to give me\nyour phone number?\012I'll phone you for\nanother battle.",
  ["40:4c77"] = "Register the phone\nnumber?",
  ["40:4c93"] = "{PLAYER} registered\n{STRBUF}'s number.",
  ["40:4cb0"] = "I'll call you if\nsomething's up.",
  ["40:4cd0"] = "Oh, fine then…\nIf you want to get\012my phone number,\njust tell me.",
  ["40:4d12"] = "Seu telefone não\ntem memória sufi-\011ciente para mais\011números.",
  ["40:4d4a"] = "I waited for you.\nLet's battle!",
  ["40:4d6a"] = "{PLAYER} wins the\nNo. {STRBUF} prize,\011a {STRBUF}!",
  ["40:4d90"] = "{PLAYER} received\n{STRBUF}.",
  ["40:4da3"] = "Junte-se a nós\npara o próximo\011Concurso!",
  ["40:4dc9"] = "Os outros ganham\num GRÃO como prê-\011mio de consolação!",
  ["40:4dff"] = "Esperamos que me-\nlhorem na próxima\011vez.",
  ["40:4e21"] = "Vamos devolver os\n#MON que guar-\012damos para você.\nAqui está!",
  ["40:4e55"] = "Sua equipe está\ncheia, então o\012foi enviado para\nBOX no PC DO\011BILL.",
  ["40:4e96"] = "{STRBUF}\nGINÁSIO #MON",
  ["40:4ea4"] = "LEADER: {STRBUF}\012WINNING TRAINERS:\n{PLAYER}",
  ["40:4ec7"] = "Bem-vindo à\nCASA DE JOGOS.",
  ["40:4ee4"] = "Você precisa de\nmoedas de jogo?\012Oh, você não tem\num PORTA MOEDAS\011para elas.",
  ["40:4f2b"] = "Você precisa de\nmoedas de jogo?\012O preço é ¥1000\npara 50 moedas.\011Quer algumas?",
  ["40:4f78"] = "Obrigado! \nAqui estão as\01150 moedas.",
  ["40:4f97"] = "Obrigado! \naqui estão as\011500 moedas.",
  ["40:4fb7"] = "You don't have\nenough money.",
  ["40:4fd4"] = "Opa! Seu PORTA\nMOEDAS está cheio.",
  ["40:4ff5"] = "Não quer moedas?\nVolte outra hora!",
  ["40:5014"] = "Oh? Sua BOLSA\nestá cheia.\012Vamos guardar esse\npara você hoje,\012então volte quando\nliberar espaço.",
  ["40:5072"] = "Uau! Você e seus\n#MON são real-\011mente próximos!",
  ["40:509c"] = "Os #MON ficam\nmais amigáveis se\012você gastar tempo\ncom eles.",
  ["40:50d1"] = "Você não domou\nseus #MON.\012Se não se derem\nbem, ele não se\011sentirá à vontade.",
  ["41:4a8a"] = "Bom dia.",
  ["41:4a99"] = "Alô?\012Oh, oi, {PLAYER}!\nEstá trabalhando\011duro?",
  ["41:4aba"] = "Oh, so you're in\n{STRBUF}…\012Isn't that where\n{STRBUF}\012is? Did you go\ntake a look?",
  ["41:4b04"] = "Really, you're in\n{STRBUF}?\012I've never gone\nthere. That's kind\011of neat, {PLAYER}.",
  ["41:4b4a"] = "What? You're in\n{STRBUF}?\012Come see your MOM\nsometime!",
  ["41:4b7d"] = "You're visiting\n{STRBUF}?\012How about coming\nhome for a bit?",
  ["41:4bb5"] = "Wow, you're in\n{STRBUF}?\012Good luck on your\nPOKéMON quest!",
  ["41:4be9"] = "Isso parece real-\nmente difícil.\012Mas, {PLAYER}, sei\nque você está\012mesmo determinado.\nVocê vai ficar\011bem, certo?",
  ["41:4c40"] = "By the way, you've\nsaved up ¥{STRBUF}.\012Do you want to\nkeep on saving?",
  ["41:4c83"] = "É importante guar-\ndar seu dinheiro.",
  ["41:4ca6"] = "Oh, {PLAYER}, você\nnão está guar-\012dando dinheiro.\nVocê gostaria de\011guardar?",
  ["41:4ce2"] = "By the way, you've\nsaved up ¥{STRBUF}.\012Want to start\nsaving again?",
  ["41:4d22"] = "Certo. Eu vou\nguardar o seu\011dinheiro.",
  ["41:4d3c"] = "OK. I'll stop\nsaving your money.",
  ["41:4d5d"] = "{PLAYER}, continue\nassim! Estou tor-\011cendo por você,\011querido!",
  ["41:4d87"] = "Alô?\012Oh, oi, {PLAYER}!\nO PROFESSOR ELM\011não estava espe-\011rando você?",
  ["41:4dba"] = "Alô?\012Oh, oi, {PLAYER}!\nVocê está em uma\012grande missão para\no PROFESSOR ELM?\011Seja bonzinho!",
  ["41:4dfc"] = "Alô?\012Oi, {PLAYER}! Se\nvocê se cansar\012com sua missão,\nvenha à casa,\011querido!",
  ["41:4e3e"] = "Alô?\012…… {PLAYER}?\nEu soube pelo\012PROFESSOR ELM que\nvocê partiu para\011uma lonja viagem.\012Gostaria que você\ntivesse me dito…\012E a respeito do\ndinheiro? Eu devo\011guardá-lo?",
  ["41:4ec4"] = "Good morning!\012This is the POKé-\nMON STORAGE SYSTEM\012ADMINISTRATION\nSERVICE.",
  ["41:4f0d"] = "Good day!\012This is the POKé-\nMON STORAGE SYSTEM\012ADMINISTRATION\nSERVICE.",
  ["41:4f52"] = "Good evening!\012This is the POKé-\nMON STORAGE SYSTEM\012ADMINISTRATION\nSERVICE.",
  ["41:4f9b"] = "Who's calling?\012{PLAYER}, is it?\nHang on a sec…\012……\n……",
  ["41:4fc7"] = "Thanks for\nwaiting!\012{PLAYER}, your BOX\nhas room for {STRBUF}\011more POKéMON.\012Get out there and\nfill it up!",
  ["41:5024"] = "Thanks for\nwaiting!\012{PLAYER}, your BOX\nhas room for only\011{STRBUF} more POKéMON.\012Maybe you should\nswitch your BOX.",
  ["41:508a"] = "Obrigado por\nesperar!\012{PLAYER}, seu BOX\nestá cheio!\012Você terá que\ntrocar os BOXES\012se quiser capturar\nmais #MON.",
  ["41:50ef"] = "Oi, {PLAYER}?\nSou eu, BILL!\012Obrigado por usar\nmeus SISTEMA DE\011ARMAZENAMENTO.\012O último #MON\nque enviou comple-\011tou seu BOX.\012Você terá que\ntrocar os BOXES\012se quiser capturar\nmais #MON.\012Tchau!",
  ["41:5199"] = "Alô, {PLAYER}?\012Tente não sobre-\ncarregá-los.\012Certifique-se de\ncurar seus #-\011MONS se estiverem\011feridos.",
  ["41:51e6"] = "Alô, {PLAYER}?\012Você conheceu o\nSENHOR #MON?\011Ótimo! Volte para\011cá seguramente!",
  ["41:5221"] = "{PLAYER}? Estou bem\nchateado agora.\012Tivemos um #MON\nroubado daqui.\012Como alguém pôde\nfazer isso?",
  ["41:5272"] = "Alô, {PLAYER}?\012Nós estamos checa-\nndo o OVO agora.\012Parece ser um\nOVO #MON.",
  ["41:52b9"] = "Alô, {PLAYER}?\012Você viu meu as-\nsistente? Ele está\012no CENTRO #MON\nna CIDADE VIOLETA.",
  ["41:5305"] = "Alô, {PLAYER}?\012Como está o OVO?\nAlgo mudou?\012Se algo acontecer,\nme liga por favor.",
  ["41:5358"] = "Alô, {PLAYER}?\nComo está o OVO?\012O quê? Ele chocou?\nUau! Que tipo de\011#MON é?\012Por favor venha\nme mostrá-lo\011agora!",
  ["41:53bc"] = "Alô, {PLAYER}?\012Acabei de fazer\numa nova descober-\011ta.\012O tempo que o OVO\nleva para chocar\012depende do #-\nMON.",
  ["41:541f"] = "Alô, {PLAYER}?\012Ainda é um misté-\nrio quais tipos\012de golpes tem um\n#MON chocado.\012Estamos investiga-\nndo isso agora.",
  ["41:5484"] = "Hello, {PLAYER}?\012I discovered an\nodd thing.\012Apparently there's\nsomething called\012POKéRUS that in-\nfects POKéMON.\012Yes, it's like a\nvirus, so it's\011called POKéRUS.\012It multiplies fast\nand infects other\012POKéMON too. But\nthat's all.\012It doesn't seem to\ndo anything, and\012it goes away over\ntime.\012I guess it's\nnothing to worry\011about. Bye!",
  ["41:55b4"] = "A-alô? {PLAYER}?\nIsso é um disas-\011tre!\012Uh, hum, é\nsimplesmente ter-\011rível!\012O que eu devo\nfazer?\012Hm… Oh, não…\012Volte aqui agora\nmesmo!",
  ["41:5624"] = "Alô, {PLAYER}? Nós\ndescobrimos algo\012a respeito do\nOVO!\012Meu assistente se\nencontra no CENTRO\011#MON na CIDADE\011VIOLETA.\012Você poderia falar\011com ele?",
  ["41:56a3"] = "{PLAYER}, como vão\nas coisas?\012Eu liguei porque\nalgo estranho está\012acontecendo com as\ntransmissões de\011rádio!\012Eles estavam fa-\nlando sobre a\011EQUIPE ROCKET.\012{PLAYER}, você sabe\nalguma coisa\011sobre isso?\012Talvez a EQUIPE\nROCKET retornou.\012Não, isso não pode\nser verdade.\012Desculpe-me por\nincomodá-lo!\012Toma cuidado!",
  ["41:57a6"] = "Alô, {PLAYER}?\012Eu tenho algo para\nvocê aqui.\012Você poderia vir\nao meu LABORATÓ-\011RIO?\012Até breve!",
  ["41:5862"] = "Hello. This is\n{STRBUF}…\012Good morning,\n{PLAYER}!",
  ["41:588a"] = "Hello. This is\n{STRBUF}…\012How's it going,\n{PLAYER}?",
  ["41:58b3"] = "Hello. This is\n{STRBUF}…\012Good evening,\n{PLAYER}!",
  ["41:58db"] = "Hi. This is\n{STRBUF}.\012Hi, {PLAYER}!\nGood morning.",
  ["41:5904"] = "Hi. This is\n{STRBUF}.\012Hi, {PLAYER}!\nHow are you?",
  ["41:592c"] = "Hi. This is\n{STRBUF}.\012Hi, {PLAYER}!\nGood evening.",
  ["41:5955"] = "{PLAYER}, good\nmorning!\012It's me, {STRBUF}.\nHow are you doing?",
  ["41:5989"] = "{PLAYER}, howdy!\012It's me, {STRBUF}.\nIsn't it nice out?",
  ["41:59b5"] = "{PLAYER}, good\nevening!\012It's me, {STRBUF}.\nGot a minute?",
  ["41:59e4"] = "Good morning,\n{PLAYER}.\012This is {STRBUF}.\nDid I wake you?",
  ["41:5a15"] = "Hello, {PLAYER}.\012This is {STRBUF}.\nHow are things?",
  ["41:5a3f"] = "Good evening,\n{PLAYER}.\012This is {STRBUF}.\nWere you awake?",
  ["41:5a70"] = "How are your\nPOKéMON doing?\012My {STRBUF}'s\nreally energetic.\011It's a handful!",
  ["41:5ab5"] = "How are your\nPOKéMON doing?\012I always keep my\n{STRBUF} in top\012shape by going to\nPOKéMON CENTERS.",
  ["41:5b0d"] = "My {STRBUF}'s\nlooking awesome.\012I wish I could\nshow you.",
  ["41:5b42"] = "I dressed up my\n{STRBUF}.\012It looks even\ncuter than before.",
  ["41:5b7b"] = "Oh, yeah, I man-\naged to beat a\011tough {STRBUF}.\012I need to make my\nparty stronger.",
  ["41:5bcb"] = "You have to hear\nthis! I battled\012{STRBUF} the\nother day.\012It was easy! I had\na type advantage.",
  ["41:5c27"] = "Hey, listen!\nI almost caught\012{STRBUF} the\nother day.\012Oh, it was soooo\nclose too!",
  ["41:5c76"] = "Guess what happen-\ned the other day.\012I missed catching\n{STRBUF} again.\012Maybe I'm not very\ngood at this…",
  ["41:5cdb"] = "Want to battle?\nIt's not going to\012be a repeat of the\nlast time we met.\012I'll be around\n{STRBUF}.",
  ["41:5d37"] = "Do you want to\nbattle? I'm going\011to win this time!\012I'll be waiting\nfor you around\012{STRBUF}.\nLook for me, OK?",
  ["41:5da0"] = "Hello? This is\n{STRBUF}…\012Uh-oh… You're not\nKAZ! Sorry, wrong\011number.",
  ["41:5de2"] = "Hello, this is\n{STRBUF}. How are\011you doing, AUDREY?\012Huh? {PLAYER}?\nOops! My mistake!",
  ["41:5e2e"] = "See you later!",
  ["41:5e3e"] = "Tchau, tchau!",
  ["41:5e48"] = "You have to see\nthis! It's wild!\012A whole bunch of\n{STRBUF} have\012shown up around\n{STRBUF}!",
  ["41:5e9c"] = "It's amazing!\012On {STRBUF},\n{STRBUF} are\012biting like there\nis no tomorrow.\012{PLAYER}, bring\nyour ROD, buddy!",
  ["41:5efa"] = "A friend just told\nme this.\012He saw a lot of\n{STRBUF} in\011{STRBUF}.\012{PLAYER}, you ought\nto go look.",
  ["41:5f50"] = "They're holding\nthe Bug-Catching\012Contest today at\nthe PARK.\012{PLAYER}, are you\ngoing to go?",
  ["41:5fa4"] = "{PLAYER}, did you\nknow?\012I hear GOLDENROD's\nRADIO TOWER was\012taken over by TEAM\nROCKET.\012But what exactly\nis TEAM ROCKET?",
  ["41:6014"] = "{PLAYER}, did you\nhear the news?\012TEAM ROCKET has\ntaken over the\012RADIO TOWER in\nGOLDENROD CITY.\012I wonder if the\nworkers are OK…",
  ["41:608d"] = "Hi, {PLAYER}!\nOur BICYCLE sales\012have gone through\nthe roof!\012We owe it all to\nyour advertising\012by riding around\non our BICYCLE.\012As our way of say-\ning thanks, please\012keep that BICYCLE.\nThanks again!",
  ["42:4027"] = "Ficamos em guarda\nnessa torre.\012Aqui, expressamos\nnossa gratidão\011em honrar os\011#MON.",
  ["42:4078"] = "O-Obrigado!",
  ["42:4087"] = "Todos seres-vivos\ncoexistem através\011de cooperações.\012Devemos ser sempre\ngratos a isso.",
  ["42:40dc"] = "Só vai obter um HM\nse chegar ao topo\011daqui.",
  ["42:410e"] = "A TORRE BROTINHO\nfoi contruída há\011muito tempo para\011o treinamento\011#MON.",
  ["42:414d"] = "Um BELLSPROUT de\nuns 33 metros…\012Dizem que ele se\ntornou o pilar\011central daqui.",
  ["42:41a1"] = "Vê o pilar se\nmexendo?\012As pessoas estão\ntreinando lá em\011cima.",
  ["42:41da"] = "Uma estátua\n#MON…\012Parece ser bem\nconhecida.",
  ["42:42ad"] = "Quanto mais\nbatalharmos, mais\011a TORRE se fixará.",
  ["42:42e3"] = "Eu lutei duro, mas\nsou muito fraco.",
  ["42:4303"] = "O pilar flexível\nprotege a TORRE,\011até de terremotos.",
  ["42:4345"] = "…Move-se como\nfolhas ao vento…",
  ["42:4365"] = "Oh, sou fraco!",
  ["42:4373"] = "Eu tentei copiar\nos movimentos do\011BELLSPROUT para\011batalhar…\012Mas não treinei o\nbastante.",
  ["42:43cc"] = "Uma estátua\n#MON…\012Parece ser bem\nconhecida.",
  ["42:452b"] = "LÍDER: Você é\ncertamente um\011treinador\011habilidoso.\012Como prometi, aqui\nestá seu HM.\012Mas ouça: Você\ndeve tratar melhor\011seu #MON.\012O modo que batalha\né inadequado.\012Os #MON não\nsão instrumentos\011de guerra…",
  ["42:45f0"] = "…\n…Humph!\012Ele afirma ser o\nLÍDER mas ele é\011fraco.\012Ele é muito\ncertinho.\012Nunca perderei\npara bobos que se\011importam em ser\011legais com os\011#MON.\012Só ligo para\n#MON fortes\011que podem vencer.\012Eu realmente não\nme importo com\011#MON fracos.",
  ["42:46cc"] = "{RIVAL} used an\nESCAPE ROPE!",
  ["42:46e4"] = "Que bom que veio\naqui!\012A TORRE BROTINHO\né um local de\011treinamento.\012As pessoas e os\n#MON testam\011suas habilidades\011para construírem\011um futuro\011brilhante.\012Sou o teste final.\012Deixe-me checar os\nlaços entre seus\011#MON e você!",
  ["42:47b6"] = "Ah, excelente!",
  ["42:47c6"] = "You and your POKé-\nMON should have\012no problem using\nthis move.\012Take this FLASH\nHM.",
  ["42:4817"] = "LUZES iluminam\naté o mais escuro\011dos lugares.\012Mas para usá-lo\nfora de batalha,\011você precisa da\011INSÍGNIA do\011GINÁSIO DE\011VIOLETA.",
  ["42:488c"] = "Espero que tenha\naprendido e que\011cresça na sua\011jornada.",
  ["42:48ba"] = "Treino para achar\na luz nos\011#MON!",
  ["42:48e2"] = "Beaten by a mere\nchild!",
  ["42:48fb"] = "Quando o #MON\nfortalece, o\011treinador melhora\011também.\012Não, espere.\nQuando o treinador\011fortalece, o\011#MON melhora\011também.",
  ["42:4961"] = "Deixe-me ver o\nquanto confia em\011seus #MON.",
  ["42:498b"] = "Sim, você confia\nmesmo!",
  ["42:49a5"] = "Não está longe do\nLÍDER.",
  ["42:49c2"] = "O HM do LÍDER\nilumina até\011lugares totalmente\011escuros.",
  ["42:49f4"] = "É minha cabeça\nque está clara!",
  ["42:4a13"] = "Deixe haver luz em\nsua jornada.",
  ["42:4a38"] = "É uma poderosa\npintura de um\011BELLSPROUT.",
  ["42:4a62"] = "Uma estátua\n#MON…\012Parece ser bem\nconhecida.",
  ["42:4b20"] = "I'm trying to un-\ncover the secret\012of the legendary\nPOKéMON that is\011said to land here.\012They say that the\nPOKéMON has flown\012continuously ever\nsince the TOWER in\011the West burned.\012So, I thought that\nif I had what the\012POKéMON has, it\nwould be attracted\011by that item.\012I think that item\nis probably…\012A RAINBOW WING!\012But, where would\nI find one?",
  ["42:4f24"] = "…… …… ……\012…Oh, it's you.\012You wanted to get\nstronger, so you\012came for the leg-\nendary POKéMON\012that's supposed to\nbe here. That's\011your story, right?\012Well, that's not\ngoing to happen.\012Because I'm going\nto get it!\012I'm going to be\nthe world's great-\011est trainer, so a\011legendary POKéMON\011would be perfect\011for me.\012…Well, anyway,\nI'm getting tired\012of having a wimp\nlike you always\011showing up.",
  ["42:5093"] = "…Humph!\012É por isso que\nodeio batalhar com\011bobos.\012Não há desafio\nalgum.",
  ["42:50da"] = "…Ah, seja o que\nfor.\012Você nunca será\ncapaz de capturar\011um #MON\011lendário mesmo.",
  ["42:5124"] = "…Humph!\012É por isso que\nodeio batalhar com\011bobos.\012É uma perda de\ntempo.",
  ["42:516d"] = "Hey, I'm training\nsecretly here!\012Don't embarrass me\nby looking!",
  ["42:51ac"] = "I burned down to\nwhite ashes…",
  ["42:51cb"] = "I was so into my\ntraining that I\012fell down this\nhole.",
  ["42:5202"] = "My soul is on\nfire. I'll show\012you how hot it\nburns!",
  ["42:5236"] = "Still not hot\nenough…",
  ["42:524d"] = "In the past, there\nwere these POKéMON\012that ran through\ngrass at super-\011high speed.\012They say that they\nrun like the wind.\012If you run into\none in grass, it\011will likely bolt.",
  ["42:552a"] = "Um bando de\nDIGLETT saiu da\011terra!\012Isso foi chocante.",
  ["42:562d"] = "…… …… ……\012It's been a while,\n{PLAYER}.\012…Since I lost to\nyou, I thought\012about what I was\nlacking with my\011POKéMON…\012And we came up\nwith an answer.\012{PLAYER}, now we'll\nshow you!",
  ["42:56c5"] = "…… …… ……\012I thought I raised\nmy POKéMON to be\012the best they\ncould be…\012…But it still \nwasn't enough…",
  ["42:5722"] = "…… …… ……\012…You won, fair\nand square.\012I admit it. But\nthis isn't the\011end.\012I'm going to be\nthe greatest POKé-\011MON trainer ever.\012Because these guys\nare behind me.\012…Listen, {PLAYER}.\012One of these days\nI'm going to prove\012how good I am by\nbeating you.",
  ["42:5808"] = "…… …… ……\012I've repaid my\ndebt to you.\012With my POKéMON,\nI'm going to beat\012the CHAMPION and\nbecome the world's\011greatest trainer.",
  ["42:5a87"] = "… … …\012… Você venceu\nhonestamente.\011Eu admito. Mas\011esse não é o fim.\012Serei o melhor\ntreinador #MON\011que já existiu.\012Porque esses\ncaras estão me\011apoiando…\n \012…Ouça, {PLAYER}.\012Um dia eu vou\nprovar o quanto\011eu sou bom ao\011derrotá-lo.",
  ["42:5b65"] = "…Não pude vencer…\012Dei tudo que\ntinha…\012O que você tem,\ne o que falta em\011mim…\012Estou começando a\nentender o que o\011mestre de dragões\011me disse…",
  ["42:5bf6"] = "…Não desisti de me\ntornar o melhor\011treinador.\012Vou descobrir\nporque eu não\011posso vencer e me\011tornarei mais\011forte…\012Quando o fizer,\nvou desafiá-lo.\012E o derrotarei\nusando todo o meu\011poder.\012…Humph! E você\ncontinue assim\011até lá.",
  ["42:5cd2"] = "…Humph!\012Quando se trata\nde força, nada\011pode me vencer.\012Não preciso de\nmais nada.",
  ["43:4196"] = "Look! Check out my\nbag!\012I printed out my\nfavorites from my\012POKéDEX and stuck\nthem on my bag.",
  ["43:41f1"] = "Essa é uma CARTA\nenviada por minha\011filha.\012Isso me anima.",
  ["43:4228"] = "Preste atenção!\012…Opa, tenho que\nparar de pensar\011como um professor\011o tempo todo.\012Você deve ser um\ntreinador #MON.\012Como está\ntrabalhando duro,\011eu quero que leve\011isso.",
  ["43:42d0"] = "Deixe um #MON\nsegurar essa\011GARRA VELOZ.\012Ele pode atacar\nprimeiro durante\011as batalhas.",
  ["43:4320"] = "I'm playing with\nstickers I printed\011from my POKéDEX.",
  ["43:4352"] = "I get the other\nguy's POKéDEX\011sticker if I win.",
  ["43:437f"] = "Eu caminho pelo\nPARQUE, mas nunca\011vou à grama.\012Os treinadores\nsempre querem\011batalhar…",
  ["43:43d9"] = "PERSIAN: Fufushaa!",
  ["43:43ed"] = "I'm printing out\nmy POKéDEX.\012You can also print\nout stuff like\012MAIL and your PC\nBOXES.",
  ["43:4441"] = "O mundo\ndos #MON é\011profundo.\012Ainda há muitas\ncoisas que não\011sabemos.\012Mas eu sei mais\ndo que você!",
  ["43:44a7"] = "O-o-o-quê?",
  ["43:44b6"] = "There is a lot\nto learn.\012For example…\012There are 50 kinds\nof TM.\012Traded POKéMON\nlevel up faster.",
  ["43:4514"] = "My POKéMON are so\ncute. Let me show\011them off to you.",
  ["43:4547"] = "Maybe I can't beat\nyou in battle…\012But mine look a\nlot nicer.",
  ["43:4584"] = "My friend has a\nMARILL. It's so\012cute! I wish I had\na MARILL.",
  ["43:45c1"] = "We adore our POKé-\nMON, even if they\011dislike us.\012That's what being\na FAN is about.",
  ["43:4611"] = "M-meus #MON!",
  ["43:461d"] = "Perdi a batalha,\nmas meus #MON\011ganharam o prêmio\011por serem mais\011amáveis.",
  ["43:4662"] = "Olá? Por que\nvocê está me\011encarando?\012Oh, uma batalha?",
  ["43:4693"] = "…Hmmm…",
  ["43:469b"] = "The way you were\nlooking, I thought\011you liked me.\012After all, I am\ncute!",
  ["43:46e4"] = "PRAÇA DO DESCANSO\nPARQUE NACIONAL.",
  ["43:4705"] = "Que aviso é este?\012Favor batalhar\nsomente na grama.\012ESCRITÓRIO DO\nCHEFE\012PARQUE NACIONAL.",
  ["43:475a"] = "DICAS DO TREINADOR\012Imprima uma CARTA\nabrindo-a e\011apertando o START.",
  ["43:48e0"] = "DON: I'm going to\nwin! Don't bother\011me.",
  ["43:4907"] = "ED: Meu PARASECT\nfaz #MON\011dormirem com\011ESPOROS.",
  ["43:4937"] = "NICK: Estou\ncriando #MON\011rápidos para\011batalhas.",
  ["43:4960"] = "WILLIAM: Não estou\npreocupado em\011vencer.\012Eu apenas procuro\n#MON raros.",
  ["43:49a9"] = "BENNY: Ssh! Vai\nespantar o\011SCYTHER.\012Depois eu converso\ncom você.",
  ["43:49e6"] = "BARRY: You should\nweaken bug POKéMON\012first, then throw\na POKé BALL.",
  ["43:4a25"] = "CINDY: What is it?\012Do you find it\nfunny that a girl\012is catching bug\nPOKéMON?",
  ["43:4a70"] = "JOSH: Eu coleciono\n#MON insetos\011desde quando eu\011era um bebê.\012Não tem como eu\nperder!",
  ["43:4acd"] = "SAMUEL: Se você\ntiver tempo\011disponível, vá\011achar #MON\011insetos.",
  ["43:4b0c"] = "KIPP: Eu estudei\nmuito sobre\011#MON insetos.\012Eu certamente\nvencerei.",
  ["43:4b4f"] = "PRAÇA DO DESCANSO\nPARQUE NACIONAL.",
  ["43:4b70"] = "Que aviso é este?\012Favor batalhar\nsomente na grama.\012ESCRITÓRIO DO\nCHEFE\012PARQUE NACIONAL.",
  ["43:4bc5"] = "DICAS DO TREINADOR\012Imprima uma CARTA\nabrindo-a e\011apertando o START.",
  ["43:4e1f"] = "Bem-vindo!",
  ["43:4e29"] = "Olá. Perdoe-me,\nmas não estamos\011sorteando passeios\011hoje.",
  ["43:4e62"] = "Oi, está aqui pa-\nra o SHOW DO NÚM-\011ERO SORTUDO?\012Quer que eu olhe\nos NÚMEROS DE\011IDENTIFICAÇÃO de\011seus #MON?\n\012Se tiver sorte,\nganhará um prêmio.",
  ["43:4ee2"] = "This week's ID\nnumber is {STRBUF}.",
  ["43:4f02"] = "Deixe-me ver\nalgum combinou.",
  ["43:4f26"] = "Volte na próxima\nsemana para o\011NÚMERO SORTUDO.",
  ["43:4f5d"] = "Uau! Todos cinco\nnúmeros se combi-\011naram direito!\012Temos um grande\nvencedor!\012Você ganhou uma\nMASTER BOLA!",
  ["43:4fcb"] = "Ei! Os três\núltimos números\011se combinaram!\012Você ganhou o\n2ª prêmio,\011um DIVIDE EXP.!",
  ["43:501e"] = "Ooh, os dois\núltimos números\011se combinaram.\012Você ganhou o\n3ª prêmio,\011um PP MAIS.",
  ["43:5068"] = "Não, nenhum dos\nnúmeros combinou.",
  ["43:508e"] = "Você não tem lugar\npara o prêmio.\012Libere lugar\ne volte depois.",
  ["43:50d5"] = "We have a special\nquiz campaign on\011right now.\012Answer five ques-\ntions correctly to\011win a RADIO CARD.\012Slide it into your\nPOKéGEAR to play\012the radio anytime,\nanywhere.\012Would you like to\ntake the quiz?",
  ["43:519a"] = "Question 1:\012Can the TOWN MAP\nbe displayed on a\011POKéGEAR?",
  ["43:51d1"] = "Correct!\nQuestion 2:\012Can NIDORINA be\nfemale only?",
  ["43:5204"] = "Bull's-eye!\nQuestion 3:\012Does KURT, the\nPOKé BALL crafts-\011man, use APRIKORN?",
  ["43:524d"] = "So far so good!\nQuestion 4:\012MAGIKARP won't\nlearn any TM move?",
  ["43:528b"] = "Wow! Right again!\nHere's the final\011question:\012PROF.OAK'S POKéMON\nTALK is a very\011popular program.\012Is MARIE the co-\nhost of the show?",
  ["43:530b"] = "Bingo! Você conse-\nguiu! Parabéns!\012Aqui está seu,\nprêmio, CARTÃO DE\011RÁDIO.",
  ["43:5350"] = "{PLAYER}'s POKéGEAR\ncan now double as\011a radio!",
  ["43:5375"] = "Sintonize em nos-\nsos programas de\011rádio.",
  ["43:5399"] = "Oh, querido.\nPerdão, mas você\011errou.\012Tente de novo!",
  ["43:53d3"] = "Oh. I see. Please\ntry if you change\011your mind.",
  ["43:5403"] = "O BEN é um DJ\nfabuloso. \012Sua voz doce me\nfaz derreter!",
  ["43:5439"] = "Eu amo a MARY, do\nSHOW #MON.\012Eu só sei do\nque ela parece\011gostar.",
  ["43:5481"] = "Nós finalmente\ndominamos a\011TORRE DE RÁDIO!\012Agora todos expe-\nrimentarão o ver-\012dadeiro terror da\nEQUIPE ROCKET!\012Mostraremos-lhe\ncomo somos assus-\011tadores!",
  ["43:550f"] = "Bem forte! Só de-\nvemos observá-lo…",
  ["43:552f"] = "Você é bem forte.\012Nosso plano pode-\nria ser arruinado.\011Devo avisar aos\011outros…",
  ["43:5574"] = "1F RECEPTION\n2F SALES\0123F PERSONNEL\n4F PRODUCTION\0125F DIRECTOR'S\n   OFFICE",
  ["43:55be"] = "CANAL SORTUDO!\012Ganhe com os núme-\nros dos #MON!\012Troque seus #-\nMONS para ter\011vários NÚMEROS DE\011IDENTIFICAÇÃO!",
  ["43:570e"] = "Você pode ouvir\nrádio em qualquer\011lugar. Sintonize!",
  ["43:5740"] = "As melodias no rá-\ndio fazem meus\011#MON dormirem.",
  ["43:576d"] = "Por que eles que-\nrem dominar a\011TORRE DE RÁDIO?",
  ["43:57a0"] = "JIGGLYPUFF:\nJiggly…",
  ["43:57b5"] = "Perdão. Só pessoas\nautorizadas passam\011daqui.\012Não era assim\nantes.\012Há algo de errado\ncom o DIRETOR…",
  ["43:582e"] = "Ande à vontade\nonde quiser.\012O DIRETOR está\nbem de novo, como\011era antes.",
  ["43:5885"] = "Há 3 anos, a EQUI-\nPE ROCKET foi\011forçada a falir. \012Mas estamos retor-\nnando aqui!",
  ["43:58db"] = "Argh! Não fique\nalegre!",
  ["43:58f1"] = "Não deixaremos\nvocê arruinar nos-\011sos planos de re-\011torno!",
  ["43:5923"] = "Somos a EQUIPE\nROCKET, os explo-\011radores de #-\011MONS!\012Adoramos ser maus!\nAssustou-se?",
  ["43:596a"] = "Você se acha um\nherói?",
  ["43:5983"] = "Nem sempre somos\nmaus. Só fazemos\011tudo que gostamos.",
  ["43:59b7"] = "Ei, ei! Afaste-se\ndo nosso caminho!",
  ["43:59d7"] = "Arggh. Eu desisto.",
  ["43:59ea"] = "Nossos EXECUTIVOS\nestão tentando do-\011minar este lugar.\012Eles têm grandes\nplanos. Quais será\011que são?",
  ["43:5a4e"] = "Hahaha!\012Que chato.\nFoi muito fácil\012dominar este lu-\ngar!\012Venha, mantenha-me\nalegre!",
  ["43:5aa9"] = "Qu-quem é você?",
  ["43:5aba"] = "Você me venceu. Eu\nlembrarei isso!",
  ["43:5ade"] = "2ª ANDAR-LOJAS.",
  ["43:5ae8"] = "SHOW DO CARVALHO\012O Programa Mais\nQuente no Ar!",
  ["43:5b1b"] = "Anywhere, Anytime\nPOKéMON Radio",
  ["43:5cbf"] = "Temos gravações\ndos sons de todos\012#MON encon-\ntrados.\012Devemos ter uns\n200 tipos.",
  ["43:5d20"] = "To trainers, POKé-\nMON are their\011beloved partners.\012It's terrible how\nTEAM ROCKET is\012trying to control\nPOKéMON.",
  ["43:5d89"] = "Transmitimos 24\npor dia programas\012de entretenimento.\012Farei o meu\nmelhor para\011cumprir esta meta!",
  ["43:5df2"] = "O chefe da EQUIPE\nROCKET se trancou.\012Mas o DIRETOR\npode abrir a\011porta.\012Ele está no quinto\nandar.\012Salve-o!",
  ["43:5e69"] = "O DIRETOR está\nseguro?",
  ["43:5e80"] = "Obrigada!\nVocê é meu herói!\012Isso é um pre-\nsente pela minha\011gratidão.",
  ["43:5ebf"] = "É o DIA DE SOL.\nEle melhora golpes\011tipo fogo por um\011tempo.",
  ["43:5efa"] = "Você foi simples-\nmente maravilhoso!",
  ["43:5f16"] = "Estive dando\nordens severas.\012Esmagarei todos\nque desafiarem a\011EQUIPE ROCKET!",
  ["43:5f66"] = "O quê?!",
  ["43:5f6e"] = "Eu falhei no\nmeu dever…\012Eu pagarei\npor isto…",
  ["43:5fa2"] = "Nos sentimos bem\nmandando os #-\011MONS cometerem\011crimes.",
  ["43:5fd2"] = "You're kidding!",
  ["43:5fe2"] = "Sinto-me horrível\nperdendo!\012Droga! Detesto\n#MON inúteis!",
  ["43:601b"] = "Por que a per-\nsiana abriu?\012Você está metido\nnisto?",
  ["43:6060"] = "Estou cansado!",
  ["43:606e"] = "O quê?! Você pas-\nsou por nosso ho-\011mens no SUBTERRÂ-\011NEO?\012Como pôde?",
  ["43:60b2"] = "Um garoto des-\nconhecido aqui?\012Quem é você?",
  ["43:60e1"] = "Tch! Não te\nlevei a sério!",
  ["43:60ff"] = "Bwahahaha…\012Posso enviar\nos sinais fortes\011que preciso aqui.",
  ["43:6142"] = "É o encaixe do\nCARTÃO.",
  ["43:615a"] = "{PLAYER} inseriu\no CARTÃO.",
  ["43:6174"] = "3ª ANDAR-\nFUNCIONÁRIOS.",
  ["43:6182"] = "MÚSICA #MON\ncom o DJ BEN.",
  ["43:62b0"] = "Eu escutei ao rá-\ndio enquanto esta-\011va nas RUÍNAS.\012Havia uma estranha\ntransmissão lá.",
  ["43:6306"] = "MARY: Por quê? Por\nque tenho que pas-\011sar por isso?\012MEOWTH, ajude-me!",
  ["43:6349"] = "MARY: Oh! Você é\nmeu pequeno sal-\011vador!\012Aceitará isso como\nagradecimento?",
  ["43:638d"] = "MARY: É ótimo\npara #MON que\012sabem golpes do\ntipo normal.",
  ["43:63ca"] = "MARY: Sintonize\nno SHOW DO CARVA-\011LHO.",
  ["43:6404"] = "MEOWTH: Meowth…",
  ["43:6415"] = "Você planeja res-\ngatar o DIRETOR?\012Não será possível\nporque eu vou\011derrotar você!",
  ["43:646d"] = "Não!\nInacreditável!",
  ["43:6480"] = "Eu não acredito!\nEu fui derrotado!",
  ["43:64a2"] = "Pare! Sou conheci-\ndo como Fortaleza\011EQUIPE ROCKET!\012Não dê mais\num passo!",
  ["43:64ee"] = "A fortaleza caiu!",
  ["43:6507"] = "Você ganhou meu\nrespeito, então\011lhe darei avisos.\012Ainda não é tar-\nde. Você ainda\011pode voltar.",
  ["43:6562"] = "Se eu acho meus\n#MON bonitos?\012Eu os acharei\nbonitos--\012após derrotar os\nseus!",
  ["43:65b3"] = "Oh, não! Eles são\ntão inúteis!",
  ["43:65cf"] = "Eu amo minha\nbeleza!\012Quem liga para\n#MON?",
  ["43:6600"] = "Excelente.\012Essa TORRE DE\nRÁDIO preencherá\011nosso grande\011projeto.",
  ["43:6641"] = "Hmmm…\012Todos grandes pla-\nnos têm erros.",
  ["43:6669"] = "Você honestamente\ncrê que pode parar\011a EQUIPE ROCKET?",
  ["43:669c"] = "4ª ANDAR-PRODUÇÃO.",
  ["43:66ab"] = "4ª ANDAR-\nESTÚDIO 2.",
  ["43:686a"] = "Você! Você veio\nme resgatar?",
  ["43:6889"] = "Era o que você\nesperava?\012Errado!\nSou um impostor!\012Pretendo ser o\noriginal para\012preparar nossa\ndominação.\012Quer saber onde\no DIRETOR verda-\011deiro está?\012Claro, lhe conta-\nrei. Mas só se\011você me derrotar!",
  ["43:6965"] = "Certo. Contarei-\nlhe onde ele está.",
  ["43:6988"] = "Nós escondemos o\nDIRETOR original\012no DEPÓSITO do\nSUBTERRÂNEO.\012Está no final\ndo SUBTERRÂNEO.\012Mas duvido que\nchegue lá.",
  ["43:6a0d"] = "Hi, little boy.\nRemember me from\012the HIDEOUT in\nMAHOGANY TOWN?\012I lost then, but I\nwon't this time.",
  ["43:6a70"] = "Não pode ser!\012Eu lutei duro,\nmas ainda perdi…",
  ["43:6aaa"] = "{PLAYER}, não é?\012Um pirralho como\nvocê não apreci-\012ará a magnífica\nEQUIPE ROCKET.\012Que pena.\nEu realmente admi-\011ro sua força.",
  ["43:6b23"] = "Oh? Você chegou\naqui?\012Você deve ser\num bom treinador.\012Queremos dominar\nessa ESTAÇÃO DE\012RÁDIO e anunciar\nnosso retorno.\012Isso deve trazer\nde volta nosso\012chefe GIOVANNI de\nseu treinamento\011solo.\012Vamos recuperar\nnossa glória.\012Não deixarei você\ninterferir em nos-\011sos planos.",
  ["43:6c45"] = "Não! Perdôe-me,\nGIOVANNI!",
  ["43:6c60"] = "Como pode?\012Nosso sonhos\nacabaram.\012Não era o adequado\nà tarefa.\012Como GIOVANNI fez\nantes de mim, vou\012finalizar a EQUIPE\nROCKET hoje aqui.\012Adeus.",
  ["43:6d04"] = "DIRETOR: {PLAYER},\nobrigado!\012Suas ações cora-\njosas salvaram a\012nação #MON.\012Sei que não é\nmuito, mas por\011favor aceite.",
  ["43:6d7e"] = "There used to be a\ntower right here\011in GOLDENROD CITY.\012But it was old and\ncreaky.\012So we replaced it\nwith our RADIO\011TOWER.\012During the tear-\ndown, we found\011that at the top.\012I heard that giant\nPOKéMON used to\012fly over GOLDENROD\nin the past.\012Maybe that fell\noff a POKéMON.\012Maybe like the one\nthat appears at\012TIN TOWER in\nECRUTEAK CITY.\012OK, I better go to\nmy OFFICE.",
  ["43:6ee3"] = "There used to be a\ntower right here\011in GOLDENROD CITY.\012But it was old and\ncreaky.\012So we replaced it\nwith our RADIO\011TOWER.\012During the tear-\ndown, we found\011that at the top.\012I heard that giant\nPOKéMON used to\012fly over GOLDENROD\nin the past.\012Maybe that fell\noff a POKéMON.\012Maybe like the one\nthat appears at\012WHIRL ISLANDS near\nCIANWOOD.\012OK, I better go to\nmy OFFICE.",
  ["43:7049"] = "DIRETOR: Olá,\n{PLAYER}!\012Você sabe, eu amo\n#MON.\012Eu construí essa\nTORRE DE RÁDIO\012para mostrar-lhes\nmeu amor. \012Seria bom se as\npessoas gostassem\011de nossos progra-\011mas.",
  ["43:70e3"] = "BEN: Você escuta à\nnossa música?",
  ["43:7105"] = "5ª ANDAR-\nESCRITÓRIO DO\011DIRETOR.",
  ["43:711e"] = "5ª ANDAR-\nESTÚDIO 1.",
  ["44:409f"] = "Hm? That's a POKé-\nDEX, isn't it?\011May I see it?\012There are so many\nkinds of POKéMON.\012Hm? What's this?\012What is this\nPOKéMON?\012It looks like the\nstrange writing on\012the walls of the\nRUINS.\012If those drawings\nare really POKé-\011MON, there should\011be many more.\012I know! Let me up-\ngrade your POKé-\011DEX. Follow me.",
  ["44:42c3"] = "Hmmm… Esse lugar é\nestranho.",
  ["44:42e6"] = "Eu gosto de pensar\naqui.",
  ["44:42fd"] = "PEDRA MISTERIOSA\nPALÁCIO DO PAINEL.",
  ["44:431a"] = "RUÍNAS ALFA\012SEJAM BEM-VINDOS,\nTURISTAS.",
  ["44:433a"] = "RUÍNAS ALFA\nCENTRO DE PESQUISA\012A AUTORIDADE NAS\nRUÍNAS ALFA.",
  ["44:443c"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["44:4461"] = "Um #MON que\nvoava graciosamen-\011te com asas de\011arco-íris.",
  ["44:4516"] = "Welcome to this\nchamber.\012There are sliding\npanels that depict\012a POKéMON drawn by\nthe ancients.\012Slide the panels\naround to form the\011picture.\012To the right is a\ndescription of the\011POKéMON.",
  ["44:45cb"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["44:45f0"] = "Um #MON que se\nesconde no chão\011submarino.\012Olhos em suas\ncostas vasculharam\011a área.",
  ["44:46bb"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["44:46e0"] = "Esse #MON\nagitou o mar ao\011mexer seus dez\011tentáculos.",
  ["44:4795"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["44:47ba"] = "This flying POKé-\nMON attacked its\012prey with saw-like\nfangs.",
  ["44:484a"] = "Há uma presença\nestranha aqui…",
  ["44:486d"] = "Essa é uma grande\nsala, mas não há\011nada aqui.",
  ["44:489b"] = "Esse lugar é muito\nmístico.\012Parece ter forças\ndo além.",
  ["44:48e5"] = "Construções anciãs\nsão geralmente\011tumbas de reis.\012Como as pirâmides,\npor exemplo.",
  ["44:4933"] = "It's a replica of\nan ancient POKé-\011MON.",
  ["44:4b1e"] = "Done!\012I modified your\nPOKéDEX.\012I added an\noptional POKéDEX\012to store UNOWN\ndata.\012It records them in\nthe sequence that\011they were caught.",
  ["44:4ba0"] = "{PLAYER}'s POKéDEX\nwas upgraded.",
  ["44:4bb7"] = "O UNOWN que\ncapturar será\011gravado.\012Cheque para ver\nquantos tipos\011existem.",
  ["44:4c05"] = "Você capturou\ntodas variações de\011UNOWN?\012Que ótima\ndescoberta!\012Vou ajeitar a\nimpressora para\011manusear UNOWNS.\012Sinta-se à vontade\npara usá-la.",
  ["44:4c93"] = "As RUÍNAS têm uns\n1500 anos.\012Mas não se sabe\nporque foram\011construídas--ou\011por quem.",
  ["44:4ceb"] = "Quantos tipos de\n#MON devem ter\011nas RUÍNAS?",
  ["44:4d1e"] = "Surgiram #MON\nnas RUÍNAS? \012Que notícia\nincrível!\012Deveremos checar\nisso.",
  ["44:4d71"] = "Há estranhos\nsímbolos pintados s\011nas paredes das\011RUÍNAS.\012Eles devem ser\na chave para\011desvendar o\011mistério das\011RUÍNAS.",
  ["44:4ded"] = "The strange POKé-\nMON you saw in the\011RUINS?\012They appear to be\nvery much like the\012drawings on the\nwalls there.\012Hmm…\012That must mean\nthere are many\011kinds of them…",
  ["44:4e8b"] = "RUÍNAS ALFA\012Décimo ano de\nexploração.",
  ["44:4eae"] = "Misterioso nome\ndo #MON: UNOWN\012Um total de 26\ntipos achados.",
  ["44:4ee3"] = "Não parece\nfuncionar ainda.",
  ["44:4f02"] = "UNOWNS podem ser\nimprimidos.",
  ["44:4f5b"] = "É uma foto do\ncriador do CENTRO\011DE PESQUISA,\012PROFESSOR\nSILKTREE.",
  ["44:505c"] = "Está indo para\nAZALEA, né?\012Deixe meu #MON\nver se você sabe\011batalhar bem.",
  ["44:50b0"] = "Oh, oh, oh!",
  ["44:50bd"] = "Tudo bem, então!\nJá decidi.\012Não sairei daqui\nenquanto meu\011#MON não\011fortalecer!",
  ["44:5106"] = "Eu viajo bastante\nna procura de\011#MON.\012Está procurando\n#MON também?\012Então você é meu\nrival de coleta!",
  ["44:516c"] = "Ugh. My poor POKé-\nMON…",
  ["44:5182"] = "Toda Sexta, você\npode ouvir rugidos\011de #MON das\011profundezas da\011caverna.",
  ["44:51c4"] = "Uau! Que surpresa!\nNão esperava ver\011alguém aqui!",
  ["44:51ff"] = "Uau! Fui\nderrotado!",
  ["44:521a"] = "Eu ia comprar um\nRABOSLOWPOKE.\012Mas eu fiquei com\npena do pobre\011#MON.",
  ["44:5266"] = "O SUPERSÔNICO do\nZUBAT confunde\011meus #MON.\012Estou me\naborrecendo com\011isso!",
  ["44:52b1"] = "Eu me quemei!",
  ["44:52c0"] = "Nos finais de\nsemana, pode-se\011ouvir estranhos\011rugidos de dentro \012da caverna.",
  ["44:5300"] = "Quando iluminada,\numa caverna não\011é assustadora.\012Se for forte, os\n#MON não se\011assustarão.",
  ["44:5345"] = "LUZES!",
  ["44:534d"] = "É o fogo do meu\n#MON que\011ilumina essa\011caverna.",
  ["44:546e"] = "Já faz tempo que\nnão vejo uma\011pessoa.\012Não seja tímido.\nVamos batalhar!",
  ["44:54bb"] = "Uurggh…",
  ["44:54c4"] = "Estive perdido por\num tempo…\012Não me importo em\nficar aqui, mas\011estou tããão\011faminto!",
  ["44:5510"] = "Quem é você?\nUm visitante!",
  ["44:552e"] = "Hahaha! Você é bem\nagitado!",
  ["44:554c"] = "Eu moro aqui.\012Você pode, também,\nse quiser.\012Há muito espaço,\ncomo pode ver.",
  ["44:559b"] = "Quem está aí?\012Deixe-me sozinho\ncom meu #MON!",
  ["44:55c4"] = "Vá…\nVá embora!",
  ["44:55d2"] = "Só eu e meu\n#MON.\012Eu deliro de\nalegria.",
  ["44:5601"] = "Andei tudo por\naqui para conduzir\011minha pesquisa\011#MON.\012Deixe-me mostrar\nminhas descobertas\011numa batalha\011verdadeira!",
  ["44:5668"] = "Você me mostrou!",
  ["44:5681"] = "Eu devo arrumar\ne divulgar minhas\011descobertas.\012Eu até poderei ser\ntão famoso quanto\011o PROFESSOR ELM!",
  ["44:57bf"] = "Há dois tipos\nde pessoas.\012Aquelas que têm\nestilo, e aquelas\011que não têm.\012Que tipo de pessoa\nvocê é?",
  ["44:5826"] = "Você tem um\nestilo incrível!",
  ["44:5841"] = "O estilo de\nseus #MON é\011colorido e\011ofuscante.\012Eu admito.\012Você só tende\na melhorar!",
  ["44:5895"] = "Estou treinado.\nSe importa em\011batalhar?",
  ["44:58b8"] = "Aww, não! É bom\ndemais para mim.",
  ["44:58d9"] = "Vou treinar\nsozinho até eu\011melhorar.",
  ["44:5907"] = "Se o #MON que\ngosto estivesse\011aqui, eu iria a\011qualquer lugar.\012É o que um\ntreinadodor de\011verdade faz.",
  ["44:5958"] = "Uma vez por\nsemana, um #MON\011vem à beira da\011água.\012Eu queria ver\nesse #MON…",
  ["44:597c"] = "Uma vez por\nsemana, um #MON\011vem à beira da\011água.\012Eu queria ver\nesse #MON…",
  ["44:5b06"] = "KURT: Hey there,\n{PLAYER}!\012The guards up top\ntook off when I\011shouted at them.\012But then I took a\ntumble down the\011WELL.\012I slammed down\nhard on my back,\011so I can't move.\012Rats! If I were\nfit, my POKéMON\012would've punished\nthem…\012Ah, it can't be\nhelped.\012{PLAYER}, show them\nhow gutsy you are\011in my place!",
  ["44:5c1d"] = "KURT: Hora de ir,\n{PLAYER}!\012A EQUIPE ROCKET\nfugiu.\012Minhas costas me-\nlhoraram. Vamos\011sair daqui.",
  ["44:5c78"] = "Droga! Eu estava\nde guarda quando\012um velhote me\ngritou.\012Assustei-me tanto\nque caí aqui.\012Acho que vou\ndescontar minha\011fúria em você!",
  ["44:5d1f"] = "Arrgh! Esse NÃO é\nmeu dia!",
  ["44:5d3b"] = "Claro, estamos\ntirando as caudas\012dos SLOWPOKES e\nas vendendo.\012Tudo que fazemos\né pelo lucro.\012Está certo!\nSomos a EQUIPE\012ROCKET, e faremos\ntudo por dinheiro!",
  ["44:5dde"] = "O que você quer?\012Se perturbar nosso\ntrabalho, não se-\011remos piedosos!",
  ["44:5e23"] = "You did OK today,\nbrat, but wait\011'til next time!",
  ["44:5e54"] = "É, A EQUIPE ROCKET\nquebrou há três\011anos.\012Mas continuamos\nnossas atividades\011no subsolo.\012Agora pode se\ndivertir vendo-nos\011causar problemas!",
  ["44:5ee5"] = "Parar de tirar\nCAUDAS DE\011SLOWPOKE?\012Se obedecermos-\nlhe, a reputação\011da EQUIPE ROCKET\011estará arruinada!",
  ["44:5f37"] = "Simplesmente…\nMuito forte…",
  ["44:5f4a"] = "Precisamos do ca-\npital, mas venden-\011do RABOSLOWPOKE?\012É duro ser um\nSOLDADO ROCKET!",
  ["44:5f9b"] = "Parar de tirar\nCAUDAR?\012Claro, é só\nnos derrotar!",
  ["44:5fd3"] = "Seu fedelho!",
  ["44:5fe5"] = "O RABOSLOWPOKE\ncresce rápido!\012Qual o problema em\nvendê-los?",
  ["44:6023"] = "Um SLOWPOKE com\nsua CAUDA cortada…\012Hã? Tem uma CARTA.\nQuer lê-la?",
  ["44:6061"] = "{PLAYER} leu a\nCARTA.\012Seja boa e cuide\nda casa com o\012Vovô e com o\nSLOWPOKE.\012Com amor, Papai.",
  ["44:60b9"] = "Um SLOWPOKE com\nsua CAUDA cortada…",
  ["44:6182"] = "Preferia cuidar\nde meus bebês!",
  ["44:624a"] = "Serei como o\nSLOWPOKE.\012Esperarei com\npaciência para ver\011um evoluir.",
  ["44:62c5"] = "As pessoas\ntreinam no FAROL.\012Não é facil subir\ndevido a todos os\011treinadores.",
  ["44:631a"] = "In the past, POKé-\nMON used to light\012the sea around\nOLIVINE at night.\012The LIGHTHOUSE was\nmade in honor of\011those POKéMON.",
  ["44:646b"] = "Men of the sea are\nalways spoiling\011for a good fight!",
  ["44:64a1"] = "Urf!\nEu perdi!",
  ["44:64af"] = "What power!\nHow would you like\012to sail the seas\nwith me?",
  ["44:64e9"] = "Hm? Esse não é\nlugar para\011brincar.",
  ["44:650c"] = "Ah! Posso ver\nque você é sério.",
  ["44:652f"] = "Up top is a POKé-\nMON that keeps the\011LIGHTHOUSE lit.\012But I hear that\nit's sick now and\012can't be cured by\nordinary medicine.",
  ["44:6625"] = "Por que está aqui?\nVocê vai ficar\011observando como um\011bobo! Sugiro-lhe\011que saia!",
  ["44:666e"] = "Você está mesmo\npreocupado…",
  ["44:6689"] = "O que quer fazer\nlá em cima?\012Eu quero visitar\no #MON doente,\011mas não consigo\011ir lá…",
  ["44:66dd"] = "Os marinheiros são\ngentis e fortes.\012E você?",
  ["44:670f"] = "Você é gentil e\nforte…",
  ["44:672e"] = "Sempre que volto\nà OLIVINE, eu\011visito o GINÁSIO.\012O tipo de #MON\ndo LÍDER do\011GINÁSIO mudou sem\011eu ser avisado.",
  ["44:679e"] = "I travel the world\nto train my POKé-\011MON. I wish to\011battle with you.",
  ["44:67e1"] = "…poxa… Eu devo\ntreinar mais…",
  ["44:6801"] = "JASMINE usava\n#MON pedra\011como o ONIX.",
  ["44:68bc"] = "A JASMINE deve\nestar muito\011preocupada com o\011#MON aqui.\012Ela nem sorriu\nnesses dias.",
  ["44:690f"] = "Nem eu posso\nsorrir também…",
  ["44:692e"] = "Falando em doença,\neu soube que há\011uma boa FARMÁCIA\011em CIANWOOD.",
  ["44:696f"] = "JASMINE é a LÍDER\ndo GINÁSIO desta\011cidade.\012Quero trazê-la de\nvolta comigo. É\011melhor ninguém\011atrapalhar!",
  ["44:69d5"] = "Argh! Meus\n#MON!",
  ["44:69e6"] = "Certo. Qualquer um\nficaria preocupado\011se seu próprio\011#MON se\011machucasse.\012Vou rezar pelo\n#MON daqui e\011JASMINE poderá\011voltar ao GINÁSIO.",
  ["44:6aef"] = "I wanted to battle\nJASMINE, but she's\012not up to it now.\nSo, how about you?",
  ["44:6b3a"] = "Uau, uau. Você\né devastador!",
  ["44:6b5b"] = "Ser um LÍDER DE\nGINÁSIO não é só\011ser forte.\012Um LÍDER também\nprecisa ter\011compaixão.",
  ["44:6bb0"] = "Estamos bem alto\naqui. Meus\011#MON pássaros\011estão na melhor\011forma!",
  ["44:6beb"] = "Opa… Eles bateram…",
  ["44:6bff"] = "Meus #MON\naprenderam a\011usar o VOAR em\011CIANWOOD.\012Bem, como eu\nperdi, vou voar\011sobre o mar…",
  ["44:6dbd"] = "JASMINE: … Esse\n#MON sempre\011mantém o mar\011iluminado à noite.\012…Mas ele de\nrepente adoeceu…\012Não consegue\nrespirar…\012…Eu sei que há\numa FARMÁCIA\011maravilhosa em\011CIANWOOD…\012Mas é do outro\nlado do mar…\012E eu não posso\ndeixar AMPHY\011desacompanhado…",
  ["44:6ea0"] = "…Posso pedi-lo\npara pegar remédio\011para mim?\012Por favor!",
  ["44:6ed5"] = "JASMINE: …Esse\nremédio curará\011AMPHY?",
  ["44:6eff"] = "{PLAYER} entregou a\nPOÇÃOSECRETA à\011JASMINE.",
  ["44:6f26"] = "JASMINE: …Hm, não\nfique ofendido…\012…AMPHY não vai\naceitar nada de\011alguém que não\011seja eu…",
  ["44:6f80"] = "JASMINE: …\012AMPHY, como está\nse sentindo?",
  ["44:6fa8"] = "JASMINE: …Oh,\nestou tão\011aliviada…\012Isso é explêndido…\012Muito obrigada,\nmuito mesmo.\012Vou retornar ao\nGINÁSIO…",
  ["44:701b"] = "JASMINE: …Eu\nentendo…",
  ["44:702d"] = "…AMPHY, aguente!",
  ["44:703f"] = "AMPHY: …\n…Pa… paloo…",
  ["44:7055"] = "Sua respiração\nestá muito\011forçada…",
  ["44:7079"] = "AMPHY: Palu!\nPalulu!",
  ["45:4126"] = "Arrgh… Você achou\nnossas escadas\011secretas…",
  ["45:414f"] = "Hehe! A experiên-\ncia funcionou\011perfeitamente.\012MAGIKARPS nada\nvalem, mas\011GYARADOS são\011fábricas de\011dinheiro.",
  ["45:41bc"] = "Urrgh…\012O #MON dragão\ndaquele rapaz é\011forte…",
  ["45:41e5"] = "LANCE: DRAGONITE,\nHÍPER RAIO.",
  ["45:4204"] = "O que o trouxe,\n{PLAYER}?\012Como eu pensei,\naquele estranho\011sinal de rádio\011vem daqui.",
  ["45:4259"] = "As escadas ficam\naqui.",
  ["45:4275"] = "LANCE: {PLAYER},\ndevemos nos\011separar para olhar\011esse lugar.\012Irei primeiro.",
  ["45:47cd"] = "Ei! Alerta\nintruso!",
  ["45:47e3"] = "Não… Eu falhei…",
  ["45:47f4"] = "É minha vez!\nNão tem saída!",
  ["45:4814"] = "Há sensores de\nmovimento nas\011estátuas dos\011#MON.\012Continuaremos\naparecendo até\011você achar o\011botão secreto.",
  ["45:4876"] = "Isso já foi um\nesconderijo ninja.\012Há armadilhas\npara confundir\011intrusos como\011você.",
  ["45:48c6"] = "I get it…",
  ["45:48d1"] = "Tudo bem.\n\nFalarei um\011segredo do nosso\011esconderijo.\012Aquela coisa no\nchão acima é\011o painel de\011teletransporte.\011Se pisar nele,\011você voltará para\011a entrada.",
  ["45:4972"] = "Hehe. Sentindo-se\nsortudo, garoto?\011Vá em frente, dê\011outro passo.\011Temos armadilhas\011no chão!",
  ["45:49cd"] = "Kaboom!",
  ["45:49d6"] = "Eu nem sei onde\nas armadilhas\011estão.\012Você terá que\nter coragem e\011caminhar.",
  ["45:4a37"] = "É uma estátua do\nPERSIAN…\012Seus olhos têm um\nbrilho estranho.",
  ["45:4a68"] = "Um botão secreto!\nÉ melhor\011apertá-lo.",
  ["45:4a8b"] = "O botão está\ndesligado.",
  ["45:4f65"] = "Fique bem aí!",
  ["45:4f7b"] = "Não podemos deixar\num pirralho como\011você livre.\012É nocivo ao\norgulho da EQUIPE\011ROCKET, você sabe.\012Mesmo sendo forte,\nvocê não pode nos\011vencer ao mesmo\011tempo.\012Perdão, amigo.\nAgora prepare-se\011para ser lixado.",
  ["45:5044"] = "Ei! Não seja\negoísta. Espalhe\011a diversão.",
  ["45:5075"] = "O quê? Você tem\num cúmplice?\012Aonde está seu\nsenso de honra?\012Como chefe\nprovisório no\011lugar de GIOVANNI,\011vou lhe mostrar\011o quanto é errado\011atrapalhar a\011EQUIPE ROCKET!",
  ["45:5114"] = "Tch, você é\nrealmente forte.\012É uma pena.\012Se você se unisse\nà EQUIPE ROCKET,\011poderia ser um\011EXECUTIVO.",
  ["45:517e"] = "…Esse esconderijo\né feito para…\012Mas tudo bem.\nA experiência da\011transmissão foi um\011sucesso total.\012Não importa o que\nocorrer com esse\011esconderijo agora.\012Temos planos bem\nmaiores.\012Em breve você\napreciará o\011verdadeiro poder\011da EQUIPE ROCKET.\012Divirta-se\nenquanto puder…\012Hahahaha…",
  ["45:5290"] = "LANCE:\nConseguimos. Nós\011derrotamos todos\011os ROCKETS aqui.\012Mas estou\npreocupado com um\011jovem com quem\011batalhei por\011aqui…",
  ["45:5306"] = "Perdão, {PLAYER}.\nEu vi como você\011era bom, por isso\011recuei.\012Agora tudo o que\nresta fazer é\011desligar aquele\011estranho sinal\011de rádio.",
  ["45:5387"] = "It's this machine\nthat's causing all\011the problems.\012I don't see a\nswitch on it…\012We have no choice.\nWe have to make\012all the ELECTRODE\nfaint.\012That should stop\nthis machine from\012transmitting that\nstrange signal.\012It's no fault of\nthe POKéMON, so it\012makes me feel\nguilty.\012{PLAYER}, let's\nsplit the job.",
  ["45:54a2"] = "LANCE: Deixe\nesse lado comigo.",
  ["45:54c1"] = "LANCE: O estranho\nsinal finalmente\011parou.\012O LAGO deve ter\nvoltado ao normal.\012Você é o herói!\nDeixe-me lhe\011agradecer em\011benefício de todos\011#MON.\012Oh, sim. Você deve\nlevar isso.\012Eu achei aqui,\nmas eu não\011necessito disso.",
  ["45:55b0"] = "É o REDEMOINHO.\nEnsine-o a um\011#MON para\011atravessar águas\011selvagens.\012Mas lembre-se\ndisso.\012Você só pode\nusá-lo fora de\011batalhas se tiver\011a INSÍGNIA DO\011GINÁSIO MAHOGANY.",
  ["45:564c"] = "{PLAYER}…\012A jornada para se\ntornar o MESTRE\011#MON é longa e\011difícil.\012Mesmo sabendo\ndisso, pretende\011continuar?\012…\012Entendo. Não, você\nestá certo.\012Se você desistisse\nfacilmente, nunca\011teria perseguido\011esse sonho como\011a coisa mais\011importante.\012Eu espero vê-lo\nnovamente!",
  ["45:574f"] = "LANCE: Você está\nbem?\012Seus #MON\nestão machucados\011e cansados.\012Ei, dê a eles um\npouco do meu\011remédio.",
  ["45:57af"] = "LANCE: {PLAYER},\nvamos dar nosso\011melhor pelos\011#MON.",
  ["45:57da"] = "A porta não abre?\012Seu idiota! Você\nprecisa da senha\011que apenas a\011EQUIPE ROCKET\011sabe.",
  ["45:5831"] = "O quê? Eu perdi?",
  ["45:5840"] = "É, eu sou apenas\num NOVATO. Eu\011não sei a senha.\011Pior para você.",
  ["45:5882"] = "Oh, um garoto?\nEu não gosto\011disso, mas eu devo\011eliminá-lo.",
  ["45:58c1"] = "I knew I'd lose…",
  ["45:58d2"] = "Eu fui derrotado\nna última missão\011por um garoto\011também.\012Quando estávamos\nmaltratando os\011#MON, esse\011garoto de cabelo\011longo e vermelho\011e de olhar ruim\011me derrotou…",
  ["45:5968"] = "Você é um\npestinha!",
  ["45:5981"] = "Grrrr…",
  ["45:5989"] = "É, só o chefe sabe\na senha para\011aquela porta.\012Onde está o\nchefe? Quem sabe?\011Vá procurá-lo\011sozinho.",
  ["45:59f1"] = "A porta está\nfechada…\012Ela precisa de\nsenha para abrir.",
  ["45:5a23"] = "A porta está\nfechada…\012{PLAYER} usou a\nsenha.\012A porta se abriu!",
  ["45:5a5f"] = "É o rádio\ntransmissor que\011está enviando o\011sinal sinistro.\012Está funcionando\ncom capacidade\011total.",
  ["45:5abb"] = "O terrível sinal\ndo transmissor de\011rádio finalmente\011parou.",
  ["45:5e2f"] = "LANCE: Precisamos\nde duas senhas\011para acessar a\011sala do chefe.\012Essas senhas só\nsão sabidas por\011poucos ROCKETS.\012Foi um ROCKET que\nme contou isso.\012{PLAYER}, vamos\npegar as senhas.",
  ["45:5eeb"] = "Urrggh… O cara de\ncapa é incrivel-\011mente forte…",
  ["45:5f1d"] = "…\012Eu não te disse\nque destruiría a\011EQUIPE ROCKET?\012…Conte-me, quem\nera o cara de\011capa que usava\011#MON dragões?\012Meus #MON não\nforam páreos.\012Eu não me importo\nem perder. Eu\011posso derrotá-lo\011se eu capturar\011#MON mais\011fortes.\012O que me incomoda\nfoi o que ele\011disse…\012Contou-me que\neu não amo e\011nem confio em\011meus #MON o\011bastante.\012Estou furioso\npor perder para\011um coração mole\011como ele.\012…Humph! Não tenho\ntempo para gente\011como você!",
  ["45:60b6"] = "O quê? Quem é\nvocê? Esse é o\011escritório do\011nosso líder,\011GIOVANNI.\012Desde quando a\nEQUIPE ROCKET\011faliu, há três\011anos, ele está em\011treinamento.\012Mas sabemos que\nele voltará algum\011dia para reassumir\011o comando.\012Por isso estamos\nem alerta.\012Não deixarei\nninguém perturbar\011esse lugar!",
  ["45:61c7"] = "Eu… Nada pude\nfazer…\012GIOVANNI, por\nfavor me perdoe…",
  ["45:61fe"] = "Não, não posso\ndeixar isso me\011afetar.\012Devo informar\nos outros…",
  ["45:623b"] = "MURKROW: A senha\né…\012GRANDE GIOVANNI.",
  ["45:6265"] = "Se eu sei a\nsenha?\012Talvez.\012Mas nenhum\nfracote vai\011obtê-la!",
  ["45:62a7"] = "Tudo bem. Pare.\nEu lhe contarei.",
  ["45:62c7"] = "A senha para a\nsala do chefe é\011RABO DO SLOWPOKE.\012Mas ela é inútil\nse você não tiver\011duas senhas.",
  ["45:6327"] = "Lá-lá-lá-lá!\012Está me desafiando\npara um batalha?\012Hah! Você é um\ntolo, mas tem\011habilidades!\012Eu gosto disso!\012Se você me\nderrotar, eu lhe\011contarei a senha\011para a sala do\011chefe!",
  ["45:63cd"] = "Lá-lá-lá-lá! Você\né bom!",
  ["45:63ed"] = "Lá-lá-lá-lá!\012A senha para a\nsala do chefe…\012Uh, eu acho que é\nCAUDA DO RATICATE.",
  ["45:6443"] = "Eu trabalhava\npara a SILPH,\011mas agora faço\011pesquisas para a\011EQUIPE ROCKET.\012Um pirralho como\nvocê deve ser\011punido.",
  ["45:64b8"] = "Minha tática\nerrada me puniu…",
  ["45:64d8"] = "A radio signal\nthat drives POKé-\011MON mad…\012My experiment is a\ncomplete success.\012My promotion is\nassured. This loss\012means absolutely\nnothing.",
  ["45:6562"] = "Não me importo se\nnossa experiência\011feriu #MON.",
  ["45:6595"] = "Pensar é o meu\nponto forte, não\011batalhar.",
  ["45:65c0"] = "Se nós acionarmos\no rádio para uma\011transmissão em\011grande escala…\012Esses pensamentos\nme entuasiasmam!",
  ["45:6626"] = "A porta está\nfechada…\012Ela usa duas\nsenhas para abrir.",
  ["45:6659"] = "A porta está\nfechada…\012{PLAYER} usou as\nduas senhas.\012A porta abriu!",
  ["45:6a44"] = "Ah, cara…\nMeu chefe ficará\011irritado…\n \012O FARFETCH'D que\nCORTA árvores para\011fazer carvão\011fugiu.\012Não posso\nprocurá-lo aqui\011na FLORESTA ILEX.\012Ela é grande,\nassustadora e\011escura demais para\011mim.",
  ["45:6b01"] = "Uau! Muito\nobrigado!\012O #MON do meu\nchefe não me\011obedece porque\011eu não tenho\011INSÍGNIAS.",
  ["45:6b57"] = "Este é o #MON\nperdido.",
  ["45:6b6e"] = "FARFETCH'D: FARF!",
  ["45:6b81"] = "Ah! My FARFETCH'D!\012You found it for\nus, kid?\012Without it, we\nwouldn't be able\012to CUT trees for\ncharcoal.\012Thanks, kid!\012Now, how can I\nthank you…\012I know! Here, take\nthis.",
  ["45:6c29"] = "Este é o HM CORTA.\nEnsine ele a um\011#MON para\011cortar árvores.\012Claro, é preciso\nter a INSÍGNIA DO\011GINÁSIO DE AZALEA\011para poder usá-lo.",
  ["45:6ca8"] = "Deseja aprender\ncomo se fabrica\011carvão comigo? \012Você será o\nprimeiro em dez\011anos!",
  ["45:6d03"] = "O que estou\nfazendo?\012Estou sacudindo as\nárvores usando\011CABEÇADA.\012É divertido. Tente\ntambém!",
  ["45:6d55"] = "Balance árvores\nusando CABEÇADA.\012Às vezes caem\n#MON dormindo.",
  ["45:6d97"] = "A FLORESTA ILEX\ntem árvores tão\011grandes que te\011impedem de ver o\011céu.\012Fique atento com\nitens que podem\011ter sido largados.",
  ["45:6e11"] = "SANTUÁRIO DA\nFLORESTA ILEX\012É em homenagem\nao protetor da\011floresta…",
  ["46:42dc"] = "NÃO É PERMITIDO A\nENTRADA A PARTIR\011DESTE PONTO.",
  ["46:4329"] = "…Droga…",
  ["46:4334"] = "Acho que eu devo\nfazer as coisas\011justamente…",
  ["46:4362"] = "Você leva os tipos\nem consideração\011nas batalhas?\012Se você souber das\nvantagens de seu\011tipo, irá melhor\011nas batalhas.",
  ["46:43cb"] = "Ei, ei, ei!",
  ["46:43d8"] = "Eu conheço bem o\ntipo do meu\011#MON.\012Mas eu uso apenas\num tipo de\011#MON.",
  ["46:441a"] = "My POKéMON just\ngot haircuts!\012I'll show you how\nstrong they are!",
  ["46:4458"] = "Aiyeeee!",
  ["46:4462"] = "Seus #MON\ngostarão mais de\011você se lhes\011cortar o cabelo.",
  ["46:449b"] = "Acho que você tem\nalguns #MON\011raros.\012Deixe-me vê-los!",
  ["46:44d7"] = "Gaah! Perdi! Isso\nme enlouquece!",
  ["46:44f9"] = "Are you making a\nPOKéDEX? Here's a\011hot tip.\012The HIKER on ROUTE\n33, ANTHONY, is a\011good guy.\012He'll phone you if\nhe sees any rare\011POKéMON.",
  ["46:457a"] = "A porta está\ntrancada…",
  ["46:458d"] = "A porta está\naberta.",
  ["46:45a0"] = "A CHAVE PORÃO\nabriu a porta.",
  ["46:45c3"] = "Bem-vindo!\012Eu comando o SALÃO\n#MON!\012Sou o mais velho\ne melhor dos\011dois IRMÃOS\011CABELEIREIROS.\012Posso deixar seus\n#MON bonitos\011por apenas ¥500.\012Gostaria que eu\nfizesse isso?",
  ["46:4664"] = "Em qual #MON\neu devo trabalhar?",
  ["46:4682"] = "Certo! Veja-o\nficando bonito!",
  ["46:46a2"] = "Veja! Está pronto!",
  ["46:46b4"] = "Está certo?\nQue vergonha!",
  ["46:46d3"] = "Precisa ter mais\ndinheiro que isso.",
  ["46:46f5"] = "Faço apenas um\ncorte de cabelo ao\011dia.\012Já o fiz hoje.",
  ["46:4726"] = "Bem vindo ao SALÃO\n#MON!\012Sou o mais jovem e\nmenos caro dos\011dois IRMÃOS\011CABELEIREIROS.\012Farei o serviço em\nseu #MON por\011apenas ¥300.\012Então? O que acha?",
  ["46:47bb"] = "Certo, em qual\n#MON devo\011trabalhar?",
  ["46:47d8"] = "Certo! Vou\ndeixá-lo com um\011ótimo visual!",
  ["46:47f4"] = "Está escrito\nBOTÃO 3.",
  ["46:480c"] = "Não? Que\ndesapontamento!",
  ["46:4825"] = "Você está com\npouco dinheiro.",
  ["46:4845"] = "Posso fazer apenas\num corte de cabelo\011ao dia.\012Perdão, mas já o\nfiz hoje.",
  ["46:4889"] = "{STRBUF} parece\nestar mais feliz",
  ["46:48a6"] = "{STRBUF} looks\nhappy.",
  ["46:48b8"] = "{STRBUF} looks\ndelighted!",
  ["46:48ce"] = "Não estamos abertos\nhoje.",
  ["46:48e4"] = "…Por quê…\nPor que perdi?\012Eu reuni os mais\nfortes #MON.\012Eu não facilitei.\012Então por que eu\nperdi?",
  ["46:4e67"] = "Espere!\012Eu o vi,\nentão quis\011interrompê-lo.\012Não preciso de\nvocê no meu pé\011enquanto eu cuido\011da EQUIPE ROCKET…\012Só um segundo.\012Você me derrotou\nantes, não foi?\012Foi pura sorte.\012Mas pagarei meus\ndébitos!",
  ["46:4f27"] = "…Por quê…\nPor que perdi?\012Eu reuni os mais\nfortes #MON.\012Eu não facilitei.\012Então por que eu\nperdi?",
  ["46:4f8c"] = "…Eu não entendo…\012Será que LANCE\ndisse a verdade?\012Que eu não trato\nos #MON\011corretamente?\012Amor…\012Confiança…\012São essas coisas\nque faltam?\012Elas que estão me\nprivando da\011vitória?\012Eu… Eu não\nentendo.\012Mas isso não vai\nacabar aqui.\012Não agora.\nNão devido a isso.\012Não desistirei\ndo meu sonho de\011tornar-me o melhor\011treinador #MON\011do mundo!",
  ["46:50cc"] = "Humph. Esse é meu\nverdadeiro poder,\011bobo.\012A EQUIPE ROCKET\nserá passado.\012E eu vou triturar\no LANCE com meu\011calcanhar.",
  ["46:5140"] = "Fui desafiado para\nbatalhar aqui\011abaixo.\012É perigoso ir lá.\nTenha muito\011cuidado.",
  ["46:519a"] = "Há muitas lojas\nlá embaixo…\012Mas há treinadores\ntambém.\n\012Estou com medo de\nir lá.",
  ["46:51f5"] = "Abra uma persiana\ne a outra fechará.\012Aposto que você\nnão chegará aonde\011quer!",
  ["46:5239"] = "Droga! Fui derro-\ntado pela dúvida!",
  ["46:525a"] = "Estou confuso\ntambém…\nO botão no final é\011o primeiro a ser\011apertado, mas…",
  ["46:52a2"] = "Hahahah!\012As persianas estão\nnos confundindo,\011né?\012Vou te contar um\nsegredo se você\011me derrotar!",
  ["46:52ff"] = "Uwww…\nEu perdi.",
  ["46:5311"] = "Certo. Uma dica!\012Mude a ordem dos\nbotões.\012Isso mudará o\nmodo em que as\011persianas abrem\011e fecham.",
  ["46:5378"] = "Vou roubar seus\nbens!",
  ["46:5391"] = "Piedade!",
  ["46:5399"] = "Steal and sell!\nThat's basic in\011crime, bub!",
  ["46:53c5"] = "Eles abandonaram\nesse projeto antes\011de terminá-lo.\011Estou saqueando as\011sobras.",
  ["46:5416"] = "Sobre o topo!",
  ["46:5425"] = "DEPÓSITO DO\nSUBTERRÂNEO?\012Para que você quer\nir lá?\012Não tem nada lá\nembaixo.",
  ["46:547c"] = "Eu não me importo\nse você está\011perdido.\012Chegou até aqui,\nmas não passa de\011uma vítima!",
  ["46:54c6"] = "Urk! É, acho que\nvocê é legal!",
  ["46:54e9"] = "Você deve ter\ngelo nas veias\011para destruir a\011EQUIPE ROCKET.",
  ["46:551e"] = "Você está perdido?\nNão, é impossível.\012Tu não tens aquela\nface assustada.\012Vou lhe dar\nalgo que vai\011assustá-lo!",
  ["46:5535"] = "Você está perdido?\nNão, é impossível.\012Tu não tens aquela\nface assustada.\012Vou lhe dar\nalgo que vai\011assustá-lo!",
  ["46:55a0"] = "Como pôde?",
  ["46:55b0"] = "Vá aonde quiser!\nSaia daqui!\012Eu nem ligo, viu!",
  ["46:55e1"] = "Está DESLIGADO.\nDeseja LIGÁ-LO?",
  ["46:55f7"] = "Está escrito\nBOTÃO 2.",
  ["46:560d"] = "Está LIGADO.\nDeseja DESLIGÁ-LO?",
  ["46:5624"] = "Está escrito\nBOTÃO 2.",
  ["46:563b"] = "Aqui está!\nTudo pronto.",
  ["46:5795"] = "Eu perco a paixão\npelo trabalho se\011alguém me vê.\012Vamos garoto,\nfora!",
  ["46:57f7"] = "Oohah! Oohah!\012O negócio no chão\né um lixo.\012Pegue-o se\ndesejar!",
  ["46:5840"] = "MACHOKE: Maaacho!",
  ["46:5886"] = "MACHOKE: Maaacho!",
  ["46:59b3"] = "Como chegou aqui?\012Eu achei que isso\nnão aconteceria.\011Vou liquidá-lo.",
  ["46:59fd"] = "He disposed of me…",
  ["46:5a11"] = "A EQUIPE ROCKET\ncontinuará,\011esperando pelo\011retorno do\011GIOVANNI.\012Vamos fazer o que\nfor preciso.",
  ["46:5a70"] = "Você não vai tão\nlonge!\012Não tenho piedade\nde meus inimigos,\011mesmo sendo um\011pirralho.",
  ["46:5abf"] = "Que estouro!",
  ["46:5aca"] = "Eu perdi…\012Perdoe-me\nGIOVANNI!",
  ["46:5af0"] = "Lá-lá-lá-lá!\nLembro-me de você!\012Humilhou-me no\nesconderijo!",
  ["46:5b34"] = "Lá-lá-lá-lá!\nEntão é assim?",
  ["46:5b57"] = "Lá-lá-lá-lá!\nIsso foi uma\011explosão!\012Lembrar-me-ei de\nvocê!",
  ["46:5b8f"] = "DIRETOR: Quem?\nO quê? Você veio\011me resgatar?\012Obrigado!\012A TORRE DE RÁDIO!\012O que está havendo\naqui?\012Dominados pela\nEQUIPE ROCKET?\012Ei. Leve este\nCARTÃO.",
  ["46:5c24"] = "DIRETOR: Use isso\npara abrir as\011persianas no 3ª\011ANDAR.",
  ["46:5c56"] = "I'm begging you to\nhelp.\012There's no telling\nwhat they'll do if\012they control the\ntransmitter.\012They may even be\nable to control\012POKéMON using a\nspecial signal!\012You're the only\none I can call on.\012Please save the\nRADIO TOWER…\012And all the POKé-\nMON nationwide!",
  ["46:5f3d"] = "Hey!\012I am the KARATE\nKING!\012I train alone here\nin the dark!\012You!\nBattle with me!\012Hwaaarggh!",
  ["46:5f99"] = "Waaaarggh!\nFui derrotado!",
  ["46:5fb0"] = "Fui… fui esmagado…\012Meu treinamento\nainda não é o\011bastante.\012Mas derrota é\nderrota.\012Eu admito.\012Como prova de\nque me derrotou,\011lhe darei um raro\011#MON lutador.",
  ["46:6045"] = "{PLAYER} recebeu\nTYROGUE.",
  ["46:605a"] = "TYROGUE é do\ntipo lutador.\012Ele evolui em\n#MON mais\011fortes.\n\012Continue treinando\nduro. Continuarei\011treinando também.\012Adeus!",
  ["46:60cf"] = "Não tem espaço na\nsua equipe!",
  ["46:61cc"] = "The boulder fell\nthrough.",
  ["46:6267"] = "It's immovably\nimbedded in ice.",
  ["47:41c8"] = "Gyaaas!",
  ["47:438b"] = "Uau! Você me\nsurpreendeu!\012Estava de\nÓCULOSESCURO, daí\011nem notei sua\011presença. \012O que eu faço\naqui?\012Ei, não se\npreocupe com isso.\012Eu lhe darei\num par de\011ÓCULOSESCURO,\011então esqueça que\011me viu, certo?",
  ["47:4458"] = "Os ÓCULOSESCURO\najuda golpes do\011tipo escuro.",
  ["47:459c"] = "CLAIR: All right.\nI recognize your\012true power. This\nBADGE is yours.",
  ["47:45e1"] = "{PLAYER} received\nRISINGBADGE.",
  ["47:45fa"] = "RISINGBADGE will\nenable your\012POKéMON to use the\nmove for climbing\011waterfalls.\012Also, all POKéMON\nwill recognize you\012as a trainer and\nobey your every\012command without\nquestion.\012I also want you to\nhave this TM.",
  ["47:46d6"] = "That contains\nDRAGONBREATH.\012No, it doesn't\nhave anything to\011do with my breath.\012If you don't want\nit, you don't have\011to take it.",
  ["47:4754"] = "So, you've col-\nlected all the\011BADGES.\012Your destination\nis the POKéMON\012LEAGUE in INDIGO\nPLATEAU.\012Do you know how to\nget there?\012From here, go to\nNEW BARK TOWN.\012Then SURF east.\nThe route there is\011very tough.\012Don't you dare\nlose at the POKé-\011MON LEAGUE!\012If you do, I'll\nfeel even worse\012about having lost\nto you!",
  ["47:4881"] = "TOCA DO DRAGÃO\012Um santuário em\nhomenagem aos\011#MON dragões\011que supostamente\011viveram na TOCA\011DO DRAGÃO.",
  ["47:48d6"] = "…\nWhat? {PLAYER}?\012…No, I won't\nbattle you now…\012My POKéMON aren't\nready to beat you.\012I can't push them\ntoo hard now.\012I have to be dis-\nciplined to become\012the greatest POKé-\nMON trainer…",
  ["47:4980"] = "…\012Ei…\012Aprenda a ficar\nlonge de mim…",
  ["47:49a6"] = "{PLAYER} found a\n{STRBUF}!",
  ["47:49b8"] = "Mas {PLAYER} não\npode levar mais\011itens.",
  ["48:4101"] = "Wow, your POKéGEAR\nis impressive!\012Did your mom get\nit for you?",
  ["48:413e"] = "Ei, {PLAYER}!",
  ["48:4148"] = "O que você está\ntentando fazer?",
  ["48:4168"] = "É perigoso sair\nsem um #MON,\011não sabia?\012Os #MON\nselvagens aparecem\011na grama a caminho\011da outra cidade.",
  ["48:41ce"] = "Ah! Seu #MON\né amável. Queria\011um para mim!",
  ["48:41fc"] = "Oi, {PLAYER}!\nSaindo de novo?\012Você deve avisar\na sua mãe que\011já vai sair!",
  ["48:4240"] = "Call your mom on\nyour POKéGEAR to\012let her know how\nyou're doing.",
  ["48:427e"] = "Oi, {PLAYER}!\012Eu ouvi dizer\nque encontraram\011novos #MON!",
  ["48:42b0"] = "……\012So this is the\nfamous ELM POKéMON\011LAB…",
  ["48:42d7"] = "…\012Então este é o\nfamoso LABORATÓRIO\011DO PROFESSOR ELM…",
  ["48:42f2"] = "CIDADE NEW BARK\012A Cidade Onde os\nVentos do Recomeço\011Sopram.",
  ["48:4332"] = "CASA DE {PLAYER}.",
  ["48:433c"] = "ELM POKéMON LAB",
  ["48:434a"] = "CASA DO PROFESSOR\nELM.",
  ["48:45ae"] = "Você é um trei-\nnador novato, né?\011Eu sabia!\012Certo! Todos\nsão novatos em\011alguma coisa!\012Se quiser, eu\npossou ensiná-lo\011algumas coisas.",
  ["48:463a"] = "Certo, então!\nSiga-me!",
  ["48:4650"] = "Este é um CENTRO\n#MON. Eles cu-\012ram seus #MON\nnum instante.\012Você confiará mui-\nto neles, então\012é melhor você\naprender sobre\011eles.",
  ["48:46cf"] = "Esta é uma LOJA\n#MON.\012Eles vendem BOLAS\npara pegar #-\012MONS selvagens.\nE outros itens\011úteis.",
  ["48:4724"] = "A ROTA 30 é por\naqui.\012Os Treinadores ba-\ntalharão com seus\012premiados #MON\nlá.",
  ["48:4772"] = "Este é o mar,\ncomo pode ver.\012Alguns #MON\nsó são achados\011na água.",
  ["48:47b7"] = "Ei…\012É minha casa!\nObrigado pela sua\011companhia.\012Deixe-me dar-lhe\num presentinho.",
  ["48:4803"] = "{PLAYER}'s POKéGEAR\nnow has a MAP!",
  ["48:481c"] = "POKéGEAR becomes\nmore useful as you\011add CARDS.\012I wish you luck on\nyour journey!",
  ["48:486a"] = "Oh… É algo que\ngosto de fazer…\012Bom. Venha me ver\nquando quiser.",
  ["48:48ad"] = "…\012You got a POKéMON\nat the LAB.\012What a waste.\nA wimp like you.\012…\012Don't you get what\nI'm saying?\012Well, I too, have\na good POKéMON.\012I'll show you\nwhat I mean!",
  ["48:4942"] = "Hmph. Está feliz\npor vencer?",
  ["48:4961"] = "…\012My name's ???.\012I'm going to be\nthe world's great-\011est POKéMON\011trainer.",
  ["48:49a5"] = "Hmph. Foi uma\nperca de tempo.",
  ["48:49c7"] = "…\012My name's ???.\012I'm going to be\nthe world's great-\011est POKéMON\011trainer.",
  ["48:4a0b"] = "Did you talk to\nthe old man by the\011POKéMON CENTER?\012He'll put a MAP of\nJOHTO on your\011POKéGEAR.",
  ["48:4a63"] = "Quando se está com\n#MON, ir a\011qualquer lugar é\011divertido.",
  ["48:4a91"] = "A casa do SENHOR\n#MON é mais\011acima.",
  ["48:4abc"] = "Eu batalhei com\nos treinadores na\011rota.\012Meu #MON per-\ndeu. Eles estão\011feridos.\012Eu devo levá-los\nao CENTRO #MON.",
  ["48:4b21"] = "Um #MON que\ncapturei tinha\011um item.\012Acho que é a\nÁGUA MÍSTICA.\012Não preciso dela,\nvocê a quer?",
  ["48:4b7c"] = "De volta a pesca\npara mim, então.",
  ["48:4b9b"] = "CIDADE CHERRYGROVE\012A Cidade das Lin-\ndas e Perfumadas\011Flores.",
  ["48:4bd0"] = "CASA DO GUIA.",
  ["48:4d29"] = "Hello!\nYou are trainer?\012Battle GYM LEADER,\nwin you did?",
  ["48:4d62"] = "Ooh, la la!\nIsso é ótimo!",
  ["48:4d81"] = "É isso? Então\nvocê deve estudar!\011Siga-me!",
  ["48:4daf"] = "Ei, eu sou um\nprofessor. É bom\011que estude aqui!",
  ["48:4ddf"] = "Dizem que aparecem\nfantasmas na TORRE\011BROTINHO.\012E golpes #MON\nnormais não fazem\012efeitos neles.",
  ["48:4e49"] = "Ei, você é um\ntreinador POKÉMON?\012Se derrotar o LÍ-\nDER DO GINÁSIO\012daqui, você estará\nbem preparado!",
  ["48:4ea5"] = "FALKNER, do GINÁ-\nSIO #MON DE\012VIOLETA, é um bom\ntreinador!\012Ele herdou o giná-\nsio de seu pai\012e está fazendo um\nbom serviço com\011ele.",
  ["48:4f1b"] = "Eu vi uma árvore\nlouca acima!\012Se tocá-la, ela\nse mexe e dança!\012Legal!",
  ["48:4f68"] = "CIDADE VIOLETA\012A Cidade dos Sen-\ntimentos Nostálgi-\011cos.",
  ["48:4f92"] = "CIDADE VIOLETA\012LÍDER DO GINÁSIO\nPOKÉMON: FALKNER\012O Elegante Mestre\ndos #MON Aves.",
  ["48:4fda"] = "TORRE BROTINHO\012A Experiência do\nRumo #MON.",
  ["48:5003"] = "ACADEMIA POKéMON\nDO EARLY.",
  ["48:51e7"] = "…Diga-me algo.\012É verdade que\na EQUIPE ROCKET\011voltou?\012O quê? Você os\nderrotou? Hah! Não\011minta.\012Não é piada?\nEntão vamos ver o\011quanto você é bom.",
  ["48:5280"] = "… Hmph! #MON\ninúteis!\012Você, escute. Só\nvenceu porque meus\012#MON são\nfracos.",
  ["48:52cd"] = "Odeio a fraqueza.\012#MON, trei-\nnadores. Não\011importa quem ou o\011quê. \012Eu serei forte\ne exterminarei a\011fraqueza.\012Isso vale para\na EQUIPE ROCKET\011também.\012Eles são fortes\nem grupo.\012Mas sozinhos,\neles são fracotes.\012Eu os odeio.\012E você saia do\nmeu caminho. Um\012fracote como você\né só distração.",
  ["48:53f5"] = "…Hmph! Sabia\nque você mentiu!",
  ["48:5415"] = "É inseguro ir lá,\nentão estou em\011guarda.\012Não sou um Bom\nSamaritano?",
  ["48:5461"] = "Você conhece o\nRABOSLOWPOKE?\011Soube que é ótimo.\012Não se alegra por\neu te contar isso.",
  ["48:54b5"] = "Os SLOWPOKES sumi-\nram da cidade…\012Soube que estão\nvendendo suas CAU-\011DAS por aí.",
  ["48:550d"] = "Os SLOWPOKES vol-\ntaram.\012Como os conheço,\nsei que não passe-\012avam por aí.",
  ["48:5568"] = "Você veio pedir\na KURT para fa-\011zer BOLAS?\012Muita gente só\nfaz isto.",
  ["48:55b4"] = "Atravesse AZALEA\ne vai estar na\011FLORESTA ILEX.\012Mas as árvores\nmagrelas impos-\012sibilitam a pas-\nsagem.\012O #MON DO HO-\nMEM DO CARVÃO pode\011cortá-las.",
  ["48:564a"] = "SLOWPOKE: …\012…… …… ……",
  ["48:565d"] = "…… ……Yawn?",
  ["48:5679"] = "CIDADE AZALEA\012Onde Pessoas e\n#MON Vivem em\011Ótima Harmonia.",
  ["48:56b2"] = "CASA DO KURT.",
  ["48:56c0"] = "CIDADE AZALEA\012LÍDER DO GINÁSIO\nPOKÉMON: BUGSY\012A Enciclopédia\n#MON Ambulante.",
  ["48:5706"] = "POÇO SLOWPOKE\012Também chamado\nde POÇO QUE FAZ\011CHOVER. \012Os habitantes\nacreditam que o\011bocejo do SLOWPOKE\011chama a chuva.\012Os registros indi-\ncam que o bocejo\011do SLOWPOKE acabou\012com uma seca há\n400 anos.",
  ["48:57ac"] = "ESTUFA DE CARVÃO.",
  ["48:57bb"] = "FLORESTA ILEX\012Entre pelo\nportão.",
  ["48:5936"] = "Você cruzou o mar\npara chegar aqui?\012Deve ter sido\ndifícil.\012Seria bem mais\nfácil se seu\012#MON soubesse\ncomo VOAR…",
  ["48:59a8"] = "Mas você não pode\nusar o VOAR sem\011a INSÍGNIA DO GI-\011NÁSIO daqui.\012Se derrotar o LÍ-\nDER DO GINÁSIO,\011venha me ver.\012Eu terei um bom\npresente para\011você.",
  ["48:5a28"] = "É a INSÍGNIA DO\nGINÁSIO CIANWOOD!\012Você deve levar\neste HM.",
  ["48:5a62"] = "Ensine VOAR aos\nseus #MON.\012Você poderá VOAR\nrapidamente para\012qualquer lugar\nvisitado.",
  ["48:5abc"] = "Meu marido perdeu\npara você, então\011ele deve treinar\011mais.\012É bom, pois\nele estava ficando\011gordinho.",
  ["48:5b24"] = "Se usar o VOAR,\nvocê poderá voltar\012à OLIVINE rapi-\ndamente.",
  ["48:5b5e"] = "As Pedras ao norte\nda cidade podem\011ser quebradas.\012Podem estar escon-\ndendo algo.\012Seu #MON pode-\nria usar o ESMAGA-\011PEDRAS para quebrá-\011las.",
  ["48:5bd9"] = "CHUCK, the GYM\nLEADER, spars with\012his fighting POKé-\nMON.",
  ["48:5c78"] = "CIDADE CIANWOOD\012Um Porto Cercado\npor Grandes Mares.",
  ["48:5ca7"] = "CIDADE CIANWOOD\n\012LÍDER DO GINÁSIO\n#MON: CHUCK\012Sua Incrível Força\nFaz O Que ele \011Fala.",
  ["48:5cee"] = "500 Anos de\nTradição\012FARMÁCIA DA CIDADE\nCIANWOOD\012Estamos Aguardando\nSeus Pedidos Médi-\011cos.",
  ["48:5d3d"] = "CIDADE CIANWOOD\nESTÚDIO FOTOGRÁ-\011FICO\012Tire uma Foto de\nRecordação!",
  ["48:5ec6"] = "Eles fizeram a\nnova TORRE DE\011RÁDIO para subs-\012tituir a velha em\nruínas.",
  ["48:5f06"] = "Eu sei que há uma\nnova LOJA DE BICI-\011CLETAS, mas não\012consigo achá-la.",
  ["48:5f43"] = "Aquele homem de\npreto está vesti-\012do como membro\nda EQUIPE ROCKET?\012Que tolo!",
  ["48:5f8a"] = "Aquele homem de\npreto é mesmo da\012EQUIPE ROCKET?\nNão acredito!",
  ["48:5fd0"] = "The RADIO TOWER in\nGOLDENROD CITY is\011a landmark.\012They're running a\npromotional cam- \011paign right now.\012They'll modify\nyour POKéGEAR,\012so it can also\nserve as a radio.",
  ["48:6071"] = "Oh, your POKéGEAR\nworks as a radio!",
  ["48:6093"] = "E-he-he-he…\012Encrenquei-me por\njogar no porão\012da LOJA DE DEPAR-\nTAMENTOS.",
  ["48:60e0"] = "O homem naquela\ncasa avalia os\011nomes de seus\011#MON.\012Pode até renomeá-\nlos.",
  ["48:612c"] = "Uau! Que cidade\ngrande! Nem\012sei o lugar das\ncoisas.",
  ["48:616a"] = "Então essa é a\nTORRE DE RÁDIO…",
  ["48:6187"] = "O que você quer,\nsua peste? Some!",
  ["48:61ab"] = "Sai do caminho!",
  ["48:61ca"] = "Dominar a TORRE\nDE RÁDIO…\012O quê? Não é\nda sua conta!",
  ["48:6207"] = "#MON? Não são\nnada mais que\012fábricas de di-\nnheiro!",
  ["48:623f"] = "Nosso sonho se\nrealizará…\012Foi uma grande\nesforço…",
  ["48:627c"] = "Ei, pirralho!\nVocê não é daqui!\011Saia daqui!",
  ["48:62a8"] = "Experimente o\nverdadeiro terror\011da EQUIPE ROCKET!",
  ["48:62d4"] = "ESTAÇÃO DA CIDADE\nGOLDENROD.",
  ["48:62ec"] = "TORRE DE RÁDIO DA\nCIDADE GOLDENROD.",
  ["48:6308"] = "Seleção Completa\nde Produtos #-\011MON!\012LOJA DE DEPARTA-\nMENTOS DA CIDADE\011GOLDENROD.",
  ["48:6341"] = "CIDADE GOLDENROD\012LÍDER DO GINÁSIO\nPOKÉMON: WHITNEY\012A Garota Incri-\nvelmente Linda!",
  ["48:6386"] = "CIDADE GOLDENROD\012A Festiva Cidade\nCharmosa.",
  ["48:63b8"] = "O Mundo é\nredondo!\011LOJA DE BICI-\nCLETAS.",
  ["48:63de"] = "O Seu Lazer!\012CASA DE JOGOS DA\nCIDADE GOLDENROD.",
  ["48:640b"] = "AVALIADOR DE NOMES\012Avalie o Apelido\nde seu #MON.",
  ["48:6435"] = "SUBTERRÂNEO\nENTRADA.",
  ["48:644b"] = "SUBTERRÂNEO\nENTRADA.",
  ["49:40d7"] = "…\012You again?\012There's no need to\npanic. I don't\012bother with wimps\nlike you.\012Speaking of weak-\nlings, the city's\012GYM LEADER isn't\nhere.\012Supposedly taking\ncare of a sick\012POKéMON at the\nLIGHTHOUSE.\012Humph! Boo-hoo!\nJust let sick\011POKéMON go!\012A POKéMON that\ncan't battle is\011worthless!\012Why don't you go\ntrain at the\011LIGHTHOUSE?\012Who knows. It may\nmake you a bit\011less weak!",
  ["49:4235"] = "Estradas escuras\nsão perigosas à\011noite.\012Mas na escuridão\nda noite, o\012mar é ainda mais\ntraiçoeiro!\012Sem a ajuda do\nguia do FAROL,\012nenhum navio pode\nnavegar.",
  ["49:42e1"] = "That thing you\nhave--it's a POKé-\011GEAR, right? Wow,\011that's cool.",
  ["49:431e"] = "Wow, you have a\nPOKéDEX!\012That is just so\nawesome.",
  ["49:434e"] = "Hello, laddie!\nThe sea is sweet!\012Sing with me! \nYo-ho! Blow the\011man down!…",
  ["49:439a"] = "CIDADE OLIVINE\012O Porto Mais\nPerto das Terras\011Isoladas.",
  ["49:43ca"] = "PORTO OLIVINE\nPIER DO NAVIO\011VELOZ.",
  ["49:43e7"] = "CIDADE OLIVINE\012LÍDER DO GINÁSIO\n#MON: JASMINE\012A Garota da De-\nfesa de Aço.",
  ["49:442a"] = "FAROL DE OLIVINE\nTambém conhecido\011como FAROL DA LUZ.",
  ["49:4604"] = "ECRUTEAK possuía\nduas torres:\012uma à leste e\ne outra a oeste.",
  ["49:4646"] = "Ah, youngster.\nHave you learned\012to dance like the\nKIMONO GIRLS?\012If you go to their\nDANCE THEATER, an\012odd old man will\ngive you something\011nice, I hear.",
  ["49:46de"] = "Eu vou praticar no\nTEATRO DE DANÇA.\012Se importa de me\nacompanhar?",
  ["49:471d"] = "That used to be a\nmuch taller tower,\012but it burned down\nin a fire.",
  ["49:4761"] = "Três grandes #-\nMONS fugiram em\011diferentes dire-\011ções.\012Onde estavam?",
  ["49:47a4"] = "Soube de um boato\nsobre o FAROL DE\011OLIVINE.\012O #MON que\nserve como guia\012adoeceu.\nParece que eles\011estão encrencados.",
  ["49:481d"] = "O #MON no FAROL\nDE OLIVINE foi cu-\011rado.\012Os Barcos podem\nnavegar pelo mar à\011noite facilmente.",
  ["49:487e"] = "Soube que #MON\nestão tumultuando\012o LAGO DA RAIVA.\nQueria ver isto.",
  ["49:48c3"] = "CIDADE ECRUTEAK\nA Cidade Histórica\012Onde o Passado en-\ncontra o Presente.",
  ["49:4905"] = "TIN TOWER\012A legendary POKé-\nMON is said to\011roost here.",
  ["49:493a"] = "CIDADE ECRUTEAK\012LÍDER DO GINÁSIO\n#MON: MORTY\012O Místico Vidente\ndo Futuro.",
  ["49:497e"] = "TEATRO DE DANÇA\nDE ECRUTEAK.",
  ["49:4996"] = "TORRE QUEIMADA\012Foi destruída por\num fogo misteri-\011oso.\012Por favor afaste-\nse, pois é insegu-\011ro.",
  ["49:4b65"] = "Hi, sonny boy! I\nsee you're new in\011MAHOGANY TOWN.\012Since you're new,\nyou should try a\012yummy RAGECANDY-\nBAR!\012Right now, it can\nbe yours for just\011¥300! Want one?",
  ["49:4c03"] = "Bom! Aprecie-o!",
  ["49:4c14"] = "You don't have\nenough money.",
  ["49:4c31"] = "Oh, fine then…",
  ["49:4c41"] = "Você não tem\nespaço para isso.",
  ["49:4c5f"] = "RAGECANDYBAR's\nsold out.\012I'm packing up.\nDon't bother me,\011sonny boy.",
  ["49:4ca2"] = "Você está aqui\npara ver o ritual\011dos GYARADOS no\011LAGO?",
  ["49:4cda"] = "AS MAGIKARPS\nretornaram ao LAGO\011DA RAIVA.\012Isso deve ser uma\nboa notícia para\011os pescadores de\011lá.",
  ["49:4d33"] = "Como chegou tão\nlonge, dedique-se\011para passear um\011pouco.\012Você deveria ir\nao norte e\011examinar o LAGO\011DA RAIVA agora.",
  ["49:4daf"] = "Visite a Loja da\nVovó. Ela vende\011coisas que ninguém\011tem.",
  ["49:4deb"] = "CIDADE MAHOGANY\012Bem-vindo ao Lar\ndo Ninja.",
  ["49:4e1b"] = "Enquanto visita\na CIDADE MAHOGANY,\011prove o DOCE\011RAIVA!",
  ["49:4e4e"] = "CIDADE MAHOGANY\012LÍDER DO GINÁSIO\n#MON: PRYCE\012O Professor da\nDureza do Inverno.",
  ["49:5063"] = "Esse lago é cheio\nde GYARADOS e\011nada mais…\012Então as MAGIKARPS\nestão sendo\011forçadas a\011evoluir…",
  ["49:50c0"] = "Você veio aqui\ndevido aos boatos?\012Você é {PLAYER}?\nEu sou LANCE, um\011treinador como\011você.\012Eu ouvi boatos,\nentão eu vim\011investigar…\012Eu vi o modo como\nvocê batalhou\011anteriormente,\011{PLAYER}.\012Posso dizer\nque você é\011um treinador\011com grandes\011habilidades.\012Se não se\nimportar, poderia\011me ajudar a\011investigar?",
  ["49:51d2"] = "LANCE: Excelente!\012Parece que as\nMAGIKARPS do LAGO\011estão sendo\011forçadas a\011evoluir.\012Uma misteriosa\ntransmissão de\011rádio vinda de\011MAHOGANY é a\011causa.\012Estarei te\nesperando,\011{PLAYER}.",
  ["49:527d"] = "Oh… Bem, se você\nmudar de idéia,\011venha me ajudar.",
  ["49:52b1"] = "LANCE: Hm? Você\nvai me ajudar?",
  ["49:52d7"] = "GYARADOS: Gyashaa!",
  ["49:52eb"] = "{PLAYER} obtained a\nRED SCALE.",
  ["49:5304"] = "Os GYARADOS estão\nnervosos!\012Isso é um mau\nsinal!",
  ["49:532d"] = "Haha! As MAGIKARPS\nestão mordendo!",
  ["49:5350"] = "Eu soube que esse\nlago foi feito\011por rituais de\011GYARADOS.\012Será que tem\nalguma conexão com\011seus poderes\011destrutivos?",
  ["49:53c7"] = "Meus olhos estão\nme enganando? Eu\011vi um GYARADOS\011vermelho no LAGO…\012Mas pensei que os\nGYARADOS eram\011azuis?",
  ["49:542e"] = "Deixe-me batalhar\ncom o #MON que\011acabei de pegar!",
  ["49:545a"] = "I might be an ex-\npert angler, but\012I stink as a POKé-\nMON trainer…",
  ["49:549b"] = "Não perderei\ncomo pescador!\011Pego #MON o\011dia todo.",
  ["49:54cc"] = "No matter what I\ndo, all I catch\012are the same POKé-\nMON…",
  ["49:5503"] = "Minha linha está\nenrolada…",
  ["49:551d"] = "Por que não\ncapturo um bom\011#MON?",
  ["49:553e"] = "Se um treinador\nver outro\011treinador, ele\011tem que fazer um\011desafio.\012Esse é nosso\ndestino.",
  ["49:5594"] = "Nossa…\nBoa batalha.",
  ["49:55a8"] = "Os #MON e\nseus treinadores\011ficam poderosos\011após constantes\011batalhas.",
  ["49:55eb"] = "O que ocorreu ao\nGYARADOS vermelho?\012Ele sumiu?\012Oh, droga. Eu vim\naqui para nada?\012Já sei--vamos\nbatalhar!",
  ["49:5651"] = "Boa jogada!",
  ["49:565e"] = "Falando nisso, eu\nvi uma BUTTERFREE\011rosa.",
  ["49:5690"] = "WESLEY: Bem, como\nvai você?\012Como sabe, hoje\né Quarta-feira.\011Sou WESLEY da\011Quarta.",
  ["49:56e9"] = "Que bom\nconhecê-lo. Leve\011Essa lembrança.",
  ["49:5717"] = "WESLEY: A\nFAIXAPRETA melhora\011os golpes do tipo\011lutador.",
  ["49:5750"] = "WESLEY: Como você\nme achou, você\011deve ter\011conhecidos meus\011irmãos.\012Ou você teve pura\nsorte?",
  ["49:57b5"] = "WESLEY: Hoje não\né Quarta. Isso é\011tão ruim.",
  ["49:57e3"] = "LAGO DA RAIVA,\ntambém chamado de\011LAGO DO GYARADOS.",
  ["49:580f"] = "CASA DOS\nPESCADORES.",
  ["49:5994"] = "I am sorry.\012Our GYM LEADER is\ntraining in the\011cave behind here.\012I have no idea\nwhen our LEADER\011will return.",
  ["49:5a01"] = "Our GYM LEADER is\nwaiting for you.\012However, it would\nbe impossible for\012a run-of-the-mill\ntrainer to win.",
  ["49:5a6b"] = "You defeated our\nGYM LEADER?\011That's amazing!\012With your power,\nyou should succeed\012in the POKéMON\nLEAGUE.",
  ["49:5ad0"] = "Only dragon users\nare permitted to\012train here.\nPlease leave.",
  ["49:5b0e"] = "Since CLAIR, the\ndragon master, has\012allowed it, you\nmay enter.",
  ["49:5b4e"] = "Meu rádio pifou?\nUltimanente, só\nrecebo esse sinal\011estranho.",
  ["49:5b87"] = "Aroo! Vozes em\nminha cabeça!\012Hã? Estou\nescutando ao meu\011rádio!",
  ["49:5bc1"] = "Você vai fazer\nseus #MON\011esquecer uns\011golpes?",
  ["49:5bf5"] = "I'm going to be a\ndragon user like\011CLAIR.",
  ["49:5c1f"] = "SANTOS: …\012É Sábado…\012Sou SANTOS do\nSábado…",
  ["49:5c4f"] = "Você pode levar\nisso…",
  ["49:5c63"] = "SANTOS: …\012TALÃO MAGIA…\012Fortalece golpes\nfantasmas…\012Ele vai\nassustá-lo…",
  ["49:5cae"] = "SANTOS: …\012Vou vê-lo de novo\nem outro Sábado…\012Não terei\nmais presentes…",
  ["49:5cf8"] = "SANTOS: Hoje não\né Sábado…",
  ["49:5d16"] = "Uau, você\natravessou o\011CAMINHO DE GELO.\011Nossa, deve ser um\011ótimo treinador!",
  ["49:5d5f"] = "VILA BLACKTHORN\012Um quieto lugar\nmontanhoso.",
  ["49:5d89"] = "VILA BLACKTHORN\012LÍDER DO GINÁSIO\n#MON: CLAIR.\012A abençoada\nusuária de\011#MON dragões.",
  ["49:5dd1"] = "CASA DO APAGADOR\nDE GOLPES.",
  ["49:5de7"] = "DRAGON'S DEN\nAHEAD",
  ["49:5dfb"] = "DICAS DO TREINADOR\012Um #MON\nsegurando um GRÃO\011MILAGRE se curará\011de todo problema\011de estado.",
  ["49:5f27"] = "MONTE PRATA.",
  ["4a:4175"] = "Estou fazendo\nmeus últimos\011preparos para a\011LIGA #MON.",
  ["4a:41ab"] = "Fui mal!",
  ["4a:41b7"] = "Vai ser difícil\nvencer na LIGA\011#MON.\012Preciso treinar um\npouco mais.\012Eu soube que a\nELITE QUATRO DA\011LIGA é mais\011difícil que os\011LÍDERES DE\011GINÁSIO.",
  ["4a:4246"] = "Ao passar por\nbatalhas difíceis,\011você ganha força.",
  ["4a:4276"] = "Gaah! Viver é\nmais difícil!",
  ["4a:4293"] = "Para chegar a\nLIGA #MON, você\011tem que cruzar a\011ROTA DA VITÓRIA.\012Mas a ROTA DA\nVITÓRIA é dura.\012Praticamente\nninguém vai lá!",
  ["4a:430b"] = "Como você chegou\ntão longe, deve\011ser muito bom.\012Vou dar o meu\nmáximo nessa\011batalha!",
  ["4a:436c"] = "Não! Não acredito\nnisso!",
  ["4a:4386"] = "Eu derrotei\noito LÍDERES DE\011GINÁSIO, logo\011estava confiante.\012Terei que me\nesforçar mais na\011próxima.",
  ["4a:43e5"] = "I lost to a train-\ner named {RIVAL}.\012He was really\nstrong, but…\012It was as if he\nabsolutely had to\011win at any cost.\012I felt sorry for\nhis POKéMON.",
  ["4a:446e"] = "#MON não são\narmas bélicas.",
  ["4a:4488"] = "#MON são\nparceiros de longa\011data e sem preço.",
  ["4a:44b3"] = "Uau, olhe todas\nessas INSÍGNIAS.\012Estou admirado!\n \012Mas só colecioná-\nlas não o satis-\011faz, certo?",
  ["4a:4519"] = "Boa batalha!",
  ["4a:4527"] = "Pessoas e #MON\ncrescem com suas\011experiências.\012Não seja\num preguiçoso\011fatalista.",
  ["4a:4573"] = "Sinto-me ótimo\nhoje!\012Sinto que posso\naté vencer o\011CAMPEÃO DA LIGA!",
  ["4a:45bc"] = "Não! Não nessa\nbatalha!",
  ["4a:45d5"] = "Como na pesca,\ntudo acaba com os\011#MON quando\011você desiste.",
  ["4a:4613"] = "ROTA 26\012LIGA #MON\nPORTÃO DE\011RECEPÇÃO.",
  ["4a:486a"] = "Ei!",
  ["4a:4870"] = "Do you know what\nyou just did?\012You've taken your\nfirst step into\011KANTO.\012Check your POKé-\nGEAR MAP and see.",
  ["4a:48d8"] = "Você parece ser\nbem forte.\012Deixe-me batalhar\ncom você!",
  ["4a:4904"] = "Yow!",
  ["4a:490a"] = "Se você continuar\nesse caminho duro,\011a verdade será\011revelada!\012É, perdão, eu só\nquis dizer alguma\011coisa legal.",
  ["4a:497b"] = "Hm? Você é bom,\nnão é?",
  ["4a:4997"] = "Como eu pensei!",
  ["4a:49ab"] = "Um bom treinador\npode reconhecer\011outros bons\011treinadores.",
  ["4a:49de"] = "Você não deve\ndesprezar os\011#MON selvagens\011dessas áreas.",
  ["4a:4a18"] = "Oh! Você é forte\ndemais!",
  ["4a:4a34"] = "Você é só uma\ncriança, mas\011não deve ser\011desprezada também.",
  ["4a:4a72"] = "É raro ver alguém\nvindo aqui.\012Está treinado por\nconta própria?",
  ["4a:4ab3"] = "Oh! Você é forte\nmesmo!",
  ["4a:4acd"] = "Estou checando\npré e pró\011evoluções de\011#MON.\012As evoluções real-\nmente fortalecem\011os #MON.\012Mas formas\nevoluídas aprendem\011golpes mais\011devagar.",
  ["4a:4b54"] = "Não diga nada!\012Deixe-me adivinhar\nseus pensamentos.\012Mmmmmmm…\012Consegui! Está\nindo ao desafio\011da LIGA #MON!",
  ["4a:4bc0"] = "Você é demais!",
  ["4a:4bd1"] = "Com sua\nhabilidade, irá\011bem na LIGA.\012Isso é o que\nminha premunição\011diz.",
  ["4a:4c21"] = "Piu! Piu! Piiiu!",
  ["4a:4c39"] = "Piu!",
  ["4a:4c41"] = "CRIADORES DE AVES\ncomo eu imitam\011sons de aves para\011comandar #MON.",
  ["4a:4c7e"] = "CACHOEIRA TOHJO\012A LIGAÇÃO ENTRE\nKANTO E JOHTO.",
  ["4a:4d53"] = "ROTA 28.",
  ["4a:4ed2"] = "Os #MON se\nescondem na grama.\012Não se sabe quando\naparecerão…",
  ["4a:4f0a"] = "Já te vi muitas\nvezes.\012Quantos #MON\nvocê capturou?\012Quer que eu lhe\nmostre como\011capturar #MON?",
  ["4a:4f78"] = "É assim que se\nfaz.\012Se enfraquecê-los\nantes, será mais\011fácil pegá-los.",
  ["4a:4fc2"] = "Oh. Certo.\012De qualquer modo,\nvocê deve andar\011muito se quiser\011capturar #MON.",
  ["4a:500e"] = "Hã? Quer que eu\nlhe mostre como\011capturar #MON?",
  ["4a:503f"] = "Ei. Como vão seus\n#MON?\012Se estiverem\nfracos e sem\011preparo para\011batalhar, fique\011fora da grama.",
  ["4a:5097"] = "Vê essas beiras?\nÉ assustador\011pulá-las.\012Mas você pode ir\na NEW BARK sem\011passar pela grama.",
  ["4a:5104"] = "Eu quis descançar,\nentão salvei para\011gravar meus\011progressos.",
  ["4a:5177"] = "Estou esperando\npor um #MON que\011apareça à noite.",
  ["4a:51a7"] = "Estou esperando\npor um #MON que\011apareça de manhã.",
  ["4a:51dd"] = "TUSCANY: Essa é a\nprimeira vez que\011nos encontramos?\011Permita que eu me\011apresente.\012Sou TUSCANY da\nTerça-feira.",
  ["4a:525a"] = "Aproveitando a\nintrodução, aceite\011esse presente, um\011ARCO ROSA.",
  ["4a:529a"] = "TUSCANY: Não\nconcorda que é\011adorável?\012Isso fortalece\ngolpes do tipo\011normal.\012Tenho certeza que\nlhe será útil.",
  ["4a:5312"] = "TUSCANY: Já\nencontrou MÔNICA,\011minha irmã mais\011velha?\012Ou meu irmão mais\nnovo, WESLEY?\012Sou a segunda de\nsete crianças.",
  ["4a:5384"] = "TUSCANY: Hoje\nnão é Terça. Que\011horrível…",
  ["4a:53b9"] = "ROTA 29\012CIDADE CHERRYGROVE-\nCIDADE NEW BARK.",
  ["4a:53e4"] = "ROTA 29\012CIDADE CHERRYGROVE-\nCIDADE NEW BARK.",
  ["4a:55ad"] = "Vá, RATTATA!\012AGARRAR!",
  ["4a:55c3"] = "O quê? Essa é uma\ngrande batalha!\011Deixe-me só!",
  ["4a:55f0"] = "Acabei de perder,\nentão estou\011procurando mais\011#MON.\012Espere! Você\nparece fraco. Ei,\011vamos batalhar!",
  ["4a:5649"] = "Ugh. I don't have\nany more POKéMON.",
  ["4a:566a"] = "I have to have\nmore POKéMON for\011battles.\012I'm going to catch\nsome more!",
  ["4a:56ae"] = "Você é um\ntreinador #MON,\011certo?\012Então você deve\nbatalhar!",
  ["4a:56e5"] = "Que estranho. Eu\nganhava antes.",
  ["4a:5703"] = "Tornar-se um bom\ntreinador é\011realmente duro.\012Vou batalhar com\noutras pessoas\011para eu ficar\011melhor.",
  ["4a:575e"] = "Ao invés de um\n#MON inseto,\011achei um\011treinador!",
  ["4a:5789"] = "Argh! Você é bem\nforte!",
  ["4a:57a2"] = "I ran out of POKé\nBALLS while I was\011catching POKéMON.\012I should've bought\nsome more…",
  ["4a:57f0"] = "Casa do SENHOR\n#MON?\012Está um pouco mais\nacima.",
  ["4a:581a"] = "Todos se divertem\nbatalhando! Você\011deveria também!",
  ["4a:584a"] = "Não sou uma\ntreinadora.\012Mas se olhar nos\nolhos, prepare-se\011para batalhar.",
  ["4a:5891"] = "ROTA 30\012CIDADE VIOLETA-\nCIDADE CHERRYGROVE.",
  ["4a:58ba"] = "CASA DO SENHOR\n#MON\012LOGO ACIMA!",
  ["4a:58db"] = "CASA DO SENHOR\n#MON.",
  ["4a:58ec"] = "TRAINER TIPS\012No stealing other\npeople's POKéMON!\012POKé BALLS are to\nbe thrown only at\011wild POKéMON!",
  ["4a:5b1e"] = "CAVERNA ESCURA…\012Se meu #MON\npudesse clareá-la,\011eu a exploraria.",
  ["4a:5b54"] = "Peguei muitos\n#MON. Deixe-me\011batalhar contigo!",
  ["4a:5b87"] = "Awwwww…",
  ["4a:5b90"] = "Você pode capturar\n#MON mesmo\011tendo seis com\011você.\012Se capturar um,\nele vai para\011seu BOX\011automaticamente.",
  ["4a:5bf8"] = "… Arf… Hã?\012Eu andei longe\nhoje procurando\011#MON.\012Meu pé dói e eu\nestou sonolento…\012Se eu fosse um\n#MON selvagem,\011seria fácil de se\011capturar…\012…Zzzz…",
  ["4a:5c80"] = "…Zzzz… Hã?\012O que foi? Você\ntem CARTA para\011mim?",
  ["4a:5caf"] = "{PLAYER} entregou o\n#MON segurando\011a CARTA.",
  ["4a:5cd9"] = "Let's see…\012…DARK CAVE leads\nto another road…\012That's good to\nknow.\012Thanks for bring-\ning this to me.\012My friend's a good\nguy, and you're a\011swell guy too!\012I'd like to do\nsomething good in\011return too!\012I know! I want you\nto have this!",
  ["4a:5dbb"] = "O TM50 é o\nPESADELO.\012É um golpe\nterrível que corta\011periodicamente o\011HP do inimigo\011dorminhoco.\012Ooooh… Que\nassustador…\012Não quero ter\nsonhos ruins.",
  ["4a:5e46"] = "Essa CARTA não é\npara mim.",
  ["4a:5e5e"] = "Why is this POKé-\nMON so special?\012It doesn't have\nany MAIL.",
  ["4a:5e97"] = "O quê? Você não\nquer nada?",
  ["4a:5eb6"] = "Se eu tomar esse\n#MON de você, o\011que usará nas\011batalhas?",
  ["4a:5efa"] = "Eu achei um bom\n#MON na CAVERNA\011ESCURA.\012Vou treiná-lo para\ndesafiar FALKNER.\012Ele é o líder do\nGINÁSIO da CIDADE\011VIOLETA.",
  ["4a:5f6a"] = "ROTA 31\012CIDADE VIOLETA-\nCIDADE CHERRYGROVE.",
  ["4a:5f93"] = "CAVERNA ESCURA.",
  ["4b:42a5"] = "Espere!\nPor que a\011pressa?",
  ["4b:42c0"] = "{PLAYER}, certo?\nUm rapaz usando\011óculos estava\011procurando por\011você.\012Vá vê-lo. Ele está\nte esperando no\011CENTRO #MON.",
  ["4b:43c5"] = "Você já foi ao\nGINÁSIO #MON?\012Lá você pode\ntestar seu #MON\011e si mesmo.\012É parada\nobrigatória para\011todos treinadores!",
  ["4b:443a"] = "Você tem bons\n#MON aí.\012Deve ser devido ao\ntreinamento que\011receberam na\011CIDADE VIOLETA.\012O treinamento no\nGINÁSIO ajudou de\011forma excepcional.\012Como lembrança da\nCIDADE VIOLETA,\011leve isso.\012Ele melhora o\npoder de golpes do\011tipo grama.",
  ["4b:452a"] = "Suas experiências\nna CIDADE VIOLETA\011devem ser úteis\011para sua jornada.",
  ["4b:456e"] = "O que acha\ndeste delicioso\011e nutritivo\011RABOSLOWPOKE?\012Para você, vai\ncustar apenas\011¥1,000,000!\012Você vai gostar!",
  ["4b:45e4"] = "Tch! Achava que as\ncrianças de hoje\011em dia tinham mais\011dinheiro…",
  ["4b:4611"] = "Você não quer?\nEntão vá embora.\012Xô!",
  ["4b:4636"] = "Ei! Você me fez\nperder aquele\011peixe!",
  ["4b:4659"] = "Sploosh!",
  ["4b:4663"] = "Calm, collected…\nThe essence of\012fishing and POKé-\nMON is the same.",
  ["4b:46a4"] = "I'm a good angler,\nbut an even better\011trainer!",
  ["4b:46d3"] = "Tch! Tentei mistu-\nrar as coisas…",
  ["4b:46f1"] = "Pescar é diversão\npara vida toda.\012Os #MON são\namigos de toda a\011vida!",
  ["4b:4863"] = "Meu #MON?\nAcabei de pegar!",
  ["4b:487d"] = "SPLASH?",
  ["4b:4886"] = "#MON novatos\nnão são páreos\011para os já bem\011criados.",
  ["4b:48c2"] = "Eu não o vira aqui\nantes. Você se\011acha muito forte\011então?",
  ["4b:4907"] = "Você é forte!",
  ["4b:4916"] = "Eu vou tentar ser\no melhor com meus\011favoritos.\012Não vou usar os\nmesmos #MON\011que todos usam.",
  ["4b:497c"] = "Eu achei bons\n#MON na grama!\012Acho que eles\nserão úteis para\011mim!",
  ["4b:49bf"] = "Droga. Achei que\neu ganharia.",
  ["4b:49dd"] = "A grama é cheia\nde coisas legais.",
  ["4b:4a02"] = "Esse lugar… É\nincrível.",
  ["4b:4a20"] = "Hmmm. Isso é\ndespontador.",
  ["4b:4a3e"] = "Se não quiser\nbatalhar, evite o\011contato visual.",
  ["4b:4a73"] = "Hã-hã. É, e você\nsabe…\012Pois não? Uma\nbatalha? Estou no\011telefone. \012Oh, certo. Mas\nvamos fazê-la\011rápido.",
  ["4b:4ad2"] = "Take it easy!\nThat's mean!",
  ["4b:4aed"] = "A conversa estava\nlegal também.",
  ["4b:4b0c"] = "Essa INSÍGNIA! É\nda CIDADE VIOLETA!\012Você derrotou\nFALKNER?",
  ["4b:4b41"] = "Eu conheço minhas\nfraquezas.",
  ["4b:4b61"] = "Eu devo treinar de\nnovo no GINÁSIO\011da CIDADE VIOLETA.",
  ["4b:4bc0"] = "UARRRRR!\nAS PESSOAS FOGEM\011QUANDO EU RUJO!\011MAS VOCÊ NÃO! ISSO\011ME ALEGRA! AGORA\011LEVE ISSO!",
  ["4b:4c19"] = "UARRR! É O RUGIDO!\012ATÉ OS #MON\nFOGEM DE UM BOM\011RUGIDO!",
  ["4b:4c4e"] = "FRIEDA: Oba! Hoje\né Sexta\012Eu sou FRIEDA da\nSexta-feira!\012Prazer em\nconhecê-lo!",
  ["4b:4c91"] = "Aqui está uma\nBARBA VENENO!",
  ["4b:4caf"] = "FRIEDA: Dê isso a\num #MON que\011possui golpes do\011tipo veneno.\012Oh!\012É perigoso!\012Você vai ficar\nchocado com o bem\011que isto faz aos\011golpes venenosos!",
  ["4b:4d27"] = "FRIEDA: Hiia! Do\nque você gosta?\012Eu amo as Sextas.\nSem dúvida alguma.\012Você não acha\nlegal também?",
  ["4b:4d8c"] = "FRIEDA: Hoje não\né Sexta?\012É tão chato quando\nnão é!",
  ["4b:4dc7"] = "ROTA 32\012CIDADE VIOLETA-\nCIDADE AZALEA.",
  ["4b:4deb"] = "RUÍNAS ALFA\nENTRADA LESTE.",
  ["4b:4e08"] = "CAVERNA UNION\nACIMA.",
  ["4b:4fad"] = "Eu vim através do\ntúnel, mas ainda\011tenho energia\011sobrando.",
  ["4b:4ff1"] = "Whoa, boy! You've\ngot more zip.",
  ["4b:5011"] = "Nós ANDARILHOS\nsomos melhores nas\011montanhas.",
  ["4b:503e"] = "ROTA 33.",
  ["4b:52ee"] = "Aqui é o local\ndo meu treino!",
  ["4b:530f"] = "What happened?",
  ["4b:531f"] = "Vou treinar ainda\nmais.\012Afinal, estou\ntentando me tornar\011um LÍDER DE\011GINÁSIO.",
  ["4b:536c"] = "Sou o melhor na\nminha sala em\011#MON.",
  ["4b:538e"] = "Não! Há treinado-\nres melhores…",
  ["4b:53b0"] = "Treino duro, logo,\nposso ser o melhor\011em minha sala.",
  ["4b:53e2"] = "Estou confiante em\nminha técnica de\011criar #MON?\012Quer ver?",
  ["4b:541a"] = "I didn't do a good\nenough job?",
  ["4b:5439"] = "Maybe I should\nleave one in DAY-\011CARE.\011What should I do?",
  ["4b:5473"] = "Você é um\ntreinador?\012Vamos ter uma\nbatalha para\011praticar.",
  ["4b:54a4"] = "Oh, não! Não\nposso vencer…",
  ["4b:54be"] = "Você é muito forte\npara ser parceiro\011de luta.",
  ["4b:54ea"] = "Aonde vai?\nE o que pretende\011fazer?",
  ["4b:550f"] = "You're a tough\nlittle guy.",
  ["4b:552a"] = "É, não vejo nada\nde errado hoje.\011Seja bom e fique\011longe de proble-\011mas.",
  ["4b:5570"] = "Estou patrulhando\nà busca de gente\011suspeita.",
  ["4b:559c"] = "Acabei de pegar\nmeu #MON do\011CRIATÓRIO.\012Vamos ver o quanto\nele fortaleceu!",
  ["4b:55e7"] = "Por que isso\nacabou assim?",
  ["4b:5602"] = "Meus #MON\nsabiam golpes que\011eu não tinha\011ensinado.\012Isso me confundiu\ntodo!",
  ["4b:5649"] = "IRENE: Kyaaah!\nA boy found us!",
  ["4b:5669"] = "IRENE: Ohhhh!\nHe's too strong!",
  ["4b:5688"] = "IRENE: Minha irmã\nKATE o vencerá por\011isso!",
  ["4b:56b6"] = "IRENE: Essa praia\nnão é ótima?\012É o nosso refúgio\nsecreto!",
  ["4b:56f4"] = "JENN: Você não\npode vencer IRENE\011e ir impune!",
  ["4b:5722"] = "JENN: Perdão,\nIRENE! Irmã!",
  ["4b:573f"] = "JENN: Não se\norgulhe! Minha\011irmã KATE é forte!",
  ["4b:576f"] = "JENN: A luz solar\nfortalece seu\011corpo.",
  ["4b:5799"] = "KATE: Você foi\nmesmo rude com\011minhas irmãzinhas!",
  ["4b:57c9"] = "KATE: Não! Não\nacredito que\011perdi.",
  ["4b:57eb"] = "KATE: Você é muito\nforte. Nem tive\011chances.\012Ei. Você merece\nisso.",
  ["4b:5834"] = "KATE: Perdão por\nassustá-lo.\012Não esperávamos\nser achAdas por\011alguém aqui.\n \012Você nos assustou.",
  ["4b:58b1"] = "ROTA 34\012CIDADE GOLDENROD-\nCIDADE AZALEA.\012FLORESTA ILEX\nENTRE ALGUM LUGAR.",
  ["4b:58f6"] = "TRAINER TIPS\012BERRY trees grow\nnew BERRIES\011everyday.\012Make a note of\nwhich trees bear\011which BERRIES.",
  ["4b:595a"] = "CRIATÓRIO #MON\012DEIXE-NOS CRIAR\nSEUS #MON!",
  ["4b:5c09"] = "ROTA 44\012CAMINHO DE GELO\nacima.",
  ["4b:5c44"] = "Eu estive obtendo\ndados de #MON\011no meu rádio.\012Acho que sou bom.",
  ["4b:5c4d"] = "Music on the radio\nchanges the moods\011of wild POKéMON.",
  ["4b:5c81"] = "Eu mostrarei a\nminha namorada que\011sou bom!",
  ["4b:5cac"] = "Você poderia ter\nperdido para mim…",
  ["4b:5cd0"] = "Eu fui humilhado\nem frente a minha\011namorada…",
  ["4b:5cfd"] = "Meu namorado é\nfraco, logo, não\011devo confiar nele.",
  ["4b:5d29"] = "Nossa! Você é\nforte!",
  ["4b:5d43"] = "Posso contar mais\ncom meus #MON\011que com meu\011namorado.",
  ["4b:5d73"] = "Você está indo ao\nGINÁSIO?\012Eu também!",
  ["4b:5d96"] = "Oh. Eu não pude\nvencer…",
  ["4b:5daa"] = "As INSÍGNIAS de\nGINÁSIO são\011lindas.\012Eu as coleciono.",
  ["4b:5dd6"] = "What kinds of POKé\nBALL do you use?",
  ["4b:5df8"] = "Nossa. Faltou\nrapidez!",
  ["4b:5e11"] = "Some POKéMON flee\nright away.\012Try catching them\nwith KURT's FAST\011BALL.\012Whenever I find a\nWHT APRICORN, I\011take it to KURT.\012He turns it into a\ncustom POKé BALL.",
  ["4b:5eaa"] = "Observe minha\ndestreza com\011BOLAS!",
  ["4b:5ece"] = "Uau! Que abalo!",
  ["4b:5ee6"] = "Eu ia faciná-lo\ncom meu #MON\011premiado.\012Mas sua proeza me\neletrocutou!",
  ["4b:5f36"] = "Vou a todo lugar\nque #MON\011insetos apareçam.",
  ["4b:5f61"] = "I see. So you\nbattle that way.",
  ["4b:5f81"] = "Meu VENONAT me fez\nvencer o Concurso\011Caça-Inseto no\011PARQUE nacional.",
  ["4b:5fc3"] = "Estou praticando\nsopro de fogo.",
  ["4b:5fe5"] = "Ai! Queimei a\nponta de meu\011nariz!",
  ["4b:6009"] = "A Marcha #MON\nno rádio\011atrai #MON\011selvagens.",
  ["4b:6037"] = "O perigo se\noculta à noite!",
  ["4b:6053"] = "Opa!",
  ["4b:605c"] = "Você sabe, a\nnoite pode ser\011legal.\012Mas não abuse,\ntudo bem?",
  ["4b:60a3"] = "Seus #MON\nparecem fortes.\n \012Você poderia ir a\nqualquer lugar\011seguramente.",
  ["4b:60e1"] = "ROTA 35.",
  ["4b:6321"] = "É uma árvore\nestranha.\012Usar o POTE\nSQUIRT?",
  ["4b:6346"] = "{PLAYER} usou o\nPOTE SQUIRT.",
  ["4b:6360"] = "A árvore estranha\nnão gosta do POTE\011SQUIRT!\012A árvore estranha\natacou!",
  ["4b:63a7"] = "Wa-hey!\012Eu ia arrancar\naquela árvore com\011meu soco direto.\012Mas eu não pude!\nEu sou um\011fracassado!",
  ["4b:6408"] = "Você eliminou\naquela árvore\011idiota?\012Estou\nimpressionado.\012Quero que leve\nisso.",
  ["4b:6464"] = "Isso é o ESMAGA-PEDRAS.\012Você pode quebrar\numa pedra com um\011simples e bem\011mirado golpe.\012Se tiver alguma\npedra em seu\011caminho, basta\011quebrá-la!",
  ["4b:64f0"] = "Uma estranha\nárvore está\011fechando o\011caminho para a\011CIDADE GOLDENROD.\012Está me privando\nde fazer compras.\012Algo tem que ser\nfeito.",
  ["4b:6568"] = "Aquela estranha\nárvore sumiu sem\011deixar rastro.\012Oh! Ela era mesmo\num #MON?",
  ["4b:65b7"] = "Eu vou ler seus\npensamentos!",
  ["4b:65d8"] = "Eu o subestimei!",
  ["4b:65e8"] = "Eu seria forte\nse conseguisse\011saber o que meu\011oponente está\011pensando.",
  ["4b:662a"] = "Graças a meus\nestudos, estou\011pronto para\011qualquer #MON!",
  ["4b:665a"] = "Opa! Erro de\ncomputação?",
  ["4b:6674"] = "Darn. I study five\nhours a day too.\012There's a lot you\ncan't learn just\011by reading books.",
  ["4b:66cc"] = "ARTHUR: Quem é\nvocê?\012Sou ARTHUR da\nQuinta.",
  ["4b:66f9"] = "Ei. Você pode\nlevar isso.",
  ["4b:6713"] = "ARTHUR: Um #MON\nque usa golpes do\011tipo pedra deve\011segurar isso.\012Ele impulsiona\ngolpes do tipo\011pedra.",
  ["4b:6776"] = "ARTHUR: Sou ARTHUR\nda Quinta.\012Sou o segundo\nfilho nascer das\011sete crianças.",
  ["4b:67bf"] = "ARTHUR: Hoje não\né Quinta.\012Que desagradável.",
  ["4b:67f0"] = "ROTA 36.",
  ["4b:67fa"] = "RUÍNAS ALFA\nENTRADA NORTE.",
  ["4b:6818"] = "DICAS DO TREINADOR\012O estado dos\n#MON muda,\011mesmo em tipos\011iguais.\012Suas situações\npodem ser\011parecidas no\011início.\012Porém, as\ndiferenças virão à\011medida que o\011#MON crescer.",
  ["4b:68ba"] = "DICAS DO TREINADOR\012Use o CAVAR para\nvoltar à entrada\011de qualquer lugar.\012É util para\nexplorar cavernas\011e outros lugares.",
  ["4c:4093"] = "ANN: ANNE and I\nare in this to-\011gether!",
  ["4c:40bc"] = "ANN & ANNE: You're\nmean!",
  ["4c:40d5"] = "ANN: Eu posso\ndizer o que minha\011irmã e meus\011#MON pensam.",
  ["4c:410f"] = "ANNE: ANN e eu\nestamos juntas\011nessa!",
  ["4c:4138"] = "ANN & ANNE: You're\nmean!",
  ["4c:4151"] = "ANNE: Dividimos os\nmesmos sentimentos\011de nossos\011#MON.",
  ["4c:4180"] = "Os #MON nada\npodem fazer quando\011dormem.\012Vou lhe mostrar\no quanto isso\011é assustador!",
  ["4c:41ca"] = "… O que você\nestá olhando?",
  ["4c:41e5"] = "Pôr os #MON\npara dormir ou\011paralizá-los são\011boas técnicas de\011batalha.",
  ["4c:422d"] = "SUNNY: Oi!\012Sou SUNNY do\nDomingo.\012E significa que\nhoje é domingo!",
  ["4c:4269"] = "Fui mandada para\nlhe dar isso se o\011visse!",
  ["4c:4294"] = "SUNNY: Essa coisa…\012Um…\012… O que era mesmo…\012…\012Oh! Agora me\nlembro!\012Um #MON que\nsabe golpes\011elétricos deve\011segurá-lo.\012Minha irmã MÔNICA\ndisse que ele\011melhora golpes\011elétricos!",
  ["4c:4336"] = "SUNNY: Meus\nirmãos são:\012MÔNICA, TUSCANY,\nWESLEY, ARTHUR,\011FRIEDA e SANTOS.\012Todos são mais\nvelhos do que eu!",
  ["4c:43a8"] = "SUNNY: Hoje não\né Domingo?\011Um… Esqueci!",
  ["4c:43d1"] = "ROTA 37.",
  ["4c:45a8"] = "Voar alto no céu,\nmeu querido\011#MON!",
  ["4c:45d6"] = "Sinto-me voando\nlonge agora.",
  ["4c:45f9"] = "Eu planejo treinar\nna CIDADE CIANWOOD\011para ensinar meu\011#MON a VOAR.",
  ["4c:4638"] = "Deixe-me testar\nalgo que aprendi\011hoje.",
  ["4c:4661"] = "Não estudei o\nbastante, eu acho.",
  ["4c:4681"] = "Eu tenho que\nfazer vários\ntestes, e não\011tenho muito tempo\011para #MON.\012Quando tenho\ntempo, eu me\011concentro demais.",
  ["4c:46f0"] = "Are you good at\ntraining?\012If you are, could\nyou show me how?",
  ["4c:472e"] = "Entendo. Então é\nassim que você\011batalha.",
  ["4c:4752"] = "Eu conheço algo\nbom!\012O leite da FAZENDA\nMOOMOO é famoso\011pelo seu sabor.",
  ["4c:4796"] = "Você é um\ntreinador bonito!\012Posso ver seus\n#MON?",
  ["4c:47ca"] = "Estou feliz pois\npude ver seus\011#MON!",
  ["4c:47eb"] = "When I see POKé-\nMON, it seems to\011soothe my nerves.",
  ["4c:481d"] = "Eu já atravessei\nmares, logo\011conheço todos\011tipos de #MON!",
  ["4c:4856"] = "Sua habilidade é\nde classe mundial!",
  ["4c:4872"] = "Todas pessoas no\nmundo vivem\011felizes com seus\011#MON.",
  ["4c:48b2"] = "ROUTE 38\012OLIVINE CITY -\nECRUTEAK CITY",
  ["4c:48d9"] = "DICAS DO TREINADOR\012Se um #MON\nestiver tentando\011evoluir, você pode\011pará-lo.\012Aperte o botão B\ndurante a\011evolução.\012Isso assusta\no #MON e\011interrompe sua\011evolução.",
  ["4c:4abc"] = "MILTANK: Mooo!",
  ["4c:4acc"] = "Eu acabei de\nvoltar de OLIVINE.\012Então que tal uma\nbatalha #MON?",
  ["4c:4b05"] = "Arrrrrgh!",
  ["4c:4b10"] = "Meus #MON\nforam capturados e\011criados sobre os\011mares.\012São meus parceiros\nnessas longas\011viagens.",
  ["4c:4b68"] = "Would you mind if\nI bragged about\011my POKéMON?",
  ["4c:4b94"] = "I couldn't begin\nto brag…",
  ["4c:4bae"] = "I'm not listening\nto your bragging!\012We POKé FANS have\na policy of not\012listening to other\npeople brag!",
  ["4c:4c11"] = "Somente #MON\nlindos.\012Vamos mostrar\nnossos #MON\011juntos ao mesmo\011tempo.",
  ["4c:4c53"] = "Não me importo em\nperder.",
  ["4c:4c68"] = "Você conhece\n#MON bebês?\012Eu aposto que eles\nsão adoráveis!",
  ["4c:4ca2"] = "Deixe-me ver de\nque seus #MON\011são capazes.",
  ["4c:4ccd"] = "Ooh, seus #MON\ntêm potencial.",
  ["4c:4ced"] = "You know how POKé-\nMON have different\011abilities?\012People are like\nthat too. Every-\011one has different\011potential.",
  ["4c:4d5a"] = "ROTA 39\012CIDADE OLIVINE-\nCIDADE ECRUTEAK.",
  ["4c:4d81"] = "FAZENDA MOOMOO\012Aprecie nosso\nLeite Delicioso e\011Fresquinho!",
  ["4c:4dad"] = "Nem tive tempo de\nfalar do PIKACHU…",
  ["4c:4f84"] = "Você tem que se\naquecer antes de\011entrar na água.\012Isso é básico.",
  ["4c:4fc3"] = "Certo! Tio!\nDesisto!",
  ["4c:4fd7"] = "A CIDADE CIANWOOD\né bem distante\011daqui.",
  ["4c:5009"] = "A young guy like\nyou should swim.\012Don't SURF on your\nPOKéMON.",
  ["4c:5044"] = "Opa. Eu perdi…",
  ["4c:5054"] = "Nadar exercita\ntodo seu corpo.\011É saudável.",
  ["4c:5087"] = "Você está indo\npara CIANWOOD?\012Que tal uma rápida\nbatalha primeiro?",
  ["4c:50c3"] = "Essa eu perdi!",
  ["4c:50d5"] = "Digo que nado\nmelhor do que\011você. Legal!",
  ["4c:5103"] = "Não me atrapalhe.\012Estou segurando um\n#MON aquático!",
  ["4c:5137"] = "Ooh, me sinto\ntonta!",
  ["4c:514f"] = "Enquanto eu\nflutuar assim,\011as ondas me\011carregarão.",
  ["4c:5183"] = "Mesmo não podendo\nver daqui,\011CIANWOOD é após\011o mar.",
  ["4c:51c4"] = "MÔNICA: Estou\nfeliz em\011conhecê-lo.\012Sou MÔNICA da\nSegunda.",
  ["4c:51f4"] = "Como prova de\nnossa amizade,\011vou te dar um\011presente!",
  ["4c:522a"] = "MÔNICA: É um item\nque aumenta o\011poder de golpes\011do tipo voador.\012Você deve equipar\num #MON pássaro\011com esse item.",
  ["4c:529a"] = "MÔNICA: Meus\nirmãos estão em\011todos lugares.\n\012Tente encontrar\ntodos eles!",
  ["4c:52f5"] = "MÔNICA: Acho que\nhoje não é\011Segunda.\012Que triste…",
  ["4c:5325"] = "ROTA 40\012CIDADE CIANWOOD-\nCIDADE OLIVINE.",
  ["4c:54a1"] = "The water's warm\nhere. I'm loose\011and limber.\012Sure, I'll take\nyou on!",
  ["4c:54e4"] = "Droga! Pareço uma\npassa!",
  ["4c:5500"] = "Não é relaxante\nficar flutuando\011assim?",
  ["4c:552b"] = "Estou cansado.\n\nEmpreste-me meu\011#MON se eu\011vencer.",
  ["4c:5559"] = "Uf, uf, uf…",
  ["4c:5566"] = "Está tão longe de\nCIANWOOD.\012Mas não é fácil\nvoltar para\011OLIVINE também.\012O que devo fazer?",
  ["4c:55c0"] = "Vê essas\nilhas que estão\011bloqueadas por\011redemoinhos?\012Deve ter algo\nsecreto lá!",
  ["4c:5612"] = "Qual o segredo da\nsua força?",
  ["4c:5636"] = "Foi uma noite\nescura e chuvosa…\012Eu vi esse #MON\ngigante viando das\011ilhas.\012Estava caindo\npenas de suas asas\011de prata.",
  ["4c:56b8"] = "Fui derrotado!",
  ["4c:56f4"] = "As ondas são\nselvagens aqui.\012Elas te cansam\nquando você nada.",
  ["4c:56fe"] = "As correntes me\nimpedem de chegar\011à ilha.",
  ["4c:572f"] = "Você está\nprocurando os\011segredos das ILHAS\011RODOPIO?",
  ["4c:575e"] = "Ooh, você tem\nmuita paciência!",
  ["4c:577f"] = "Um segredo sobre\nas ILHAS RODOPIO…\012É preta por\ndentro!",
  ["4c:57b6"] = "Estou a caminho\ndas ILHAS RODOPIO.\012Vou explorá-la com\nmeus amigos.",
  ["4c:57f9"] = "É assim que você\nfaz?",
  ["4c:5811"] = "There's supposed\nto be a big POKé-\011MON deep beneath\011WHIRL ISLANDS.\012I wonder what it\ncould be?",
  ["4c:586c"] = "Você parece tão\nelegante, montado\011em seu #MON.",
  ["4c:5896"] = "Fui esmagado…",
  ["4c:58a3"] = "Não havia uma\ncanção sobre um\011garoto andando\011de LAPRAS?",
  ["4c:58d8"] = "O tempo está tão\nbonito que fico\011deslumbrado!",
  ["4c:5904"] = "Ohhh!",
  ["4c:590b"] = "Uma queimadura\né o pior para a\011pele.\012Mas eu não uso\nprotetores.\012Não poluirei a\nágua.",
  ["4c:5962"] = "Se quiser\ndescansar, ponha\011os pés na água.\012Você recuperará\nsua energia e\011ficará mais forte.",
  ["4c:59c5"] = "Oh! Você tem mais\nenergia do que\011eu.",
  ["4c:59ea"] = "Eu ouvi rugidos\ndas profundezas\011das ILHAS.",
  ["4c:5a17"] = "Os STARYUS se\nreúnem na\011superfície da água\011à noite.",
  ["4c:5a49"] = "Oh, querido…",
  ["4c:5a54"] = "Os cardumes de\nSTARYU se iluminam\011ao mesmo tempo.\012É tão bonito, tão\nassustador.",
  ["4c:5c16"] = "LABORATÓRIO DE\nPESQUISA DO\011PROFESSOR ELM.",
  ["4c:5c4a"] = "O quê? Isso está\nerrado.",
  ["4c:5c62"] = "Eu quero me tornar\no treinador\011CAMPEÃO usando o\011#MON que eu\011capturei.\012É a melhor parte\nda pesca!",
  ["4c:5cbf"] = "Ah, é bom estar\naqui fora!\012Sinto-me tão\nlivre!",
  ["4c:5cec"] = "Hahahah!",
  ["4c:5cf6"] = "Perder parece\ninsignificante\011comparado a olhar\011o grande céu\011azul!",
  ["4c:5d33"] = "EI!\012Esse é meu lugar\nsecreto! Saia,\011seu forasteiro!",
  ["4c:5d6a"] = "Eu deveria ter\nusado minha PEDRA\011DA LUA…",
  ["4c:5d8d"] = "You're working on\na POKéDEX?\012Wow, you must know\nsome pretty rare\011POKéMON!\012May I please see\nit. Please?",
  ["4c:5dee"] = "ROTA 42\012CIDADE ECRUTEAK-\nCIDADE MAHOGANY.",
  ["4c:5e16"] = "MOUNT MORTAR\012WATERFALL CAVE\nInside",
  ["4c:5e3a"] = "MOUNT MORTAR\012WATERFALL CAVE\nInside",
  ["4c:5e5e"] = "ROTA 42\012CIDADE ECRUTEAK-\nCIDADE MAHOGANY.",
  ["4d:418e"] = "Eu amo #MON!\012É por isso que\ncomecei e continuo\011colecionando\011#MON!",
  ["4d:41d8"] = "Como pode fazer\nisso comigo?",
  ["4d:41f6"] = "O que mais gosto\nalém de #MON?\012A MARY do rádio.\nAposto que ela é\011linda!",
  ["4d:423d"] = "Ei! Você tem algum\n#MON raro?",
  ["4d:425e"] = "Oh, my poor POKé-\nMON! Darlings!",
  ["4d:427d"] = "Ficaria feliz só\nde ter um único\011raro #MON.",
  ["4d:42aa"] = "Would you get\nthis?\012Some {RIVAL} guy\nmade fun of my\011POKéMON!\012Darn it! My POKé-\nMON's great!",
  ["4d:42fa"] = "Meu NIDOKING foi\nmuito bem!",
  ["4d:431c"] = "É normal as\npessoas gostarem\011de diferentes\011tipos de #MON.\012Sempre ter os\n#MON mais\011fortes não é o\011principal.",
  ["4d:4385"] = "Estou afundado.\012Pode ser devido\nao meu\011equipamento.\012Vamos batalhar\npara mudar isso!",
  ["4d:43d4"] = "Eu perdi, mas me\nsinto melhor.",
  ["4d:43f7"] = "A BOLA ATRAÇÃO do\nKURT é a melhor\011para pegar\011#MON fisgados.\012Deve ser mais\nefetivo que uma\011ULTRA BOLA.",
  ["4d:4459"] = "Faço muitas\ncoisas com meus\011#MON--é super\011legal!",
  ["4d:4489"] = "Perder não é tão\nlegal…",
  ["4d:44a2"] = "O que está havendo\nno LAGO DA\011RAIVA?\012Nós planejávamos\nacampar lá.",
  ["4d:44e5"] = "Você está indo ao\nLAGO DA RAIVA\011também?\012Vamos brincar um\npouco antes!",
  ["4d:4528"] = "Eu brinquei\ndemais!",
  ["4d:453c"] = "Estou fazendo\npiquenique com\011#MON.\012Quer entrar?",
  ["4d:456f"] = "ROTA 43\012LAGO DA RAIVA-\nCIDADE MAHOGANY.",
  ["4d:4596"] = "ROTA 43\012LAGO DA RAIVA-\nCIDADE MAHOGANY.",
  ["4d:45bd"] = "DICAS DO TREINADOR\012Todos #MON têm\nvantagens e\011desvantagens\011dependendo do\011tipo.\012Um #MON de\nnível maior pode\011perder dependendo\011do tipo.\012Aprenda quais\ntipos são fortes\011e quais são fracos\011contra os dos seus\011#MON.",
  ["4d:488b"] = "Aack! You made me\nlose a POLIWAG!\012What are you going\nto do about it?",
  ["4d:48d1"] = "Simplesmente\nesqueça.",
  ["4d:48e8"] = "Aquele POLIWAG\nque perdi…\011Era grande.\012Eu juro que ele\ndevia ter uns\0115 metros!",
  ["4d:4937"] = "Eu pesco até não\npoder mais.\012Também batalho até\nficar derrubado.\012Essa é minha\nrelação com meus\011#MON.",
  ["4d:4995"] = "Hmmmm… Isso não\nestá certo.",
  ["4d:49af"] = "São 100 vitórias e\n101 derrotas.\012Não batalharei de\nnovo por um tempo.",
  ["4d:49ef"] = "Você sabe algo\nsobre #MON\011pássaros lendá-\011rios?",
  ["4d:4a1b"] = "Uau! Você é\nquente.",
  ["4d:4a33"] = "ARTICUNO, ZAPDOS\ne MOLTRES são os\011três #MON\011pássaros lendá-\011rios.\012Eu soube que há\noutros pássaros\011lendários.",
  ["4d:4aa7"] = "Com certeza\nvencerei!",
  ["4d:4ac0"] = "Argh… Foi uma\nderrota chocante…",
  ["4d:4adf"] = "É importante ter\nconvicção do seu\011lado.",
  ["4d:4b0f"] = "Farei tudo para\npôr minhas mãos\011em #MON raros!",
  ["4d:4b3e"] = "Oooh, seus\n#MON são tão\011atraentes.",
  ["4d:4b61"] = "Se um #MON\ntiver cores\011diferentes das\011normais, é mais\011valoroso.\012O quê? Você acha\nque não é\011verdade?",
  ["4d:4bbf"] = "I can tell you're\na good trainer by\011looking at you.\012I'm good at POKé-\nMON, and I can see\011that you are too.",
  ["4d:4c26"] = "Tch! É um erro da\nminha parte.",
  ["4d:4c49"] = "Uau. Você tem\nmuitas INSÍGNIAS.\012Sem dúvidas você\né forte.\012Será que MORTY do\nGINÁSIO ECRUTEAK\011ainda está\011treinando?\012Ele realmente me\nmartelou.",
  ["4d:4cd0"] = "Você parece forte.\012Bons treinadores\nvêem fortes\011oponentes por\011instinto.",
  ["4d:4d14"] = "Não! Isso não\nfunciona.",
  ["4d:4d30"] = "Todos nós\nmelhoramos ao\011passarmos por\011várias batalhas.\012Eu batalhei muito\nparam me tornar o\011que sou hoje--uma\011elite.",
  ["4d:4d96"] = "Uau! Demais!",
  ["4d:4daf"] = "ROTA 44\012CIDADE MAHOGANY-\nVILA BLACKTHORN.",
  ["4d:4feb"] = "Be prepared for\nanything!\012Let me see if your\nPOKéMON have been\011raised properly!",
  ["4d:5039"] = "Oh, perdi essa!",
  ["4d:504b"] = "Voltarei ao\nCAMINHO DE GELO\011DE BLACKTHORN e\011treinar mais.",
  ["4d:5087"] = "Você! É bem\ndisposto! Mas quer\011saber?\012Quando se fala de\ndisposição, eu sou\011o melhor!",
  ["4d:50dc"] = "Meus #MON\nnão foram muito\011dispostos!",
  ["4d:50fb"] = "Cara, eu amo o\nHP MAIS! Hmmm,\011yum!\012Fico bebendo o do\nmeu #MON!\012Não posso parar!",
  ["4d:5147"] = "Meus #MON\nsão poderosos!",
  ["4d:5162"] = "Hahaha! Sou o\ngrande perdedor!",
  ["4d:517e"] = "Não sou muito bom\npara pensar, vê?\012Então, só faço\nuso da força!",
  ["4d:51c4"] = "Por que escalo\nmontanhas?\012Porque elas\nestão lá.\012Por que treino\n#MON?\012Porque eles estão\nlá!",
  ["4d:5220"] = "Derrotas…\nTambém estão lá!",
  ["4d:523b"] = "A melhor coisa\nque já me\011aconteceu foi\011descobrir os\011#MON.",
  ["4d:5276"] = "Eu treinava aqui\nsozinho.\012Pelo poder do meu\ntrabalho!",
  ["4d:52b1"] = "Waaaargh!",
  ["4d:52bc"] = "Isso exige\nmedidas extremas.\012Devo ir às colinas\ne treinar na\011solidão.",
  ["4d:530e"] = "O que pensa\na respeito da\011criação de\011#MON?",
  ["4d:5339"] = "Ganhou meu respeito.",
  ["4d:5350"] = "Vejo que cria\nseus #MON com\011carinho.\012Os laços que\nvocê construiu\011vão ajudá-lo em\011situações duras.",
  ["4d:53b2"] = "Qual é sua\nestratégia de\011batalha?\012É besteira usar\ngolpes fortes sem\011ter necessidade.",
  ["4d:5405"] = "Bom, perdi.",
  ["4d:5414"] = "Sou contra ao uso\nexcessivo de\011golpes fortes.\012Quero vencer, mas\nnão quero ferir os\011#MON.",
  ["4d:5490"] = "ROTA 45\012MONTANHAS A\nSEGUIR.",
  ["4d:561f"] = "Certo! vou lhe\nmostrar a força\011dos #MON da\011montanha!",
  ["4d:5652"] = "Piedade! Mostrou-\nme seu poder!",
  ["4d:5674"] = "Acabou. eu não\nligo.\012Nós ANDARILHOS\nsomos assim.",
  ["4d:56a5"] = "I'm raising POKé-\nMON too!\012Will you battle\nwith me?",
  ["4d:56d6"] = "Quê…?",
  ["4d:56dd"] = "Dei meu melhor\nmas não pude\011vencer.\012Sem desculpas.\nAdmito a derrota.",
  ["4d:571b"] = "I raise POKéMON\ntoo!\012Let's battle!",
  ["4d:573b"] = "Oh, darn it!",
  ["4d:5749"] = "Estive em tantos\nGINÁSIOS, mas o\011de GOLDENROD é o\011meu favorito.\012É cheio de lindas\nflores!",
  ["4d:57aa"] = "ROTA 46\012MONTANHAS A\nSEGUIR.",
  ["4d:588a"] = "Você já visitou o\nGINÁSIO PEWTER?\012O LÍDER usa\n#MON do tipo\011pedra.",
  ["4d:58c8"] = "À noite, as\nCLEFAIRIES vêm\011brincar no MONTE\011LUA.\012Mas nem toda\nnoite.",
  ["4d:590e"] = "Ah, você percorreu\ntodo o caminho\011desde JOHTO?\012Isso me traz\nmemórias.\012Quando eu era\njovem, eu fui\011à JOHTO para\011treinar.\012Você me lembra\ndemais de como eu\011era quando jovem.\012Ei. Quero que\nvocê fique com\011esse item que eu\011achei em JOHTO.",
  ["4d:59f2"] = "Ir a lugares novos\ne dEsconhecidos e\nver novas pessoas…\012Essas são as\ndiversões de\011uma viajem.",
  ["4d:5a47"] = "CIDADE PEWTER\012A Cidade Cinza\nComo a Pedra.",
  ["4d:5a66"] = "CIDADE PEWTER\012LÍDER DO GINÁSIO\n#MON: BROCK\012O Treinador\n#MON Sólido\011Como uma Pedra.",
  ["4d:5aa6"] = "Há um aviso\naqui…\012O MUSEU DE\nCIÊNCIA DE PEWTER\011está fechado para\011renovações…",
  ["4d:5af1"] = "Há um aviso\naqui…\012LOJA DE PRESENTES\nDO MONTE LUA\011ABERTA AGORA!",
  ["4d:5b24"] = "Gyaaas!",
  ["4d:5c1a"] = "My bug POKéMON are\ntough. Prepare to\011lose!",
  ["4d:5c43"] = "Fui massacrada…",
  ["4d:5c53"] = "Vou procurar\n#MON insetos\nmais fortes.",
  ["4d:5c7c"] = "Se andar na grama\nalta vestindo\011um calção, vai\011se ferir?",
  ["4d:5cc2"] = "Nada bom!",
  ["4d:5cd5"] = "CIDADE LAVENDER\012A Nobre Cidade\nRoxa.",
  ["4d:5d00"] = "Estou preocupada\ncom queimaduras.",
  ["4d:5d1f"] = "Ai, ai, ai!",
  ["4d:5d29"] = "As feridas vão\narder mesmo quando\011tomar um banho.",
  ["4d:5d80"] = "Por que as garotas\nnão gostam de\011#MON insetos.",
  ["4d:5da5"] = "DIGLETT'S CAVE",
  ["4e:4062"] = "Hey, kid! I just\nhad a double shot\012of espresso, and\nI am wired!\012I need to talk to\nsomeone, so you'll\011have to do!\012I might not look\nlike much now, but\012I was an expert at\ncatching POKéMON.\012Do you believe me?",
  ["4e:412c"] = "Bom, bom. Sim,\neu era algo\011sobrenatural, vou\011te contar!",
  ["4e:4174"] = "O quê? Seu\ninsolente!\012Se eu fosse um\npouco mais jovem,\011eu lhe mostraria\011uma coisa, ou\011duas. Humph!",
  ["4e:41ce"] = "Esse GINÁSIO não\ntem um LÍDER\011desde agora pouco.\012Um jovem de PALLET\nse tornou o LÍDER,\011mas ele sai às\011vezes.",
  ["4e:423b"] = "Você vai batalhar\ncom o LÍDER?\012Boa sorte para\nvocê. Vai precisar\011dela.",
  ["4e:4281"] = "Yawn!\012Devo ter dormido\nno sol.\012… Eu sonhei que um\nDROWZEE estava\011comendo o meu\011sonho. Estranho,\011né?\012Hã? O quê é isso?\012De onde esse TM\nveio?\012Isso é assustador!\nEi, você pode\011ficar com esse\011TM.",
  ["4e:4343"] = "TM42 contém o\nCOME SONHO…\012…Zzzzz…",
  ["4e:4367"] = "Soube que há\nvários itens no\011chão da FLORESTA\011DE VIRIDIANA.",
  ["4e:43ac"] = "CIDADE VIRIDIANA\012O Eterno Paraíso\nVerde.",
  ["4e:43d8"] = "CIDADE VIRIDIANA\012LÍDER DO GINÁSIO\n#MON: …\012O resto do texto\nestá ilegível…",
  ["4e:441d"] = "Já faz um ano\ndesde a erupção\011do vulcão.",
  ["4e:4456"] = "BEM-VINDO À\nCIDADE VIRIDIANA,\012O PORTAL PARA O\nPLANALTO ÍNDIGO.",
  ["4e:44fc"] = "LIGA #MON\012ROTA DA VITÓRIA\nENTRADA.",
  ["4e:455e"] = "#MON insetos\nparecem bonecos\011de pelúcia quando\011se aperta suas\011barrigas.\012Eu os adoro!",
  ["4e:4592"] = "ROTA 2\012CIDADE VIRIDIANA-\nCIDADE PEWTER.",
  ["4e:45b2"] = "Se treinadores se\nencontram, a\011primeira coisa\011que eles fazem\011é batalhar!",
  ["4e:45f0"] = "Para treinadores,\né regra batalharem\011sempre se se\011encontrem.",
  ["4e:460c"] = "Você aí!\nDeseja batalhar?",
  ["4e:461b"] = "Você é forte.\012Obviamente deve\nter treinado duro.",
  ["4e:4650"] = "ROTA 1\012CIDADE PALLET-\nCIDADE VIRIDIANA.",
  ["4e:46c2"] = "I'm raising POKé-\nMON too.\012They serve as my\nprivate guards.",
  ["4e:46fb"] = "Tecnologia é\nincrível!\012Agora pode-se\ntrocar #MON\011através do tempo\011como um e-mail.",
  ["4e:4746"] = "CIDADE PALLET\012Tranqüilo Lugar\nde Paz & Pureza.",
  ["4e:4778"] = "Um…\nEu…",
  ["4e:4785"] = "Glug…",
  ["4e:479c"] = "BLUE'S HOUSE",
  ["4e:482b"] = "LABORATÓRIO DE\nPESQUISA DO\011PROFESSOR CARVA-\011LHO.",
  ["4e:4847"] = "Glug…",
  ["4e:484e"] = "Terra à vista!\nVamos continuar!",
  ["4e:487b"] = "Hi!\012I was just going\nto put some sun\011block on.",
  ["4e:48ab"] = "Se eu vencer,\nterá que me ajudar\011com minha loção\011de bronzear!",
  ["4e:48c6"] = "Tenho que me\npreocupar com os\011danos causados\011pelo sol.",
  ["4e:48fc"] = "Cansei de pescar.\nVamos batalhar!",
  ["4e:4921"] = "Falha total…",
  ["4e:4931"] = "Só vou voltar\na pescar…",
  ["4e:49a7"] = "Quem é você?\012Bem, é óbvio\nque você é um\011treinador…\012Meu nome é\nAZUL.\012Eu já fui o\nCAMPEÃO, porém foi\011por um curto\011tempo…\012Aquele intrometido\ndo VERMELHO me\011venceu…\012De qualquer modo,\no que você quer?\011Quer me desafiar\011ou outra coisa?\012…Odeio dizer isso,\nmas não estou\011muito à vontade\011para batalhas\011agora.\012Dê uma olhada\nao seu redor…\012Um vulcão entra em\nerupção e assim,\011uma cidade inteira\011desaparece.\n \012Em #MON se pode\nganhar ou perder.\011Mas se não\011tivermos cuidado,\011podemos perder em\011um segundo.\012…\012É desse jeito…\012Mas, de qualquer\nmodo, eu ainda\011sou um treinador.\012Se eu vejo um\noponente forte,\011me dá vontade de\011batalhar.\012Se quiser batalhar\ncomigo, venha\011ao GINÁSIO DE\011VIRIDIANA.\012Lá eu vou\ndesafiá-lo.",
  ["4e:4c48"] = "Há um aviso aqui…\012O GINÁSIO DE\nCINNABAR agora\011está nas ILHAS\011SEAFOAM.\012BLAINE.",
  ["4e:4c97"] = "ILHA CINNABAR\012A Quente Cidade\ndo Desejo Ardente.",
  ["4e:4d3d"] = "Sinto-me bem mais\nleve na água.",
  ["4e:4d5f"] = "Oh, não!",
  ["4e:4d68"] = "Nadar exercita\ntodo seu corpo.\012É realmente bom\npara você.",
  ["4e:4da5"] = "Que coleção\nincrível de\011INSÍGNIAS DE\011GINÁSIO.\012Nós devemos\nbatalhar!",
  ["4e:4de5"] = "Não!",
  ["4e:4dea"] = "SURFAR não é mais\no único golpe\011HM que se usa na\011água.",
  ["4e:4e20"] = "Acho que é\nimpossível nadar\011todo caminho até\011JOHTO.",
  ["4e:4e58"] = "Aiyah!",
  ["4e:4e60"] = "Além de no mar,\ntambém posso nadar\011em rios e lagos.",
  ["4e:4e97"] = "O que essa placa\ndiz?\012GINÁSIO CINNABAR\nLÍDER: BLAINE.",
  ["4e:4fa6"] = "Você já foi nadar\nno mar à noite?",
  ["4e:4fd8"] = "Glub…",
  ["4e:4fdf"] = "À noite, o mar\nfica preto. Parece\011até que ee vai\011engolir você.",
  ["4e:5025"] = "Puff, puff…\nSó… um pouco…\011mais… até…\011FUCHSIA…",
  ["4e:5058"] = "Estou afogando.",
  ["4e:5066"] = "Eu… Pedi a minha\nnamorada para\011nadar até FUCHSIA…\011Gasp…",
  ["4e:509a"] = "Detesto pessoas\nbobas!",
  ["4e:50b9"] = "Poderia vencê-lo\nna natação…",
  ["4e:50d8"] = "É um nado rápido\nentre FUCHSIA e\011as ILHAS SEAFOAM…\012Nossa, que grande\nhomem meu namorado\011é! Que bobão!",
  ["4e:5144"] = "Nadando?\nSou horrível\011nisso\n.\012Só estou me\ndebatendo nessas\011águas rasas.",
  ["4e:5191"] = "Pensei que podia\nvencer.",
  ["4e:51a9"] = "Posso ser ruim\nna natação, mas\011eu amo o mar.",
  ["4e:51da"] = "Perdão. Essa\nestrada está\011fechada para a\011construção.\012Se quiser chegar\na CINNABAR, é\011melhor ir pelo\011sul da CIDADE\011PALLET.",
  ["4e:524f"] = "Estou todo suado.\nHora de nadar!",
  ["4e:5270"] = "Quem sabe quanto\ndemorará para\011remover essa\011pedra…",
  ["4e:52a8"] = "A estrada já\nestá consertada.\012Agora posso ir\npescar de novo.",
  ["4e:52e7"] = "ROTA 19\012CIDADE FUCHSIA-\nILHAS SEAFOAM.",
  ["4e:5310"] = "Favor ter cuidado\nse você for nadar\011nas ILHAS SEAFOAM.\012POLÍCIA DE\nFUCHSIA.",
  ["4e:53eb"] = "One of the ELITE\nFOUR used to be\012the LEADER of\nFUCHSIA's GYM.",
  ["4e:5429"] = "A filha de KOGA\no sucedeu como\011LÍDER DE GINÁSIO\011depois dele ir\011para a ELITE\011QUATRO.",
  ["4e:5479"] = "A ZONA DO SAFÁRI\nestá fechada…\011É triste, pois é\011a maior atração\011de FUCHSIA.",
  ["4e:54c8"] = "CIDADE FUCHSIA\n\012Olhe! É a Paixão\nRosada!",
  ["4e:54f0"] = "CIDADE FUCHSIA\012LÍDER DO GINÁSIO\n#MON: JANINE\012A Venenosa Mestra\nNinja.",
  ["4e:5531"] = "Há um aviso\naqui…\012O ESCRITÓRIO DA\nZONA DO SAFÁRI\011estará fechada até\011segunda ordem.",
  ["4e:557b"] = "ZONA DO SAFARI\012CASA DO PATRÃO.",
  ["4e:5596"] = "O PATRÃO está\nviajando.\012Conseqüentemente,\na ZONA DO SAFÁRI\011está fechada.",
  ["4e:55dd"] = "Não bagunce.\012Favor levar seu\nlixo com você.",
  ["4e:56d3"] = "Se estiver procu-\nrando #MON,\011precisará olhar na\011grama alta.",
  ["4e:5713"] = "Aiieee!",
  ["4e:571c"] = "Como você é tão\nforte, deve\nser divertido\011batalhar.",
  ["4e:574e"] = "A PISTA DE\nCICLISMO é um\011curto atalho para\011CELADON.",
  ["4e:577c"] = "…Whew!",
  ["4e:5784"] = "Se não tiver\numa BICICLETA,\011não terá permissão\011para usar o\011atalho.",
  ["4e:57c8"] = "ROTA 18\012CIDADE CELADON-\nCIDADE FUCHSIA.",
  ["4e:587f"] = "Hey, you! You're\nfrom JOHTO, huh?",
  ["4e:58a1"] = "Uau, você é\ndemais!",
  ["4e:58b2"] = "Não se anime,\ndoidão de JOHTO!",
  ["4e:58d3"] = "Uau. Que BICICLETA\nlegal!",
  ["4e:58ef"] = "Mas você não é\ntão legal…",
  ["4e:590d"] = "Pareço legal,\nmas sou fraco,\011então não sou\011legal mesmo.\012Preciso treinar\nmais…",
  ["4e:5957"] = "Ei! Quer ter uma\nbatalha veloz?",
  ["4e:597a"] = "Nossa! Você tem\nótimas técnicas!",
  ["4e:599c"] = "Andar sem as mãos\né considerado\011legal na PISTA DE\011CICLISMO.",
  ["4e:59d3"] = "Somos as destemi-\ndas estrelas da\011pista!",
  ["4e:59f1"] = "Ahh… Tenho recorde\nde derrotas…",
  ["4e:5a0a"] = "Dirigir sem\ncuidado causa\011acidentes!\012Pega leve!",
  ["4e:5aa6"] = "CASA DA ALMA\012Deixe as Almas\ndos #MON\011Descansarem em\011Paz.",
  ["4e:5b3a"] = "This POLIWRATH is\nmy partner.\012I wonder if it'll\never evolve into a\011frog POKéMON.",
  ["4e:5b88"] = "POLIWRATH: Croak!",
  ["4e:5b9b"] = "Perdi nas máquinas\nde roleta de novo…\012Nós garotas também\nas jogamos agora.\012Você também\ndeveria jogá-las.",
  ["4e:5c00"] = "GRIMERS têm\naparecido\011ultimamente.\012Vê aquele lago\nem frente a casa?\011Os GRIMERS vivem\011lá agora.\012De onde eles\nvieram? Esse é um\011problema sério…",
  ["4e:5c99"] = "Nihihi! Esse\nGINÁSIO é ótimo!\011Só são permitidas\011garotas aqui!",
  ["4e:5cd2"] = "Quer ouvir um\nsegredo?\012A MANSÃO CELADON\ntem uma porta dos\011fundos oculta.",
  ["4e:5d12"] = "Estão fazendo um\nconcurso de comer\011no restaurante.\012Só de vê-los\ndevorar a comida\011já me deixa\011enjoado…",
  ["4e:5d7a"] = "A LOJA DE\nDEPARTAMENTOS DE\011CELADON tem a\011maior e melhor\011seleção de\011produtos.\012Se não achar algo\naqui, não o achará\011em lugar algum.\012É… Eu pareço uma\nvendedora.",
  ["4e:5e18"] = "Olhar para o chão\nenquanto andava\011me deixou tonta.",
  ["4e:5e52"] = "CIDADE CELADON\012A Cidade dos\nSonhos Arco-íris.",
  ["4e:5e7b"] = "CIDADE CELADON\012LÍDER DO GINÁSIO\n#MON: ERIKA\012A Princesa Amante\nda Natureza.",
  ["4e:5ebb"] = "Ache o que\nprecisar na LOJA\011DE DEPARTAMENTOS\011DE CELADON!",
  ["4e:5ee6"] = "A Diversão\nde Todos\012CASA DE JOGOS DE\nCELADON.",
  ["4e:5ef7"] = "A Diversão\nde Todos\012CASA DE JOGOS DE\nCELADON.",
  ["4e:5f2a"] = "DICAS DO TREINADOR\012A SUPER DEFESA\nprotege #MON\011de golpes\011ESPECIAIS como\011água e fogo.\012Compre seus\nitens na LOJA DE\011DEPARTAMENTOS DE\011CELADON!",
  ["4e:6081"] = "Treinadores que\nprocuram poder\011escalam o MONTE\011PRATA ignorando\011seus perigos.\012Com seus #MON\nconfiados, acham\011que podem ir a\011qualquer lugar…",
  ["4e:614f"] = "It's locked…",
  ["4f:407f"] = "Esqueceu-se de\nalguma coisa?",
  ["4f:409d"] = "Kyaaah!",
  ["4f:40a6"] = "Antes de ser uma\nprofessora, eu\011esquecia muitas\011coisas.",
  ["4f:40e4"] = "Em dias de\nsol, acho que\011as crianças\011prefeririam\011brincar no pátio\011da escola a\011estudar na sala\011de aula.",
  ["4f:414c"] = "Eu não queria\nperder…",
  ["4f:4163"] = "Estudar é\nimportante, mas\011se exercitar\011também é vital.",
  ["4f:419c"] = "Espere. Tenho\nque ligar para\011minha mãe.",
  ["4f:41be"] = "Perdão, mãe.\nFui derrotado!",
  ["4f:41d9"] = "Minha mãe se\npreocupa muito\011comigo e tenho que\011sempre ligar para\011ela.",
  ["4f:421d"] = "Vamos batalhar.\nNão perderei!",
  ["4f:4238"] = "Sayonara! Acabei\nde aprender isso\011na minha aula de\011japonês.",
  ["4f:4255"] = "Estamos numa\nexcursão de\011Estudos Sociais\011para a TORRE DE\011RÁDIO DE LAVENDER.",
  ["4f:428a"] = "CASA DO TREINADOR\012O Clube para\nGrandes Batalhas\011entre Treinadores.",
  ["4f:42cc"] = "TORRE DE BATALHAS\nACIMA.",
  ["4f:42e3"] = "Cansei de andar.\nPreciso de um\011descanso.",
  ["4f:4313"] = "Minha aula\npreferida é\011ginástica!",
  ["4f:432e"] = "Oh, não! Como pude\nperder?",
  ["4f:4349"] = "Se #MON fosse\nmatéria escolar,\011eu seria o melhor!",
  ["4f:437c"] = "ROTA 15\012CIDADE FUCHSIA-\nCIDADE LAVENDER.",
  ["4f:4458"] = "Deixe-me lhe\ncontar, custou-me\011capturar meu\011#MON premiado.",
  ["4f:4495"] = "Awaaah!",
  ["4f:449e"] = "SQUIRTLE,\nCHARMANDER e\011BULBASAUR…\012Acho que é uma\nmistura bem\011balanceada.",
  ["4f:44e8"] = "Meu sonho é voar\ncom meu querido\011#MON pássaro.",
  ["4f:4517"] = "Posso sonhar, mas\nnunca voar…",
  ["4f:453a"] = "Você tem #MON\nque sabem o\011golpe HM VOAR,\011não é?\012Eu o invejo.",
  ["4f:457a"] = "Did you battle all\nthe GYM trainers?",
  ["4f:45a0"] = "Oh, wow! Too\nstrong for me!",
  ["4f:45bd"] = "If you have KANTO\nBADGES, they'll\012help you in linked\nbattles.",
  ["4f:46a7"] = "Curve-se perante\nmeus #MON\011reais!",
  ["4f:46c7"] = "Como… Como ousou\nferir a realeza?",
  ["4f:46e8"] = "Não é que todos\nqueriam ser rei\011um dia?",
  ["4f:4714"] = "Nihihi! Gostaria\nde batalhar com\011minha gangue\011PIKACHU?",
  ["4f:4747"] = "PI-PIKACHU!",
  ["4f:4754"] = "Você parece ter\nvários #MON,\011mas PIKACHU ainda\011é o melhor.",
  ["4f:4796"] = "Agilidade é o\natributo chave do\011#MON pássaro.",
  ["4f:47c2"] = "Venceu-me com sua\nrapidez…",
  ["4f:47e0"] = "Seus #MON\nsão certamente bem\011treinados.",
  ["4f:4809"] = "Check out my POKé-\nMON. Just look at\012their coloring and\ntheir plumage.",
  ["4f:484e"] = "Droga!\nNão muito bom!",
  ["4f:4867"] = "Se enfeitá-los,\nos #MON se\011alegram.",
  ["4f:488b"] = "Devo ir ao TÚNEL\nDE ROCHA para\011pegar meu ONIX.",
  ["4f:48be"] = "Perdi…",
  ["4f:48c7"] = "Características\ngeológicas parecem\011não mudar.\012Mas na verdade\nmudam, bem aos\011poucos.",
  ["4f:4921"] = "DICAS DO TREINADOR\012Olhe! Bem ali, à\nesquerda do da\011placa.",
  ["4f:4960"] = "ROTA 13\012NORTE: PONTE DO\nSILÊNCIO.",
  ["4f:4982"] = "NORTE: CIDADE\nLAVENDER\012OESTE: CIDADE\nFUCHSIA.",
  ["4f:4a69"] = "Patience is the\nkey to both fish-\011ing and POKéMON.",
  ["4f:4a9a"] = "Gwaaah!",
  ["4f:4aa3"] = "Sou muito\nimpaciente para\011pescar…",
  ["4f:4ac2"] = "Sinto-me tão\nfeliz, pescar\011enquanto ouço umas\011músicas em meu\011rádio.",
  ["4f:4b0b"] = "Meu rádio bobo me\ndistraiu!",
  ["4f:4b2b"] = "Have you checked\nout KANTO's radio\012stations? We get a\ngood variety here.",
  ["4f:4b74"] = "O que é mais\nimportante em\011nossas vidas todo\011dia?",
  ["4f:4ba5"] = "A resposta já\nvai vir!",
  ["4f:4bc4"] = "Acho que a\neletricidade é\011a coisa mais\011importante em\011nossa vida diária.\012Se não fosse, as\npessoas não teriam\011entrado em pânico\011quando a USINA ELÉTRICA parou de\011funcionar.",
  ["4f:4c6b"] = "Você se lembra?",
  ["4f:4c7d"] = "Você se lembra?",
  ["4f:4c8f"] = "The tug you feel\non the ROD when\012you hook a POKé-\nMON…\012That's the best\nfeeling ever for\011an angler like me.",
  ["4f:4cf7"] = "ROTA 12\012NORTE: CIDADE\nLAVENDER.",
  ["4f:4d18"] = "PONTO DE PESCA.",
  ["4f:4de8"] = "É proibido roubar\nem #MON.\012Vamos fazer uma\npartida limpa!",
  ["4f:4e25"] = "Hã? Como isso\naconteceu?",
  ["4f:4e40"] = "Eu fiz uma luta\nlimpa com honra.\012Não me arrependo\nde nada.",
  ["4f:4e81"] = "Tenho muita\ncoceira quando\011visto uma bermuda\011curta na grama.",
  ["4f:4ebf"] = "Aiyaaah!\nFui pisado!",
  ["4f:4ed8"] = "Vou pegar mais\n#MON na grama.",
  ["4f:4f09"] = "…\012Perdi quando\nestava de olhos\011fechados…",
  ["4f:4f2f"] = "Não posso ver…\012Tudo ao seu\nrespeito…",
  ["4f:4f5b"] = "Não pude prever\nseu poder…",
  ["4f:4f7a"] = "Força é convicção…\012Você é forte\nporque acredita\011em seus #MON.",
  ["4f:4fc6"] = "ROTA 11.",
  ["4f:5048"] = "KANTO tem vários\nprogramas de rádio\011bons.",
  ["4f:5080"] = "Pessoas vêm de\ntodos lugares para\011homenagear as\011almas dos #MON\011mortos.",
  ["4f:50a2"] = "Você precisa\nde uma #\011FLAUTA para\011acordar #MON\011dorminhocos.\012Todo treinador\ntem que saber\011disso!",
  ["4f:50f2"] = "You need a POKé\nFLUTE to wake\011sleeping POKéMON.\012Every trainer has\nto know that!",
  ["4f:513d"] = "VOLUNTÁRIO DE\nLAVENDER\012CASA DE #MON.",
  ["4f:5162"] = "Fui chicoteado!",
  ["4f:51a7"] = "CAVERNA DO\nDIGLETT.",
  ["4f:51c6"] = "CASA DO AZUL.",
  ["4f:5308"] = "VERMILION PORT is\nKANTO's seaside\011gateway.\012Luxury liners from\naround the world\011dock here.",
  ["4f:5362"] = "Meu #MON está\npreparando a área\011para a construção.\012Mas não tenho\ndinheiro para\011começar o projeto…",
  ["4f:53bd"] = "MACHOP: Guooh\ngogogoh!",
  ["4f:53d5"] = "O MACHOP está\nrugindo enquanto\011achata o terreno.",
  ["4f:540d"] = "Há oito GINÁSIOS\nem KANTO.\012Esse grande prédio\né o GINÁSIO #-\011MON DE VERMILION.",
  ["4f:5457"] = "O SNORLAX está\nroncando em paz…",
  ["4f:5477"] = "The POKéGEAR was\nplaced near the\011sleeping SNORLAX…\012…\012SNORLAX woke up!",
  ["4f:54bb"] = "Habilidosos trei-\nnadores se reúnem\011em KANTO.\012Os LÍDERES DE\nGINÁSIO são muito\011fortes.\012Não será fácil\nvencê-los.",
  ["4f:551e"] = "Você começou a\ncoletar INSÍGNIAS\011GINÁSIOS DE KANTO?\012Não acha fortes\nos treinadores\011daqui?",
  ["4f:557b"] = "Acho que em breve\nterminará com sua\012conquista aos\nGINÁSIOS DE KANTO.\012Deixe-me saber se\npegou as oito\011INSÍGNIAS.",
  ["4f:55e6"] = "Parabéns!\012Pegou todas INSI-\nGNIAS DE KANTO.\012Vou presenteá-lo\npor seus esforços.",
  ["4f:563d"] = "Ter vários tipos\nde #MON deve\012ajudá-lo nas\nbatalhas.\012Eu sei que as\nINSÍGNIAS DE KANTO\011vão ajudá-lo.",
  ["4f:56ac"] = "CIDADE VERMILION\012O Porto do lindo\nPôr-do-sol.",
  ["4f:56da"] = "CIDADE VERMILION\012LÍDER DO GINÁSIO\n#MON: TENENTE\nSURGE.\012O americano relâm-\npago.",
  ["4f:571b"] = "FÃ CLUBE #MON\012Bem-vindos Fãs\n#MON!",
  ["4f:5741"] = "DIGLETT'S CAVE",
  ["4f:5751"] = "ENTRADA DO PORTO\nDE VERMILION.",
  ["4f:5820"] = "The road is closed\nuntil the problem\012at the POWER PLANT\nis solved.",
  ["4f:5864"] = "UNDERGROUND PATH\012CERULEAN CITY -\nVERMILION CITY",
  ["4f:5923"] = "A garota DUPLICA\nparecia triste.\012Ela disse que\nperdeu sua BONECA\011predileta, a\011CELFAIRY.",
  ["4f:59a3"] = "The COPYCAT girl\nlooked unhappy.\012She said she lost\nher favorite POKé\011DOLL--CLEFAIRY.",
  ["4f:59f6"] = "Você veio de\nJOHTO?\012Poderia voltar\npara casa se o\011TREM IMÃ estivesse\011funcionando.",
  ["4f:5a44"] = "Você veio de\nJOHTO?\012Pode voltar para\ncasa através do\011TREM IMÃ.",
  ["4f:5a94"] = "Fui ao GINÁSIO\nquerendo batalhar\011com treinadores…\012Tudo ficou confuso\ne eu fui parar no\011GINÁSIO ao lado.\012Cara, eu\nfiquei bastante\011embaraçado.",
  ["4f:5b24"] = "Essa é a\nCORPORAÇÃO SILPH,\011famosa por seus\011produtos #MON.\012No passado, a\nEQUIPE ROCKET\011queria a compania\011por causa disso.",
  ["4f:5b92"] = "Chew… Chew…\012Soube que há um\ngrande problema\011na USINA ELÉTRICA.\n\012Chew… Chew…",
  ["4f:5be1"] = "Chew… Chew…\012Soube que havia\num grande problema\011na USINA ELÉTRICA.\012Chew… Chew…\nHaah, cansei!",
  ["4f:5c3b"] = "Ir ao beco pela\nprimeira vez me\011deixa ansioso.",
  ["4f:5c7b"] = "Há um lugar\nchamado CASA DO\011TREINADOR em\011VIRIDIANA onde\011treinadores de todos\011lugares se reúnem.",
  ["4f:5cdb"] = "Nossa cidade foi\ncitada em um\011programa de rádio.\012É bom ouvir\nelogios para sua\011cidade, mas é\011embaraçoso também.",
  ["4f:5d4d"] = "CIDADE SAFFRON\012O Brilhante Ponto\nComercial Dourado.",
  ["4f:5d7c"] = "CIDADE SAFFRON\012LÍDER DO GINÁSIO\n#MON: SABRINA\012A Mestra\ndos #MON\011Psíquicos!",
  ["4f:5dbf"] = "Sejam Todos\nBem-vindos!\012GINÁSIO DE LUTA.",
  ["4f:5de0"] = "CORPORAÇÃO SILPH\012PRÉDIO DE\nESCRITÓRIO.",
  ["4f:5dfb"] = "CASA DO SENHOR\nPSÍQUICO.",
  ["4f:5e0f"] = "CIDADE SAFRON\012ESTAÇÃO DO\nTREM ÍMÃ.",
  ["4f:5f1e"] = "The road is closed\nuntil the problem\012at the POWER PLANT\nis solved.",
  ["4f:5f62"] = "UNDERGROUND PATH\012CERULEAN CITY -\nVERMILION CITY",
  ["4f:5f93"] = "CAMINHO DO SUBSOLO\012CIDADE CERULEANA-\nCIDADE VERMILION.",
  ["4f:60b0"] = "KANTO's POWER\nPLANT is toward\012the end of ROUTE\n9. There was an\012accident of some\nsort there.",
  ["4f:610c"] = "Você está\ncoletando todo\011tipo de #MON?\012Deve ser bastante\ndesafiador, mas\011isso parece\011divertido também.",
  ["4f:6170"] = "A PENÍNSULA ao\nnorte é um\011bom lugar para\011encontros.\012As garotas adoram!",
  ["4f:61b1"] = "SLOWBRO: Yarah?",
  ["4f:61c2"] = "Meu SLOWBRO e\neu fazemos uma\011ótima combinação!",
  ["4f:61f1"] = "SLOWBRO, mostre-me\nsua CONFUSÃO!",
  ["4f:6216"] = "Sou um grande\nfã da MISTY\011do GINÁSIO DE\011CERULEANA.",
  ["4f:623d"] = "Vi um cara\nestranho indo\011à PENINSULA\011CERULEANA.",
  ["4f:6271"] = "Havia uma caverna\nque tinha #MON\011extremamente\011fortes nela.",
  ["4f:62b6"] = "Ayuh?\012Meu ACHA\nITENS está\011respondendo.",
  ["4f:62da"] = "CIDADE CERULEANA\012Uma Misteriosa\nÁura Azul a\011Envolve.",
  ["4f:630d"] = "CIDADE CERULEANA\012LÍDER DO GINÁSIO\n#MON: MISTY\012A Mais Bela\nSereia.",
  ["4f:6349"] = "Há um aviso aqui…\012A LOJA DE\nBICICLETA se mudou\011para a CIDADE\011GOLDENROD em\011JOHTO…",
  ["4f:6394"] = "Há um aviso aqui…\012Acabar com\na Bandidagem e\011tornar a cidade\011um lugar mais\011amigável e\011animado!\012POLÍCIA DE\nCERULEANA.",
  ["4f:6403"] = "PENÍNSULA CERULE-\nANA A SEGUIR.",
  ["4f:6418"] = "It's locked…",
  ["50:4080"] = "I came to explore\nROCK TUNNEL.",
  ["50:40a0"] = "Uau! Perigo,\ncara.",
  ["50:40b4"] = "Meus #MON\nforam feridos\011antes mesmo de\011entrarmos no\011TÚNEL DE ROCHA.\012É melhor eu\nlevá-los ao CENTRO\011#MON.",
  ["50:411a"] = "Já esteve em um\npiquenique?\012Eles são tão\ndivertidos!",
  ["50:414f"] = "Ohhhh!",
  ["50:4157"] = "Fazemos muitas\ngostosuras e as\011dividimos com\011todos.\012São deliciosas!",
  ["50:419d"] = "Ei, você!\nNão bagunce!",
  ["50:41b5"] = "Eu só estava\nfalando que…",
  ["50:41d1"] = "Perdão. Você não\nestava bagunçando.\011Foi erro meu.",
  ["50:4202"] = "As pessoas não\ndeviam deixar lixo\011para trás.",
  ["50:422c"] = "Ohh… Perdi…",
  ["50:423a"] = "Conservar enegia\né importante, mas\011o meio-ambiente é\011ainda mais vital.",
  ["50:4283"] = "Ela vai vir do\nMONTE PRATA,\011quando ela vir…\012O MONTE PRATA é\nem JOHTO, certo?",
  ["50:42d2"] = "Estava ocupado\ncantando…",
  ["50:42eb"] = "As batalhas exigem\nconcentração.",
  ["50:430d"] = "Contarei-lhe um\nsegredo.\012Mas primeiro,\nbatalhamos!",
  ["50:433b"] = "Oh, droga! Perdi\nessa…",
  ["50:4353"] = "A USINA ELÉTRICA\né após um pequeno\011rio.",
  ["50:437d"] = "MANSÃO CELADON.",
  ["50:443b"] = "Hey, kid! Me am a\nTEAM ROCKET member\011kind of guy!\012Come from another\ncountry, a trainer\011number one, me!\012Think I did, if\nstop the energy,\012be big panic for\nhere people!\012Secret it is my\nmission, so tell\011you I not!\012But! If win you do\nversus me, a man I\012be and mine secret\nto you I tell.\012Hey, kid! Battle\nbegin we do!",
  ["50:4574"] = "Ayieeeh! Não, não,\nnão, nisso não\011acredito!\012Muito forte você\né! Páreo para você\011não sou!",
  ["50:45cd"] = "OK. Tell you mine\nsecret will I.\012MACHINE PART steal\nby me, hide it I\012did in GYM of the\nCERULEAN.\012Inside water put\nit I did. Look for\012in water center of\nGYM at.\012Boy, but you\nforget me not!\012Beat you for sure\nwill TEAM ROCKET.\012Come from JOHTO\nwill they, mine\012friends, yes. Will\nrevenge they are.",
  ["50:46f3"] = "…\012Você disse o quê?\nEQUIPE ROCKET\011Adeeeeeus? Acabou\011foi o que disse?\012Oh, não! A partir\nde agora, o que\011devo fazer?",
  ["50:48e7"] = "MISTY: Aww! Por\nque você tem que\011aparecer agora e\011nos incomodar?\012Sabe como\nchamam-se pessoas\011como você?\012Pestes! É isso\nmesmo, peste!\012…\012…Oh? Essas\nINSÍGNIAS que\011tem… São INSÍGNIAS\011DOS GINÁSIOS DE\011JOHTO?\012Se tem oito,\ndeve ser bom.\012Certo, então.\nVenha ao GINÁSIO\011DE CERULEANA.\011Ficarei feliz em\011desafiá-lo.\012Eu, MISTY, LÍDER\nDO GINÁSIO em\011CERULEANA.",
  ["50:4a2e"] = "Vença os seis\ntreinadores para\011ganhar um prêmio\011fabuloso! Acha\011que consegue?",
  ["50:4a83"] = "Eu desisto!",
  ["50:4a96"] = "Fiz meu melhor.\nNão me arrependo.",
  ["50:4ab9"] = "Sou a segunda.\nAgora é sério!",
  ["50:4ad6"] = "Como pude perder?",
  ["50:4ae9"] = "Fiz meu melhor.\nNão me arrependo.",
  ["50:4b0c"] = "Eis o número 3.\nNão serei fácil.",
  ["50:4b2a"] = "Ow! Fui pisoteado!",
  ["50:4b3d"] = "Fiz meu melhor.\nNão me arrependo.",
  ["50:4b60"] = "Sou o número 4!\nEstá cansado?",
  ["50:4b7a"] = "Também perdi…",
  ["50:4b87"] = "Fiz meu melhor.\nNão me arrependo.",
  ["50:4baa"] = "Certo. Sou o\nnúmero 5. Vou\011estourá-lo!",
  ["50:4bc8"] = "Uau! Muito bom!",
  ["50:4bd9"] = "Fiz meu melhor.\nNão me arrependo.",
  ["50:4bfc"] = "Sou a última da\nfila, mas lhe\011digo, sou forte!",
  ["50:4c2c"] = "You're kidding.",
  ["50:4c3c"] = "Fiz meu melhor.\nNão me arrependo.",
  ["50:4c5f"] = "Mufufufu…\012Não estou\nrelacionado ao\011conjunto dos seis\011treinadores.\012Esperei aqui para\nvencê-lo quando\011ficasse cansado\011de todas as\011batalhas.",
  ["50:4ce2"] = "Não está cansado\nmesmo?",
  ["50:4cfb"] = "Perdão… Não\ntrapacearei mais…",
  ["50:4d1c"] = "Você enfrentou uma\nbatalha a mais do\011que esperava,\011mas venceu mesmo\011assim.\012Como prometi,\nreceberá um\011prêmio.",
  ["50:4d7e"] = "Mas após ver\ncomo você batalha,\011quero ver como me\011saio.\012Que tal? Deixe-me\ndesafiá-lo.",
  ["50:4dde"] = "Nunca tive uma\nbatalha tão boa!",
  ["50:4e01"] = "That was a great\nbattle!\012You and your POKé-\nMON are truly out-\011standing!",
  ["50:4e48"] = "CABANA DO MAR\nCASA DO BILL.",
  ["50:4f79"] = "Ah! O tempo está\nbom como sempre.",
  ["50:4f9c"] = "Faz sol, mas\nestou molhado…",
  ["50:4fb8"] = "Quando chove, é\ndifícil fazer\011fogo…",
  ["50:4fe2"] = "Hmmm… Não sei o\nque fazer…",
  ["50:5001"] = "I knew I'd lose…",
  ["50:5012"] = "Você parecia\nforte.\012Fiquei com medo de\ndesafiá-lo…",
  ["50:5043"] = "Posso correr como\no vento!",
  ["50:505d"] = "Hahahahahaha!",
  ["50:506a"] = "Visto calções o\nano inteiro.\012É minha política\nde moda.",
  ["50:50a8"] = "Dê um passo e dê\numa olhada!",
  ["50:50c8"] = "Uau! É quente!",
  ["50:50d9"] = "O melhor sopra\nfogo em KANTO,\011sou eu.\012Mas não sou o\nmelhor treinador…",
  ["50:5124"] = "PRAÇA DO MONTE LUA\012Apenas suba as\nescadas.",
  ["50:51d5"] = "There's been news\nof an incident at\011the POWER PLANT.",
  ["50:520a"] = "I lost? That's\nnews too…",
  ["50:5223"] = "I might go to the\nPOWER PLANT. Is it\011near ROCK TUNNEL?",
  ["50:525b"] = "Sinto que eu\nvou vencer.\012Vamos ver se\ntenho razão!",
  ["50:5293"] = "Aww, você é muito\nforte.",
  ["50:52ad"] = "Soube que\nCLEFAIRIES surgem\011no MONTE LUA.\n \012Mas onde poderiam\nestar?",
  ["50:52eb"] = "Um…\nI…",
  ["50:52f6"] = "……Vou treinar\nmais…",
  ["50:5311"] = "PRAÇA DO MONTE LUA\012Apenas suba as\nescadas.",
  ["50:53ef"] = "Somos o grupo\nde treinadores da\011FEDERAÇÃO KANTO\011DE #MON.\012Vamos passar por\ncima de você!",
  ["50:543f"] = "P-perdão!",
  ["50:5449"] = "A FEDERAÇÃO KANTO\nDE #MON nunca\011acabará!",
  ["50:5475"] = "Os tiras fecharam\no CAMINHO DO\011SUBSOLO!\012Isso realmente me\nirrita!",
  ["50:54b5"] = "P-perdoe-me!",
  ["50:54c4"] = "Derrotado por um\ndoidão de JOHTO…",
  ["50:54e8"] = "We're the KANTO\nPOKéMON FEDERA-\011TION!\011Right on, dude!",
  ["50:551b"] = "Droga! Perdão!",
  ["50:552a"] = "Tentaremos não\nperturbar ninguém\011a partir de agora…",
  ["50:5557"] = "Como funciona o\nTREM ÍMÃ?",
  ["50:557a"] = "Só quero ver o\nTREM ÍMÃ…",
  ["50:55a0"] = "O poder dos ímãs\né fantástico!",
  ["50:55c4"] = "We can't do with-\nout electricity.\012The POWER PLANT\nsupplies us with\011electricity.",
  ["50:5615"] = "Don't waste\nelectricity!",
  ["50:562e"] = "The POWER PLANT\nnorth of LAVENDER\012supplies power to\nthe MAGNET TRAIN.",
  ["50:5675"] = "It's locked…",
  ["50:5682"] = "O aviso está\nrasgado.\012É impossível\nler…",
  ["50:571c"] = "USINA ELÉTRICA DE KANTO.",
  ["50:5776"] = "Aaaaaaa!",
  ["50:5780"] = "Aaaaa-tchinnn!",
  ["50:5790"] = "Binha gribe está\nme fazendo\011esbirrar!\012Aaa-TCHIN!",
  ["50:57bd"] = "Você gosta de\n#MON, não é?\012Eu também!",
  ["50:57df"] = "Devo dizer que é\nminha derrota.",
  ["50:57fe"] = "Veja o que fez\naos meus #MON…\012Não esquecerei\nisso…",
  ["50:5831"] = "ROTA 10\012CIDADE CERULEANA-\nCIDADE LAVENDER.",
  ["50:588f"] = "Arrrgh! Bateu,\npegou fogo!",
  ["51:400e"] = "Sailors are really\ngenerous.\012One taught my\nPOKéMON STRENGTH.\012Now it can move\nbig boulders.",
  ["51:4067"] = "Há uma pessoa na\nCIDADE CIANWOOD\011após o mar.\012Ouvi ele se\ngabando de seu\011#MON raro.",
  ["51:419a"] = "…Obrigada por usa\najuda no FAROL…\012Mas isso já é\ndiferente.\012Permita que eu me\nintroduza.\012Eu sou JASMINE, a\nLÍDER DO GINÁSIO.\011Eu uso o tipo-aço.\012…Você conhece o\ntipo-aço?\012É um tipo que\nfoi recentemente\011descoberto.\012…Hm… Posso\ncomeçar?",
  ["51:429c"] = "…Você é um\ntreinador melhor\011do que eu, tanto\011na habilidade\011quanto na\011gentileza.\012De acordo com as\nregras da LIGA,\011eu lhe confiro\011essa INSÍGNIA.",
  ["51:431b"] = "{PLAYER} received\nMINERALBADGE.",
  ["51:4335"] = "A INSÍGNIA MINERAL\nmelhora a DEFESA\011dos #MON.\012…Hm… Leve isso\ntambém…",
  ["51:4386"] = "…Você poderia usar\nesse TM para\011ensinar a CAUDA\011FERRO.",
  ["51:43b2"] = "Hm… Não sei como\ndizer isso, mas,\011boa sorte…",
  ["51:43e3"] = "JASMINE usa o\ntipo-aço que\011foi descoberto\011recentemente. Não\011sei muito sobre\011ele.",
  ["51:4432"] = "Isso foi incrível.\012O tipo-aço, hã?\012Foi um confronto\ndireto com o tipo\011desconhecido!",
  ["51:4489"] = "JASMINE, a LÍDER\nDO GINÁSIO, está\011no FAROL.\012Ela está cuidando\nde um #MON\011doente.\012Um treinador forte\nprecisa ter\011compaixão.",
  ["51:4583"] = "Quando meu #MON\nadoeceu, o\011FARMACEÚTICO em\011ECRUTEAK me fez\011uns remédios.",
  ["51:45d1"] = "RHYDON: Gugooh!",
  ["51:4624"] = "No caminho para\nCIANWOOD, há\011quatro ilhas\011desertas.\012As crianças más\nsão levadas para\011as ilhas como\011punição!",
  ["51:4692"] = "Sempre que me\nencrenco, o meu\011Pai me assusta.",
  ["51:472a"] = "OLIVINE está no\nmar!\012E se está no mar,\nsignifica que há\011muita pescaria!\012Eu pesquei aqui\npor 30 anos.\012Você gostaria de\nencarar o mar e\011pescar?",
  ["51:47bc"] = "Ah, haha! Temos\num novo pescador!",
  ["51:47e8"] = "Os peixes não\nestão só no mar.\012Eles estão em\ntodo lugar que há\011água.",
  ["51:482d"] = "O queê? Você não\ngosta de pescar!?\011É imcompreensível!",
  ["51:4860"] = "Como vai você?\nPegou um grandão?",
  ["51:48bd"] = "Hah! Your POKéMON\nsure look like\011lightweights!\012They don't have\nthe power to move\011boulders aside.\012Here, use this\nand teach them\011STRENGTH!\012You'll need\nGOLDENROD's GYM\012BADGE to use that\noutside battles.",
  ["51:4980"] = "No mar, a única\ncoisa com que pode\011contar é você\011mesmo!\012Estou tão\norgulhoso do meu\011corpo!",
  ["51:49e0"] = "Crossing the sea?\nThen listen up!\012There are whirl-\npools on the way\011to CIANWOOD.\012Your POKéMON must\nknow a special\012move to get over\nthe whirlpools.",
  ["51:4aaa"] = "Do your POKéMON\nalready know the\012move for carrying\npeople on water?",
  ["51:4aec"] = "Minha BUTTERFREE\nveio do meu\011namorado do outro\011lado do mar.\012Ela trazia uma\nCARTA dele.\012Quer saber o que\nela diz?\012Deixe-me ver…\nNada! É segredo!",
  ["51:4bb0"] = "Where did you say\nyou're from?\012NEW BARK TOWN?\012PROF.ELM lives\nover there, right?\012You've come a long\nway to get here.",
  ["51:4d04"] = "MOOMOO is sick…\012She needs lots of\nBERRIES.",
  ["51:4d30"] = "Estamos dando\ncomida à MILTANK.",
  ["51:4d46"] = "Seu mugido está\nfraco…",
  ["51:4d56"] = "Seu mugido está\nfraco…",
  ["51:4d68"] = "Seu mugido está\nfraco…",
  ["51:4d77"] = "Dar um GRÃO à\nMILTANK?",
  ["51:4d91"] = "{PLAYER} deu um\nGRÃO à MILTANK.",
  ["51:4dad"] = "A MILTANK ficou\num pouco mais\011saudável!",
  ["51:4dd1"] = "A MILTANK ficou\nmais saudável!",
  ["51:4df0"] = "A MILTANK\nestá totalmente\011saudável!",
  ["51:4e11"] = "{PLAYER} não tem\nGRÃOS…",
  ["51:4e24"] = "{PLAYER} não dará\num GRÃO.\012A MILTANK parece\ntriste.",
  ["51:4f0d"] = "My MILTANK ain't\ngivin' me milk\011nomore.\012This here FARM's\ngot famous milk.\012Most everyone\nwants a drink.\012It'll give me lots\no' milk if'n I\012feed it lots o'\nBERRIES, I reckon.",
  ["51:4fb7"] = "How'd you like my\nMOOMOO MILK?\012It's my pride and\njoy, son.\012Give it to POKéMON\nto restore HP!\012I'll give it to ya\nfer just ¥500.",
  ["51:5031"] = "Aqui está!\nBeba e divirta-se!",
  ["51:5050"] = "Sorry, son.\nNo cash, no sale!",
  ["51:506f"] = "I reckon yer\nPACK's full, son.",
  ["51:508e"] = "Você não o quer?\nVolte depois,\011certo?",
  ["51:50b3"] = "É melhor eu ir\nordenhar.",
  ["51:50cd"] = "Nosso leite vai\naté para KANTO.\012Logo, se nossa\nMILTANK não nos\011der leite, teremos\011problemas.",
  ["51:512d"] = "Você curou nossa\nMILTANK.\012Agora ela dá LEITE\nMOOMOO de novo.\012Eis algo para os\nseus problemas.",
  ["51:519e"] = "É o RONCAR.\012É um golpe raro\nque só funciona\011enquanto o #MON\011estiver dormindo.\012É melhor pensar\nbem quando se deve\011usá-lo, rapaz.",
  ["51:526c"] = "Eu soube que um\nGYARADOS vermelho\011apareceu no LAGO.\012É estranho, sendo\nque até GYARADOS\011comuns são raros\011naquele lago…",
  ["51:52de"] = "Meu programa de\nrádio preferido?\012É o MÚSICA\n#MON.",
  ["51:530d"] = "Eu escutei risos\nno rádio…\012É horripilante.",
  ["51:545d"] = "Os #MON\ntêm várias\011experiências em\011suas vidas, como\011nós.\012Eu, também, vi\ne sofri muito em\011minha vida.\012Como sou mais\nvelho, deixe-me\011ensinar o que eu\011quero dizer.\012Eu estive com\n#MON desde\011antes de você\011nascer.\012Eu não perco\nfacilmente.\012Eu, PRYCE--o\ntreinador do\011inverno--vou\011demonstrar meu\011poder!",
  ["51:5583"] = "Ah, estou\nimpressionado pela\011sua proeza.\012Ah, com sua força\nde vontade, você\011vai superar todos\011os obstáculos.\012Você merece essa\nINSÍGNIA!",
  ["51:560b"] = "{PLAYER} received\nGLACIERBADGE.",
  ["51:5625"] = "Essa INSÍGNIA\nmelhorará o\011ESPECIAL dos\011#MON.\012Também permite seu\n#MON usar\011o REDEMOINHO\011para atravessar\011redemoinhos.\012E isso… Isso é um\npresente meu!",
  ["51:56bf"] = "Esse TM contém o\nVENTO GELADO.\012Ele causa danos\ne reduz a\011velocidade.\012Isso demonstra a\ndureza do inverno.",
  ["51:5729"] = "When the ice and\nsnow melt, spring\011arrives.\012You and your POKé-\nMON will be to-\012gether for many\nyears to come.\012Cherish your time\ntogether!",
  ["51:57b1"] = "Vou congelar seus\n#MON e não\011poderão fazer\011nada!",
  ["51:57e0"] = "Droga. Não pude\nfazer nada.",
  ["51:57fd"] = "Acho que tem um\ngolpe que um\011#MON pode\011usar quando\011congelado.",
  ["51:5835"] = "Esse GINÁSIO\ntem um chão\011escorregadio.\012É legal, né?\012Mas--não estamos\nbrincando aqui!",
  ["51:588d"] = "Você vê o quanto\nsomos sérios?",
  ["51:58ad"] = "O GINÁSIO é ótimo.\nAdoro deslizar com\011meus #MON!",
  ["51:58df"] = "Eu sei o segredo\nde PRYCE.",
  ["51:58f6"] = "Certo, lhe\ncontarei o segredo\011de PRYCE.",
  ["51:5917"] = "O segredo da força\nde PRYCE…\012Ele medita embaixo\nda cachoeira\011diariamente para\011fortalecer seu\011corpo.",
  ["51:597e"] = "Para alcançar\nPRYCE, LÍDER DO\011GINÁSIO, você\011precisa pensar\011antes de deslizar.",
  ["51:59c4"] = "Não perderia para\nvocê no esqui!",
  ["51:59e6"] = "Se você não\ndeslizar com\011precisão, não\011avançará nesse\011GINÁSIO.",
  ["51:5a27"] = "Olhe meu turno\nparalelo!",
  ["51:5a44"] = "Não! Deixou-me\ncom raiva!",
  ["51:5a5f"] = "Eu não deveria\nme gabar quanto\011ao meu esqui…",
  ["51:5a8f"] = "PRYCE é um\nveterano que\011treina #MON\011por mais de 50\011anos.\012Dizem que ele é\nbom em congelar\011oponentes com\011golpes do tipo\011gelo.\012Quer dizer\nque você deve\011derretê-lo com sua\011quente ambição!",
  ["51:5b45"] = "PRYCE é algo, mas\nvocê é algo a\011mais!\012Essa foi uma\nquente batalha que\011trouxe à tona o\011espaço entre\011gerações!",
  ["51:5c32"] = "O que é isso?\nA EQUIPE ROCKET\011voltou?\012Eu vi um homem de\npreto no LAGO DA\011RAIVA…",
  ["51:5c83"] = "Eu impedi meus\n#MON de\011evoluírem muito\011cedo.\012Fi-los aprender\ncertos golpes\011antes de deixá-los\011evoluir.",
  ["51:5ce8"] = "Os #MON ficam\nmais fortes\011quando evoluem,\011mas também\011aprendem golpes\011mais tarde.",
  ["51:5d88"] = "MOUNT MORTAR is\nlike a maze.\012Be careful. Don't\nget lost in there.",
  ["52:406c"] = "A TORRE ESTRANHA\nestá fora do\011alcance de quem\011não tem a INSÍGNIA\011DO GINÁSIO DE\011ECRUTEAK.\n\012Você terá que\nsair.",
  ["52:40cc"] = "A TORRE ESTRANHA\nestá fora do\011alcance de quem\011não tem a INSÍGNIA\011DO GINÁSIO DE\011ECRUTEAK.\012Oh! A INSÍGNIA\nDO GINÁSIO DE\011ECRUTEAK!\012Você pode ir.",
  ["52:413f"] = "The TIN TOWER up\nahead was built\012as a roost for\nflying POKéMON.",
  ["52:417d"] = "A TORRE ESTRANHA\ntremeu. Um #MON\011deve ter retornado\011ao topo!",
  ["52:41b9"] = "Duas torres…\nDois #MON…\012Mas quando uma\nqueimou, ambos\011#MON foram\011embora e nunca\011retornaram.",
  ["52:4304"] = "Oi, sou BILL.\nE quem é você?\012Hum, {PLAYER}, hã?\nVocê veio na hora\011certa.",
  ["52:434e"] = "Eu acabei agora\nos ajustes na\011minha CÁPSULA DO\011TEMPO.\012Você sabe que um\n#MON pode ser\011trocado, certo?\012Minha CÁPSULA DO\nTEMPO foi feita\011para permitir\011trocas com o\011passado.\012Mas não se pode\nenviar algo que\011não existia no\011passado.\012Se o fizer, o\nCOMPUTADOR no\011passado vai ter\011problemas.\012Então você deve\nremover tudo que\011não havia no\011passado.\012Simplesmente, não\nenvie novos golpes\011ou novos #MON\011na CÁPSULA DO\011TEMPO.\012Não se preocupe.\nEu já acabei os\011ajustes.\012Amanhã, as\nCÁPSULAS DO\011TEMPO estarão\011funcionando em\011todos CENTROS\011#MON.\012Tenho que voltar\nrápido para\011GOLDENROD para ver\011meus conhecidos.\012Tchaaau!",
  ["52:4581"] = "O modo em que as\nGAROTAS KIMONO\011dançam é\011explêndido.\012Do jeito que elas\nusam seus\011#MON!",
  ["52:45d6"] = "MORTY, o LÍDER\nDO GINÁSIO, é\011tãão legal.\012Seus #MON são\nbem fortes também.",
  ["52:461c"] = "LAGO DA RAIVA…\012A aparição de\num enxame de\011GYARADOS…\012Isso me cheira\nconspiração.\012Eu sei!",
  ["52:46d3"] = "This happened when\nI was young.\012The sky suddenly\nturned black. A\012giant flying POKé-\nMON was blocking\011out the sun.\012I wonder what that\nPOKéMON was? \012It was like a bird\nand a dragon.",
  ["52:4782"] = "Realmente existe\num #MON grande\011assim?\012Se existir, deve\nser poderoso.",
  ["52:48b8"] = "Vitórias e\nderrotas, conheço\011ambas.",
  ["52:48e9"] = "Oh, você é muito\nforte.",
  ["52:4903"] = "Eu gostei muito.\nGostaria de vê-lo\011de novo.",
  ["52:4938"] = "Eu sempre danço\ncom meus #MON.\012Claro, eu também\nos treino.",
  ["52:4974"] = "Oh, foi perto!\nEu quase venci.",
  ["52:4995"] = "Rhythm is impor-\ntant for both\012dancing and POKé-\nMON.",
  ["52:49c9"] = "O meu pregador não\né lindo?\012Oh, uma batalha\n#MON?",
  ["52:49f6"] = "Não restou mais\nnenhum #MON…",
  ["52:4a12"] = "Eu ponho uma flor\ndiferente no meu\011pregador todo\011mês.",
  ["52:4a4a"] = "Oh, você é um\ntreinador bonito.\011Gostaria de\011batalhar?",
  ["52:4a7f"] = "Você é mais forte\ndo que parece.",
  ["52:4a9e"] = "Eu treinei muito,\nentão achei que\011era uma boa\011treinadora.\012Parece que não.",
  ["52:4ae6"] = "Gosta da minha\ndança?\012Sou boa com\n#MON também.",
  ["52:4b14"] = "Ooh, você também é\nbom com #MON.",
  ["52:4b32"] = "Eu posso continuar\ndançando pois há\011pessoas que gostam\011do que faço.\012Meus #MON\ntambém mantêm meu\011espírito alto.",
  ["52:4b94"] = "Além de serem\nótimas dançarinas,\011as GAROTAS KIMONO\011também são boas\011com #MON.\012Eu sempre as\ndesafio, mas nem\011chego a arranhar…",
  ["52:4c1b"] = "Rapaz! Se você\npuder derrotar\011todas GAROTAS\011KIMONO, vou\011presenteá-lo.",
  ["52:4c5e"] = "O modo em que\nbatalhou, foi como\011assistir a uma\011dança.\012Foi algo bem raro\nde se ver!\012Quero que leve\nisso.\012Não se preocupe,\nleve-o!",
  ["52:4cdf"] = "É o SURFE.\012É um golpe que\ndeixa o #MON\011nadar através da\011água.",
  ["52:4d19"] = "Eu queria que\nmeus #MON\011fossem elegantes\011como as GAROTAS\011KIMONO!",
  ["52:4d4e"] = "RHYDON: Gugooh\ngugogooh!",
  ["52:4d68"] = "Esse homem está\nsempre com seu\011RHYDON.\012Dizem que ele quer\num #MON que\011possa SURFAR e\011dançar.\012Ele está tentando\nfazer um\011#MON de nado\011sincronizado?",
  ["52:4dee"] = "As GAROTAS KIMONO\nsão tão bonitas…\012Mas elas devem\npassar por\011um rigoroso\011treinamento.\012E devem aprender\na seguir costumes\011antes da exibição\011pública.\n \012Mas se você ama\nalguma coisa, tudo\011é possível.",
  ["52:4ebd"] = "É um lindo painel\ndecorado com\011flores.",
  ["52:4f8c"] = "My EEVEE evolved\ninto an ESPEON.\012But my friend's\nEEVEE turned into\011an UMBREON.\012I wonder why? We\nboth were raising\012our EEVEE in the\nsame way…",
  ["52:5019"] = "Se você usar o\nREVIVE, um #MON\011desmaiado vai\011acordar.",
  ["52:516b"] = "Good of you to\nhave come.\012Here in ECRUTEAK,\nPOKéMON have been\011revered.\012It's said that\nlegendary POKéMON\012will appear to the\ntruly powerful\011trainers.\012I believed that\ntale, so I have\012secretly trained\nhere all my life.\012As a result, I can\nnow see what\011others cannot.\012Just a bit more…\012With a little\nmore, I could see\012a future in which\nI meet the legen-\011dary POKéMON.\012You're going to\nhelp me reach that\011level!",
  ["52:52f4"] = "Não sou bom o\nbastante ainda…\012Tudo bem. Essa\nINSÍGNIA é sua.",
  ["52:532d"] = "{PLAYER} received\nFOGBADGE.",
  ["52:5343"] = "Por ter a INSÍGNIA\nDA NÉVOA, #MON\011até o NÍVEL 50 vão\011lhe obedecer.\012E mais, #MON\nque sabem o SURFE\011poderão usá-lo a\011qualquer hora.\012Eu quero que você\ntenha isso também.",
  ["52:53d6"] = "É a BOLA SOMBRIA.\nEla causa danos\011e pode reduzir a\011DEFESA 2.\012Use-a quando\nnecessitar.",
  ["52:542f"] = "Eu vejo…\012Sua jornada te\nlevou para lugares\011distantes.\012E você testemunhou\nmuito mais do que\011eu.\012Eu o invejo por\nisso…",
  ["52:54a7"] = "Eu gastei a\nprimavera com meu\011#MON.\012Depois o verão,\no outono e o\011inverno.\012A primavera veio\nde novo. Nós temos\011vivido juntos por\011um longo tempo.",
  ["52:5527"] = "Eu vou vencer!",
  ["52:554d"] = "De onde vieram\nos #MON?",
  ["52:5568"] = "Você pode causar\ndanos em nossos\011#MON?",
  ["52:5591"] = "Ah! Muito bem!",
  ["52:55a1"] = "Só usamos #MON\ndo tipo fantasma.\012Técnicas do tipo\nnormal não os\011machucam.",
  ["52:55e5"] = "Quem mais quiser\nvencer--vencerá!",
  ["52:55f3"] = "Eu, eu, eu perdi!",
  ["52:5602"] = "Quem mais quiser\nvencer--vencerá!",
  ["52:5628"] = "Confuso com nosso\nchão invisível?\012Derrote-me se\nquiser uma dica!",
  ["52:5669"] = "O-o quê?",
  ["52:5674"] = "Bom. Vou te contar\no segredo do chão\011invisível.\012O caminho é em\nfrente aos nossos\011olhos!",
  ["52:56d2"] = "Os treinadores\naqui têm motivos\011secretos.\012Se você vencer,\neles devem te\011contar segredos\011profundos de\011ECRUTEAK.",
  ["52:573c"] = "Uau, {PLAYER}.\nVocê foi ótimo!\012Eu estava agachado\nno canto, livre do\011puro terror!",
  ["52:58cc"] = "Ah. Você está em\numa aventura com\011seus #MON?\012Bem, o que é uma\naventura sem uma\011Caça ao Tesouro?\012Estou certo, ou\nestou certo?",
  ["52:5945"] = "Bom! Você entende\no verdadeiro\011espírito da\011aventura.\012Eu gosto disso!\nLeve isso com\011você.",
  ["52:599e"] = "Há muitos itens\nque não podem ser\011vistos.\012Use o ACHA ITENS\npara checar se há\011um item no chão\011perto de você.\012Ele não mostra o\nponto exato, logo\011você terá que\011procurar por você\011mesmo.\012Oh sim--eu soube\nque há itens na\011TORRE QUEIMADA da\011CIDADE ECRUTEAK.",
  ["52:5a95"] = "Oh… Cada um deve\nter seu gosto…",
  ["52:5ab6"] = "HISTÓRIA DE\nECRUTEAK.\012Quer ler?",
  ["52:5adc"] = "Em ECRUTEAK, havia\nduas torres.\012Cada torre era\no poleiro de\011poderosos #MON\011voadores.\012Mas uma das torres\nqueimou até o\011chão.\012Os dois #MON\nnão foram vistos\011desde então…\012Continuar lendo?",
  ["52:5b92"] = "ECRUTEAK era\ntambém o lar de\011três #MON que\011corriam ao redor\011da cidade.\012Era dito que foram\nnascidos da água,\011do relâmpago e do\011fogo.\012Mas não\npuderam conter\011seus poderes\011excessivos.\012Dizem que os três\ncorriam do modo\011que o vento passa\011pela grama.",
  ["53:40f3"] = "I am CLAIR. I'm\nthe world's best\011dragon master.\012I can hold my own\nagainst even the\012POKéMON LEAGUE's\nELITE FOUR.\012Do you still want\nto take me on?\012…Fine.\nLet's do it!\012As a trainer, I\nwill use my full\012power against any\nopponent!",
  ["53:41cf"] = "Eu perdi?\012Não acredito. Deve\nhaver algum erro…",
  ["53:4207"] = "I won't admit\nthis.\012I may have lost,\nbut you're still\012not ready for the\nPOKéMON LEAGUE.\012I know. You should\ntake the dragon\011user challenge.\012Behind this GYM is\na place called\011DRAGON'S DEN.\012Go and bring me\nthe DRAGON FANG\012from deep inside\nthe DEN.\012That is the test\nto be accepted as\012a true dragon\nuser.\012If you can do\nthat, I will ac-\011cept you as a\011worthy trainer.\012Until then, I\nwon't give you a\011BADGE.",
  ["53:4391"] = "CLAIR: What's\nthe matter?\012This errand won't\nbe hard for you,\012unless your vic-\ntory was a fluke.",
  ["53:43f0"] = "CLAIR: You did\nnot get that at\011DRAGON'S DEN.\012Trying to cheat\nlike that…\012I'm disappointed\nin you.",
  ["53:4451"] = "CLAIR: You have\nproven yourself to\011me.\012I want you to have\nthis TM.",
  ["53:44a7"] = "That contains\nDRAGONBREATH.\012No, it doesn't\nhave anything to\011do with my breath.\012If you don't want\nit, you don't have\011to take it.",
  ["53:4525"] = "So you've col-\nlected all the\011BADGES.\012Your destination\nis the POKéMON\012LEAGUE in INDIGO\nPLATEAU.\012Do you know how to\nget there?\012From here, go to\nNEW BARK TOWN.\012Then SURF east.\nThe route there is\011very tough.\012Don't you dare\nlose at the POKé-\011MON LEAGUE!\012If you do, I'll\nfeel even worse\012about having lost\nto you!",
  ["53:4651"] = "Sua primeira\nbatalha contra\011dragões?\012Vou lhe\nmostrar como\011são poderosos!",
  ["53:4696"] = "I'm disappointed.",
  ["53:46a8"] = "You've met LANCE,\nthe dragon master?\012That just can't be\ntrue.",
  ["53:46e5"] = "Minha chance de\nperder? Nem um\011porcento!",
  ["53:4711"] = "É estranho.",
  ["53:471d"] = "Conheço meus\ndefeitos agora.\012Obrigado por me\nmostrá-los!",
  ["53:4753"] = "Dragões são\n#MON sagrados.\012Eles são cheio de\nvida e energia.\012Se não for sério,\nnão será capaz de\011derrotá-los.",
  ["53:47c0"] = "Vamos em frente!",
  ["53:47cc"] = "Dragões são\nfracos contra\011golpes tipo\011dragão.",
  ["53:47fa"] = "Ei! CAMPEÃO em\nprogresso!\012Foi uma longa\njornada, mas está\011quase acabando!\011Conte comigo!\012CLAIR usa\nos místicos e\011sagrados #MON\011tipo dragão.\012Você não pode\nferi-los com\011facilidade.\012Mas você sabe,\ndizem que eles\011são fracos contra\011golpes tipo gelo.",
  ["53:48e8"] = "Você foi ótimo\nao vencer CLAIR!\012Tudo que falta\né o desafio da\011LIGA #MON.\012Você está no\ncaminho de se\011tornar o CAMPEÃO\011#MON!",
  ["53:4a3f"] = "It's not as if we\nall use dragon-\011type POKéMON.\012My policy is to\nuse POKéMON that\012are stronger than\ndragon POKéMON.",
  ["53:4aa9"] = "You are special…",
  ["53:4abb"] = "But just watch!\nMy POKéMON will\012become even more\npowerful.\012We'll be tougher\nas a trainer and\011POKéMON team.",
  ["53:4b20"] = "We go through rig-\norous training un-\011der CLAIR. I can't\011afford to lose.",
  ["53:4b69"] = "Arrrgh! I'm so\ndisgusted!",
  ["53:4b83"] = "Whew…\012I'll have to re-\nthink my training…",
  ["53:4bad"] = "The boulder fell\nthrough!",
  ["53:4c64"] = "CLAIR and LANCE\ntrained here to\012hone their skills\nas trainers.",
  ["53:4ca4"] = "DRATINI: Draa!",
  ["53:4d20"] = "Você não pode\ncomprar o REVIVE\011TOTAL, que cura\011todo o HP do\011#MON desmaiado.\n\012Cuidado--Isso não\nrestaura o PP,\011PONTOS DE PODER,\011usado em golpes.",
  ["53:4d9f"] = "O REPELENTE 03\nafasta #MON\011fracos de você.\012É o REPELENTE\nde maior duração\011que existe.",
  ["53:4e3b"] = "Nas profundezas do\nPLANALTO ÍNDIGO\011está a LIGA\011#MON.\012Eu soube que\nos melhores\011treinadores de\011todos os lugares\011vão lá.",
  ["53:4eb3"] = "There was this\nmove I just had\012to teach my POKé-\nMON.\012So I got the MOVE\nDELETER to make it\011forget an HM move.",
  ["53:4fa7"] = "BLAINE, DO GINÁSIO\nDE CINNABAR parece\011viver sozinho na\011caverna das ILHAS\011CINNABAR…",
  ["53:4ff1"] = "Você é forte\ndemais!",
  ["53:507c"] = "O vulcão de\nCINNABAR entrou em\011erupção e lançou\011pedras que\011indeterminadamente\011fecharam a ROTA\01119.\012Será que as\npessoas de\011CINNABAR estão\011bem?",
  ["53:50fc"] = "Ninguém de\nCINNABAR foi\011machucado pela\011erupção.\012Que ótimo!",
  ["53:51ba"] = "BLAINE: Waaah!\012My GYM in CINNABAR\nburned down.\012My fire-breathing\nPOKéMON and I are\012homeless because\nof the volcano.\012Waaah!\012But I'm back in\nbusiness as a GYM\012LEADER here in\nthis cave.\012If you can beat\nme, I'll give you\011a BADGE.\012Ha! You'd better\nhave BURN HEAL!",
  ["53:52b8"] = "BLAINE: Excelente.\nVocê me queimou…\012Você mereceu\na INSÍGNIA DO\011VULCÃO.",
  ["53:52f5"] = "{PLAYER} received\nVOLCANOBADGE.",
  ["53:530f"] = "BLAINE: Eu perdi\ndesta vez, mas\011eu vou vencer na\011próxima.\012Quando eu\nreconstruir meu\011GINÁSIO DE\011CINNABAR, teremos\011que ter outra\011batalha.",
  ["53:538e"] = "BLAINE: Meus\n#MON de fogo\011ficarão ainda mais\011fortes. Aguarde!",
  ["53:53cb"] = "Yo!\012… Huh? It's over\nalready?\012Sorry, dude!\012CINNABAR GYM was\ngone, so I didn't\012know where to find\nyou.\012But, hey, you're\nplenty strong even\012without my advice.\nI knew you'd win!",
  ["53:5477"] = "Um GINÁSIO #MON\npode ser em\011qualquer lugar\011em que haja um\011LÍDER DE GINÁSIO.\012Não precisa ser\nem um prédio.",
  ["53:5521"] = "…Você veio de\nlonge…\012Aqui eu meditei.\nDentro de mim, um\011novo poder foi\011despertado.\012Deixe-me dividir\nmeu poder com o\011seu #MON. Leve\011isso, garoto.",
  ["53:55b4"] = "Do you see it? It\nis HIDDEN POWER!\012It draws out the\npower of POKéMON\011for attacking.\012Remember this: its\ntype and power de-\011pend on the POKé-\011MON using it.",
  ["53:5649"] = "Eu estou\nmeditando…",
  ["53:5704"] = "O LAGO DA RAIVA é\nna verdade uma\011cratera feita\011por rituais de\011GYARADOS. Ela se\011encheu de água da\011chuva e o LAGO\011foi formado.\012Essa história é\npassada desde o\011tataravô do meu\011avô.\012Ali era um lugar\nque se podia\011capturar MAGIKARPS\011facilmente, mas…\012Eu não entendo\no que está\011acontecendo ao\011lago.",
  ["53:5823"] = "O LAGO está\nestranho desde\011quando aqueles\011homens de preto\011chegaram.",
  ["53:5866"] = "O LAGO DA RAIVA\nvoltou ao normal.\011As MAGIKARPS\011retornaram.\012Eu ainda posso\nrealizar meu sonho\011de ver a maior\011MAGIKARP do mundo.\012Você tem uma VARA?\nAjude-me se quiser.",
  ["53:5914"] = "Ah, você tem uma\nMAGIKARP!\012Deixe-me ver o\ntamanho dela.",
  ["53:594d"] = "Uau! Essa é\nincrível!\012Eu tiro meu chapéu\npara você!\012Leve essa\nlembrança!",
  ["53:5999"] = "O recorde que é\nimportante.\012Considere-o como\num bônus!",
  ["53:59d7"] = "Uau! essa é\nincrível!\012…Não queria dizer\nisso, mas eu já\011outras que são\011maiores.",
  ["53:5a32"] = "O quê? Isso não é\numa MAGIKARP!",
  ["53:5a4f"] = "Oh… Então você\nnão capturou uma\011muito boa para me\011mostrar?\012Talvez na\npróxima.",
  ["53:5af5"] = "Só pessos que iam\npara o LAGO DA\011RAIVA passaram\011por aqui\011atualmente.",
  ["53:5b3b"] = "Atualmente ninguém\nvai ao LAGO DA\011RAIVA.",
  ["53:5ca8"] = "Hold it there,\nmister!\012The toll is ¥1000\nto go through.",
  ["53:5ce1"] = "Thank you, sir!",
  ["53:5cf2"] = "Então pague o\nque tiver.",
  ["53:5d13"] = "He-he-he. Estamos\nficando ricos.\012Todos querem ver\no que está\011acontecendo no\011LAGO DA RAIVA.",
  ["53:5d6d"] = "Eu fui expulso\ndo meu cargo por\011esses caras de\011preto.\012Eles esqueceram\nisso.\012Isso me deixa\ninconfortável.\011Poderia levá-lo?",
  ["53:5dff"] = "Use esse portão\npara não andar na\011grama.",
  ["54:4005"] = "Are you collecting\nKANTO GYM BADGES?",
  ["54:405a"] = "I heard that some\nshady character is\011skulking about.\012I won't stand for\nit if he turns out\011to be a thief.",
  ["54:40c3"] = "Fomos rendidos\npor bandidos no\011passado.",
  ["54:40e7"] = "DIGLETT: Dug dug.",
  ["54:414d"] = "My husband lives\nhappily with POKé-\011MON he got through\011trades.",
  ["54:418a"] = "Ah… Sou tão feliz…",
  ["54:419c"] = "KANGASKHAN: Garu\ngaruu.",
  ["54:41b5"] = "ZUBAT: Zuba zubaa.",
  ["54:4218"] = "ROUTE 9 stretches\nto the east. The\012POWER PLANT is at\nthe end.",
  ["54:4257"] = "O TREM ÍMÃ viaja\na 544 km/h. Ele\011percorre o caminho\011entre KANTO e\011JOHTO quase sem\011gastar tempo.\012Ele realmente\ntorna JOHTO\011acessível.",
  ["54:4453"] = "Opa! Perdoe-me!\nNão se feriu,\011certo?\012Estou muito\nocupado, sem tempo\011para conversar\011com você.\012Não é bom para mim\nser visto por\011alguém.",
  ["54:44cc"] = "Oh não! Já me\nviu! Fiz um grande\011erro!",
  ["54:44fd"] = "Ei, você! Esqueça\nque me viu,\011certo?\012Não viu, ouviu\nnem sabe de nada,\011certo?\012Tchau garoto!\nNada! Adeeeus!",
  ["54:4568"] = "Perdão, sairei por\num tempo.\012MISTY, A LÍDER\nDO GINÁSIO.",
  ["54:459a"] = "Como MISTY saiu,\nsairemos também.\012TREINADORES DO\nGINÁSIO.",
  ["54:45cc"] = "MISTY: Eu o\nesperava, peste!\012Você pode ter\nvárias INSÍGNIAS\011DE GINÁSIO DE\011JOHTO, mas é\011melhor me levar a\011sério.\012Meus #MON\ntipo água são\011fortes!",
  ["54:4664"] = "MISTY: Você\nrealmente é bom…\012Admitirei que é\nhabilidoso…\012Aqui está. É a\nINSÍGNIA DA\011CASCATA.",
  ["54:46c0"] = "{PLAYER} received\nCASCADEBADGE.",
  ["54:46da"] = "MISTY: Há muitos\ntreinadores fortes\011em JOHTO? Digo,\011como você.\012Um dia viajarei\npara lá, então\011poderei batalhar\011com treinadores\011habilidosos.",
  ["54:4762"] = "Perdão por ter\nsaído. Vamos\011começar isso!",
  ["54:4790"] = "Desisto! Você é o\nvencedor!",
  ["54:47ae"] = "Vou nadar quieta-\nmente.",
  ["54:47c8"] = "Não deixe meu\nnado elegante\011irritá-lo.",
  ["54:47f7"] = "Ooh, venceu-me\ncalmamente…",
  ["54:4818"] = "Não fique tão\nalegre por me\011vencer.\012MISTY o derrotará\nse você não for\011sério.",
  ["54:486a"] = "Glub…\012Eu primeiro! Venha\nme pegar!",
  ["54:488c"] = "This can't be…",
  ["54:489b"] = "MISTY melhorou\nmuito nesses\011últimos anos.\012Não abaixe sua\nguarda, caso\011contrário, será\011esmagado!",
  ["54:48ff"] = "Ei! CAMPEÃO em\nprogresso!\012Como MISTY saiu,\ntambém saí para\011me divertir.\011He-he-he.",
  ["54:4952"] = "Hoo, você me\nmostrou como é\011forte.\012Como sempre,\nessa foi outra\011batalha magnífica!",
  ["54:4a25"] = "Você encontrará\nvários treinadores\011a caminho\011da PENÍNSULA\011CERULEANA.\012Eles querem ver\ncomo se saem\011contra outros\011treinadores.",
  ["54:4a9e"] = "MISTY é a única\npessoa na cidade\011que derrota\011os treinadores\011da PENÍNSULA\011CERULEANA.",
  ["54:4b49"] = "Um CENTRO #MON\nperto da caverna?\012Isso deve ser\nútil.",
  ["54:4b7e"] = "The POWER PLANT's\nMANAGER is looking\012for a strong POKé-\nMON trainer.\012He needs help\ngetting back\012something that\nwas stolen.",
  ["54:4bf6"] = "Soube que a\nEQUIPE ROCKET\011voltou em JOHTO\011mas foi destruída\011de novo.\012Eu não sabia nada\ndessas coisas.",
  ["54:4c64"] = "Quando você sai,\npode ver o telhado\011de uma grande\011construção.\012É a USINA ELÉTRICA.",
  ["54:4e31"] = "A thief broke into\nthe POWER PLANT…\012What is the world\ncoming to?",
  ["54:4e73"] = "Acabei de falar\ncom CERULEANA.\012Parece que um cara\nsuspeito esteve\011andando por lá.",
  ["54:4ed0"] = "Poderia pedir\npela sua\011cooperação?",
  ["54:4ef3"] = "Nós teremos que\nmelhorar nossa\011segurança.",
  ["54:4f20"] = "Alguém sumiu com\numa parte que é\011essencial para o\011gerador.\012Sem ela, o novo\ngerador é inútil!",
  ["54:4f89"] = "O gerador está bom\ne funcionando.\012Está fazendo\nbastante\011eletricidade.",
  ["54:4fca"] = "Essa USINA ELÉTRICA foi\011abandonada no\011passado.\012Nós a recolocamos\nde pé para\011fornecer energia\011ao TREM ÍMÃ.",
  ["54:5040"] = "O gerador está\nfuncionando de\011novo!",
  ["54:505f"] = "O GERENTE DA\nUSINA ELÉTRICA\011está logo ali.\012Mas como alguém\nquebrou o gerador,\011ele tem estado\011triste e furioso…",
  ["54:50d0"] = "Como o gerador\nfoi consertado, o\011GERENTE tem estado\011bem alegre.",
  ["54:5113"] = "O TREM ÍMÃ\nconsome muita\011eletricidade.\012Não pode se mover\nse o novo gerador\011não estiver\011funcionando.",
  ["54:5176"] = "Certo! Finalmente\npodemos fazer o\011TREM ÍMÃ funcionar\011de novo.",
  ["54:51b5"] = "GERENTE: Eu, eu,\neu estou pronto\011para matar alguém.\012Quem ousaria\narruinar meu\011gerador?\012Gastei muito tempo\nnele!\012Quando eu pegar o\nresponsável, ele\011provará meu SUPER\011CANHÃO!",
  ["54:5259"] = "GERENTE: Não o\nperdoarei!\012O culpado pode\nchorar e se\011lamentar, mas\011ainda o\011martelarei!\n\012Gahahahah!",
  ["54:52bf"] = "GERENTE: Ah!\nIsso!\012É a PEÇA perdida\ndo meu amado\011gerador!\012Você a achou?",
  ["54:5315"] = "Wahaha! Obrigado!\012Ei! Leve esse TM\ncomo recompensa!",
  ["54:5345"] = "GERENTE: TM07 é\no meu SUPER\011CANHÃO.\012É uma técnica\npoderosa!\012Não é o que\neu chamaria de\011precisão, mas ele\011causa bons danos!",
  ["54:53c6"] = "GERENTE: Meu\namado gerador!\012Continue bombeando\na eletricidade!",
  ["54:5612"] = "Hm? Você conhece\nBILL? Ele é meu\011neto.\012Ele está em JOHTO.\nFaz algo com\011COMPUTADORES,\011então fico em\011casa.",
  ["54:5676"] = "Se você tiver\naquele #MON,\011posso vê-lo?",
  ["54:56a4"] = "Vai me mostrar?\nQue legal da sua\011parte!",
  ["54:56c8"] = "Você não o tem?\nIsso é uma\011pena…",
  ["54:56ea"] = "Ah, so that is\n{STRBUF}?\012Isn't it cute!\nThat's so kind of\011you.",
  ["54:5725"] = "Obrigado!\012Isso representa\nminha gratidão.",
  ["54:5752"] = "Venha me\nvisitar de novo.",
  ["54:576e"] = "Obrigado por me\nmostrar tantos\011#MON lindos.\012Realmente gostei.\nEstou feliz por\011ter vivido tanto.",
  ["54:57d5"] = "Hm?\012Esse não é o\n#MON que eu\011tinha mencionado.",
  ["54:5804"] = "Meu neto BILL me\ncontou sobre um\011#MON que tem\011uma língua\011grande.",
  ["54:5843"] = "Ah, meu neto\nmencionou um\011#MON verde e\011redondo que tem\011folhas crescendo\011em sua cabeça.",
  ["54:5897"] = "Você sabe de um\n#MON do mar\011que tem uma esfera\011vermelha em seu\011corpo?\012Você sabe, aquele\nem forma de\011estrela?\012Soube que ele\naparece à noite.\012Eu certamente\ngostaria de vê-lo.",
  ["54:5942"] = "BILL me contou\nsobre um #MON\011que é muito leal\011ao seu treinador.\012Dizem que tem bom\nRUGIDO.",
  ["54:599b"] = "Soube de um lindo\n#MON que tem\011seis caudas.\012Eu adoraria\nabraçar um lindo\011#MON como esse.",
  ["54:59f5"] = "Você sabe daquele\n#MON bastante\011popular?\012O #MON que tem\num corpo amarelo\011e bochechas\011vermelhas.\012Adoraria ver\ncomo ele é antes\011de sua evolução.",
  ["55:4013"] = "Seus #MON\nsabem golpes HM?\012Esses golpes podem\nser usados mesmo\011se seus #MON\011desmaiarem.",
  ["55:4067"] = "O PC DO BILL pode\nguardar até 20\011#MON por BOX.",
  ["55:4092"] = "Do you know about\nAPRICORNS?\012Crack one open,\nhollow it out and\012fit it with a\nspecial device.\012Then you can catch\nPOKéMON with it.\012Before POKé BALLS\nwere invented,\012everyone used\nAPRICORNS.",
  ["55:41ed"] = "Todos SLOWPOKES\ndesapareceram da\011cidade.\012O protetor da\nfloresta deve\011estar nervoso com\011nós…\012Isso deve ser um\nsinal ruim.\012Devemos ficar em\nalerta.",
  ["55:4276"] = "Os SLOWPOKES\nvoltaram.\012Mas meu aprendiz\nnão voltou da\011FLORESTA ILEX.\012Onde será que\neste preguiçoso\011está?",
  ["55:42ec"] = "Você sozinho\nperseguiu a EQUIPE\011ROCKET e foi à\011FLORESTA ILEX?\012Que técnicas!\nGostei disso!\011Venha treinar\011conosco.",
  ["55:4359"] = "Para onde foram\ntodos SLOWPOKES?\011Será que estão\011brincando por aí?",
  ["55:439e"] = "Perdão--esqueci\nde agradecê-lo.\012Esse é o CARVÃO\nque eu fiz.\012#MON do tipo\nfogo ficariam\011felizes ao segurar\011isso.",
  ["55:440c"] = "Os SLOWPOKES\nvoltaram, e você\011ainda achou um\011FARFETCH'D.\012Você é o mais\nlegal!",
  ["55:445e"] = "FARFETCH'D: FARF!",
  ["55:44c6"] = "There's no GREAT\nBALL here. POKé\012BALLS will have\nto do.\012I wish KURT would\nmake me some of\011his custom BALLS.",
  ["55:452f"] = "A GREAT BALL is\nbetter for catch-\011ing POKéMON than a\011POKé BALL.\012But KURT's might\nbe better some-\011times.",
  ["55:47ee"] = "Hm? Quem é você?\012{PLAYER}, eh?\nQuer que eu faça\011umas BOLAS?\012Perdão, mas terá\nque esperar.\012Você conhece a\nEQUIPE ROCKET?\012Ah, fique calmo.\nEu vou te dizer. \n\012A EQUIPE ROCKET é\ngangue malvada que\012usa POKéMONS para\nseus trabalhos\011sujos.\012Dizem que eles\ntiveram que falir\011há três anos.\012Mesmo assim,\nestão no POÇO,\n \012cortando CAUDAS de\nSLOWPOKE para a\011venda.\012Então vou dar-lhes\numa lição sobre a\011dor!\012Aguente, SLOWPOKE!\nO velho KURT está\011indo!",
  ["55:4990"] = "KURT: Oi, {PLAYER}!\012Você agiu como\num herói verdeiro\011no POÇO.\n \012Admiro seu estilo!\012Estaria honrado em\nfazer BOLAS para\012um treinador como\nvocê.\012É tudo que tenho\nagora, mas leve-a.",
  ["55:4a44"] = "KURT: Faço BOLAS\ncom FRUTOS.\012Colete-os das ár-\nvores e traga-os\011a mim.\012Eu farei BOLAS\ncom eles.",
  ["55:4ab1"] = "KURT: Você tem um\nFRUTO para mim?\012Legal! Ele vai\nvirar uma BOLA.",
  ["55:4af4"] = "KURT: Levarei um\ndia para fazer uma\012BOLA. Volte mais\ntarde.",
  ["55:4b37"] = "KURT: Oh… Que\ndesapontamento.",
  ["55:4b53"] = "KURT: Estou traba-\nlhando!\012Não me atrapalhe!",
  ["55:4b76"] = "KURT: Ah, {PLAYER}!\nAcabei de fazer\011sua BOLA. Aqui!",
  ["55:4ba5"] = "KURT: Foi muito\nbem feita.\012Tente capturar\nPOKÉMONS com ela.",
  ["55:4bde"] = "Os SLOWPOKE su-\nmiram… Eles foram\012levados embora por\ngente ruim?",
  ["55:4c1a"] = "O vovô saiu…\nEstou tão só…",
  ["55:4c38"] = "O SLOWPOKE que meu\npai me deu voltou!\012Sua cauda está\ncrescendo também!",
  ["55:4c7e"] = "Dad works at SILPH\nwhere he studies\011POKé BALLS.\012I have to stay\nhome with Grandpa\011and SLOWPOKE.",
  ["55:4cdb"] = "SLOWPOKE: …\nYawn?",
  ["55:4cee"] = "…O jovem PROFESSOR\nCARVALHO?",
  ["55:4d03"] = "É uma estátua do\nprotetor da flo-\011resta.",
  ["55:4e83"] = "Sou BUGSY!\012Nunca perco quando\nuso #MON\011insetos.\012Minha pesquisa me\ntornará uma\011autoridade em\011#MON insetos!\012Deixe-me\ndemonstrar o que\011eu aprendi com os\011meus estudos.",
  ["55:4f26"] = "Então como foi?\012Acho que nem\npreciso de\011perguntar.\012Você falhou?\012………………\012…O quê? Você\npassou?",
  ["55:4f8c"] = "{PLAYER} foi\npresenteado com\011uma INSÍGNIA DA\011COLMÉIA DO\011GINÁSIO DA CIDADE\011AZALEA.",
  ["55:4fa3"] = "Do you know the\nbenefits of HIVE-\011BADGE?\012If you have it,\nPOKéMON up to L30\011will obey you.\012POKéMON that know\nCUT will be able\012to use it outside\nof battle too.\012Here, I also want\nyou to have this.",
  ["55:5060"] = "TM49 contém\nCORTE FÚRIA. \012Se você não errar,\nesse ataque fica\011cada vez mais\011forte.\012Quanto maior for\na batalha, melhor \011o ataque ficará. \012Isso não é ótimo?\nFui eu quem\011descobriu isso!",
  ["55:50fe"] = "#MON insetos\nsão complexos.\012Tem muitos\nmistérios a\011explorar.\012Estude seu\nfavorito por\011completo.",
  ["55:515e"] = "#MON insetos\nevoluem jovens.\012Daí eles ficam\nfortes mais\011rápido.",
  ["55:519d"] = "Apenas evoluir\nnão basta!",
  ["55:51b9"] = "#MON ficam\nmais fortes quando\011eles evoluem!",
  ["55:51e7"] = "#MON insetos\nsão legais e\011fortes! Vou lhe\011provar!",
  ["55:521a"] = "Provou como você\né forte…",
  ["55:5239"] = "Eles são tão\nlegais, mas não\011sei porque as\011garotas detestam\011#MON insetos…",
  ["55:527e"] = "Você salvou todos\nSLOWPOKES? Uau,\011você é poderoso!\012Mas meu #MON\ncrescido é bem\011forte também!",
  ["55:52da"] = "Urrgggh!",
  ["55:52e4"] = "Acho que devo\nensiná-los golpes\011melhores…",
  ["55:530f"] = "AMY: Oi! Está\ndesafiando a\011LÍDER? Nem pensar!",
  ["55:5341"] = "AMY & MAY: Oh,\ndupla bondade!",
  ["55:5362"] = "AMY: Você é mesmo\nforte!",
  ["55:537d"] = "MAY: Quer ver a\nLÍDER? Veja nós\011primeiro!",
  ["55:53ae"] = "AMY & MAY: Oh,\ndupla bondade!",
  ["55:53cf"] = "MAY: Our bug POKé-\nMON lost! Oh, what\011a shame.",
  ["55:53fc"] = "Ei, desafiante!\012BUGSY é jovem, mas\nseu conhecimento\011de #MON\011insetos é\011incrível!\012Seria mais difícil\nsem meu aviso.\012Vamos ver…\n#MON insetos\011não gostam de\011fogo.\012Golpes de\n#MON AVES são\011super efetivos.",
  ["55:54bf"] = "Parabéns! Isso\nfoi um ótimo\011choque de jovens\011treinadores\011talentosos.\012O futuro #MON\nserá brilhante com\011gente como vocês!",
  ["56:400f"] = "Quando captura um\n#MON, ele pode\011estar fraco.\012Mas ele ficará\nforte um dia.\n \012É importante\ntratar o #MON\011com amor.",
  ["56:4090"] = "Os #MON podem\nsegurar itens como\011POÇÃO e ANTÍDOTO.\012Mas eles parecem\nnão saber como\011usar itens feitos\011pelos homens.",
  ["56:41e0"] = "Sou FALKNER, o\nLÍDER desse\011GINÁSIO! \012Dizem que pode\njuntar as asas do\012#MON voador com\no Choque do\011#MON elétrico…\012Não permito \ninsultos aos\011#MON pássaros!\012Vou lhe mostrar o \npoder real dos\011ótimos #MON\011pássaros!",
  ["56:42b7"] = "…Não! Meu pai\ncuidava de\011#MON pássaros.\012Tudo bem. Leve\nisso.\012É uma oficial\nINSÍGNIA DA BRISA\011da LIGA #MON.",
  ["56:431c"] = "{PLAYER} received\nZEPHYRBADGE.",
  ["56:4335"] = "A INSÍGNIA DA\nBRISA melhora os\011poderes dos\011#MON.\012Também permite o\n#MON usar\011LUZES, se tiver, a\011qualquer hora.\012Leve isso também.",
  ["56:43b5"] = "Usando um TM, o\n#MON aprenderá\011um golpe num\011instante.\012Pense antes de\nagir--só pode\011usar o TM uma\011vez.\012O TM31 tem o\nTAPA DE LAMA.\012Ele reduz a\nprecisão do\012inimigo enquanto\ncausa danos. \012Em outras\npalavras, é\011defensivo quanto\011ofensivo.",
  ["56:44a2"] = "Tem outros\nGINÁSIOS nas\011cidades adiante. \012Você deve testar\nsuas técnicas\011nesses GINÁSIOS.\012Vou treinar duro\npara me tornar\011o melhor mestre\011de pássaros!",
  ["56:453a"] = "O segredo é\ntécnica!\012Esses aqui\nestão treinando\011dia e noite para\011serem mestres\011também.\012Vamos lá!",
  ["56:459c"] = "Gaaah!",
  ["56:45a4"] = "FALKNER é muito\nhabilidoso! \012Não comemore só\nporque você me\011derrotou!",
  ["56:45ec"] = "Vamos ver se você\né bom para\011encarar o\011FALKNER!",
  ["56:4620"] = "Não pode ser real!",
  ["56:4634"] = "Isso é horrível,\num treinador\011novato me vencer…",
  ["56:4666"] = "Ei! Não sou\ntreinador mas\011posso ajudá-lo!\012Acredite em mim!\nSe acreditar, um\011sonhado\011campeonato\011será real. \012Você acredita?\nEntão escute.\012#MON do tipo\ngrama são fracos\011contra o tipo\011voador.\012Pense nisso.",
  ["56:4735"] = "Boa batalha!\nContinue assim e\011você vai ser um\011CAMPEÃO em pouco\011tempo!",
  ["56:48a8"] = "EARL, I am!\012Wonderful are\nPOKéMON, yes!\012Teach you I will\nto be a better\011trainer!\012What you want to\nknow? Want to be\011a winner is you?",
  ["56:492a"] = "Bom! Eu vou\nensiná-lo!\012Na batalha, o\n#MON topo de\011lista será o\011primeiro!\012Mude a ordem na\nlista, facilita a\011batalha, talvez!\012Quer ouvir mais\ncoisas?",
  ["56:49be"] = "Então, quer saber\ncomo criar bem\011os #MON?",
  ["56:49e8"] = "Ótimo! Vou\nensiná-lo!\012Mesmo batalhando\npouco, o #MON\011ganhará um pouco\011de PONTOS DE\011EXPERIÊNCIA.\012Coloque o #MON\nfraco no topo de\011lista.\012Troque-o rápido\nna batalha!\012Assim, #MON\nfracos ficam\011fortes!",
  ["56:4a9e"] = "Oh! Você é um aluno\nesperto! Não tenho\011mais nada a te\011ensinar.\012Você deve ser\nbom com os\011#MON!",
  ["56:4aed"] = "Estou atento\nà leitura do\011professor.\012É melhor eu\ncopiar o que está \011no quadro também.",
  ["56:4b47"] = "Eu troquei meu\nmelhor #MON com\011o rapaz ao lado.",
  ["56:4b74"] = "Hã? O #MON que\nacabei de receber\011está segurando\011algo!",
  ["56:4ba6"] = "Um #MON\nsegurando um GRÃO\011se curará sozinho\011na batalha.\012Vários outros\nitens podem ser\011segurados pelo\011#MON…\012É bem difícil\nentender essa\011matéria…",
  ["56:4c1f"] = "O quadro mostra as\nmudanças de estado\011dos #MON na\011batalha.",
  ["56:4c6b"] = "Se envenenado, um\n#MON perde\011periodicamente HP.\012O veneno age após\nas batalhas, e o\011HP é perdido a\011medida que você\011anda.\012Para curá-lo,\nuse um ANTÍDOTO.",
  ["56:4ced"] = "A paralisia reduz\na velocidade e\011pode impedir o\011movimento.\012Continua após a\nbatalha, então use\011DESPARALISIA para\011curar.",
  ["56:4d4f"] = "Se dormir, seu\n#MON não pode\011se mover.\012Um #MON\ndorminhoco não\011acorda após\011batalhar.\012Acorde-o com um\nACORDADOR.",
  ["56:4dc2"] = "O fogo tira HP\nperiodicamente.\012Também reduz o\npoder de ataque.\012O fogo age após\na batalha.\012Use um CURA FOGO\ncomo cura.",
  ["56:4e38"] = "Se seu #MON\nestá congelado,\011ele não pode\011fazer nada.\012Continua congelado\napós a batalha. \012Cure-o com o CURA\nGELO.",
  ["56:4ea3"] = "It's this kid's\nnotebook…\012Catch POKéMON\nusing POKé BALLS.\012Up to six can be\nin your party.\012Keep reading?",
  ["56:4f04"] = "Before throwing a\nPOKé BALL, weaken\011the target first.\012A poisoned or\nburned POKéMON is\011easier to catch.\012Keep reading?",
  ["56:4f74"] = "Muitos golpes\npodem causar\011confusão.\012A confusão pode\nfazer o #MON se\011atacar.\012Sair da batalha\nacaba com a\011confusão.\012Continuar lendo?",
  ["56:4ff4"] = "Quem pega e usa\nos #MON\011nas batalhas\011são treinadores\011#MON.\012Eles devem visitar\nos GINÁSIOS\011#MON e vencer\011outros treinado-\011res.\012A próxima página\nestá… Branca!\012Garoto: He-he-he…\012Eu não escrevi\nmais nada…",
  ["56:5167"] = "She uses the names\nof her favorite\011things to eat.\012For the nicknames\nshe gives to her\011POKéMON, I mean.",
  ["56:51cb"] = "Eu chamo meu\nPIDGEY de MORANGO!",
  ["56:51e9"] = "MORANGO: Pijji!",
  ["56:52c2"] = "{PLAYER}, há quanto\ntempo.\012O PROFESSOR ELM\nme pediu para\011achá-lo.\012Ele tem outro\nfavor a pedir.\012Você levaria o OVO\n#MON?",
  ["56:5332"] = "Nós descobrimos\nque um #MON não\011nascerá até\011crescer no OVO.\012Deve estar junto\nde outros\011#MON ativos\011para nascer.\012{PLAYER}, você é a\núnica pessoa\011em que podemos\011confiar.\012Ligue para o\nPROFESSOR ELM\011quando o OVO\011chocar!",
  ["56:5400"] = "Oh, não. Você não\npode carregar mais\011#MON contigo.\012Esperarei aqui\nenquanto você\011libera espaço para\011o OVO.",
  ["56:545f"] = "M-mas… O PROFESSOR\nELM te pediu…",
  ["56:547f"] = "{PLAYER}, vai levar\no OVO?",
  ["56:549a"] = "Um rapaz chamado\nBILL fez o\011SISTEMA DE\011GUARDAR #MON\011no COMPUTADOR.",
  ["56:54cd"] = "Foi há três anos.\n \012A EQUIPE ROCKET\nmaltratava os\011#MON.\012Mas a justiça\nvenceu--um jovem\011garoto acabou com\011eles.",
  ["56:5549"] = "Os #MON são\nespertos.\012Eles não obedece-\nrão a um treinador\011sem respeito.\012Sem as INSÍGNIAS\nDE GINÁSIO certas,\011eles farão o que\011bem entenderem.",
  ["56:5628"] = "Um #MON pego\nem trocas cresce\011rápido.\012Mas se não tiver\nas INSÍGNIAS\011DE GINÁSIO\011certas, eles o\011desobedecerão.",
  ["56:56c7"] = "RUÍNAS ALFA\012Um lugar onde\nturistas podem\011tocar.\012Tente mover os\npainéis de pedra!",
  ["56:5712"] = "Você está\nestudando as\011RUÍNAS?\012Eu vi cientistas\nestudando-as.",
  ["56:574e"] = "Há desenhos nos\npainéis de pedra.\012Eu tentei movê-\nlos. O que será\011que eles são?",
  ["56:5814"] = "This is a great\nfishing spot.\012You saw people\nfishing? How\011about you?\012Would you like one\nof my RODS?",
  ["56:5879"] = "Eh, isso é bom.\012Agora você é um\npescador também!",
  ["56:58ac"] = "Pescar é ótimo!\012Se tiver água,\nseja mar ou\011oceano, tente\011pescar com a sua\011VARA.",
  ["56:58fd"] = "Oh. Mas que\ndesapontamento…",
  ["56:591e"] = "Yo, youngster. How\nare they biting?",
  ["56:5943"] = "O que devo fazer\nmeu #MON\011segurar?\012Talvez algo que\nfortaleça seus\011ATAQUES…",
  ["56:5a70"] = "Excuse me, guy!\nCan you do a guy\011a favor?\012Can you take this\nPOKéMON with MAIL\011to my friend?\012He's on ROUTE 31.",
  ["56:5adb"] = "You will? Perfect!\nThanks, guy!\012My pal's a chubby\nguy who snoozes\011all the time.\012You'll recognize\nhim right away!",
  ["56:5b4b"] = "{PLAYER} recebeu um\n#MON com CARTA.",
  ["56:5b69"] = "Você pode lê-la,\nmas não a perca!\011ROTA 31!\012Oh, sim. Havia uma\nestranha árvore\011bloqueando a\011estrada.\012Será que foi\nextirpada?",
  ["56:5be9"] = "Você não pode\ncarregar outro\011#MON…",
  ["56:5c07"] = "Oh… Não importa,\nentão…",
  ["56:5c1e"] = "Thanks, guy! You\nmade the delivery\011for me!\012Here's something\nfor your trouble!",
  ["56:5c6c"] = "Meu amigo estava\ndormindo, certo?\012Bem, o posso\ndizer?",
  ["56:5c9d"] = "Uma estranha\nárvore está\011bloqueado a\011estrada.\012Ela rebola se você\nfalar com ela.\012Soube que ela fica\nferoz quando\011alguém a rega com\011o POTE SQUIRT.",
  ["56:5d2d"] = "Eu gosto da Canção\n#MON que eles\011tocam no rádio.",
  ["56:5ef2"] = "Today's {STRBUF}.\nThat means the\012Bug-Catching Con-\ntest is on today.\012The rules are sim-\nple.\012Using one of your\nPOKéMON, catch a\012bug POKéMON to be\njudged.\012Would you like to\ngive it a try?",
  ["56:5fa4"] = "Aqui estão as\nBOLAS PARQUE para\011o Concurso.",
  ["56:5fce"] = "{PLAYER} recebeu\n20 BOLAS PARQUE.",
  ["56:5fe9"] = "The person who\ngets the strong-\011est bug POKéMON\011is the winner.\012You have 20\nminutes.\012If you run out of\nPARK BALLS, you're\011done.\012You can keep the\nlast POKéMON you\011catch as your own.\012Go out and catch\nthe strongest bug\012POKéMON you can\nfind!",
  ["56:60cd"] = "Uh-oh…\012You have more than\none POKéMON.\012You'll have to use\n{STRBUF}, the\012first POKéMON in\nyour party.\012Is that OK with\nyou?",
  ["56:613e"] = "Ótimo, guardaremos\nseus outros\011#MON enquanto\011você compete.",
  ["56:6172"] = "Os #MON de\n{PLAYER} foram\011deixados com\011o ASSISTENTE DO\011CONCURSO.",
  ["56:619e"] = "Escolha o #MON\npara ser usado no\011Concurso, e depois\011venha me ver.",
  ["56:61e3"] = "Certo. Esperamos\nque participe no\011futuro.",
  ["56:620f"] = "Uh-oh…\nThe first POKéMON\012in your party\ncan't battle.\012Please switch it\nwith the POKéMON\012you want to use,\nthen come see me.",
  ["56:6283"] = "Uh-oh…\nBoth your party\012and your PC BOX\nare full.\012You have no room\nto put the bug\011POKéMON you catch.\012Please make room\nin your party or\012your PC BOX, then\ncome see me.",
  ["56:6326"] = "Opa… O primeiro\n#MON na sua\011equipe é um OVO.\012Troque-o com um\n#MON que deseja\011usar, e depois\011venha me ver.",
  ["56:63a1"] = "You still have {STRBUF}\nminute(s) left.\012Do you want to\nfinish now?",
  ["56:63e2"] = "Certo. Espere no\nPortão Norte para\011o anúncio dos\011vencedores.",
  ["56:642a"] = "Certo. Volte para\nfora e termine.",
  ["56:6456"] = "Today's Contest is\nover. We hope you\012will participate\nin the future.",
  ["56:649b"] = "Nós realizamos\nConcursos\011regularmente no\011PARQUE.\012Você deve tentar.",
  ["56:64df"] = "Quando o próximo\nConcurso Caça\011Inseto vai\011acontecer?",
  ["56:6515"] = "The Bug-Catching\nContest is held on\012Tuesday, Thursday\nand Saturday.\012Not only do you\nearn a prize just\012for participating,\nyou also get to\012keep a bug POKéMON\nthat you catch.",
  ["56:660d"] = "Você imagina\nquem faria algo\011como isso? E por\011quê?",
  ["56:6648"] = "Você viu a árvore\nestranha na\011estrada?\012Isso deve explicar\nporque menos\011pessoas estão\011visitando as\011RUÍNAS ALFA.",
  ["56:69c0"] = "Today's {STRBUF}.\nThat means the\012Bug-Catching Con-\ntest is on today.\012The rules are\nsimple.\012Using one of your\nPOKéMON, catch a\012bug POKéMON to be\njudged.\012Would you like to\ngive it a try?",
  ["56:6a70"] = "Aqui estão as\nBOLAS PARQUE para\011o Concurso.",
  ["56:6a9a"] = "{PLAYER} recebeu\n20 BOLAS PARQUE.",
  ["56:6ab5"] = "The person who\ngets the strong-\011est bug POKéMON\011is the winner.\012You have 20\nminutes.\012If you run out of\nPARK BALLS, you're\011done.\012You may keep the\nlast POKéMON you\011catch as your own.\012Go out and catch\nthe strongest bug\012POKéMON you can\nfind!",
  ["56:6b99"] = "Uh-oh…\012You have more than\none POKéMON.\012You'll have to use\n{STRBUF}, the\012first POKéMON in\nyour party.\012Is that OK with\nyou?",
  ["56:6c0a"] = "Ótimo, guardaremos\nseus outros\011#MON enquanto\011você compete.",
  ["56:6c3e"] = "Os #MON de\n{PLAYER} foram\011deixados com\011o ASSISTENTE DO\011CONCURSO.",
  ["56:6c6a"] = "Escolha o #MON\npara ser usado no\011Concurso, e depois\011venha me ver.",
  ["56:6caf"] = "Certo. Esperamos\nque participe no\011futuro.",
  ["56:6cdb"] = "Uh-oh…\nThe first POKéMON\012in your party\ncan't battle.\012Please switch it\nwith the POKéMON\012you want to use,\nthen come see me.",
  ["56:6d4f"] = "Uh-oh…\nBoth your party\012and your PC BOX\nare full.\012You have nowhere\nto put the bug\011POKéMON you catch.\012Please make room\nin your party or\012your PC BOX, then\ncome see me.",
  ["56:6df2"] = "Opa… O primeiro\n#MON na sua\011equipe é um OVO.\012Troque-o com um\n#MON que deseja\011usar, e depois\011venha me ver.",
  ["56:6e6d"] = "You still have {STRBUF}\nminutes left.\012Do you want to\nfinish now?",
  ["56:6eac"] = "Certo. Espere aqui\npara o anúncio dos\011vencedores.",
  ["56:6ee7"] = "Certo. Volte para\nfora e termine.",
  ["56:6f12"] = "Today's Contest is\nover. We hope you\012will participate\nin the future.",
  ["56:6f57"] = "Muitos #MON\nsó podem ser\011vistos no PARQUE.",
  ["56:6f80"] = "DON: Uau, me\nvenceu. Você é\011muito bom.",
  ["56:6fab"] = "DON: A sorte faz\ngrande parte\011disso.\012Você nunca sabe\nqual #MON vai\011aparecer.",
  ["56:6ff6"] = "ED: Eu o invejo.\nNão consegui desta\011vez.",
  ["56:7027"] = "ED: Talvez se\nvença com #MON\011grandes.",
  ["56:7049"] = "NICK: Muito bem!\nVou criar melhor\011meus #MON.",
  ["56:707d"] = "NICK: Talvez se\nobtenha mais\011pontos com\011#MON de cores\011incomuns.",
  ["56:70c1"] = "WILLIAM: Você é\no vencedor? O que\011capturou?",
  ["56:70f1"] = "WILLIAM: Bem,\nestou satisfeito\011pois capturei o\011#MON que quis.",
  ["56:7135"] = "BENNY: Parabéns!\nVocê ganhou meu\011respeito!",
  ["56:7163"] = "BENNY: Eu\ncapturara um\011SCYTHER, mas não\011venci.",
  ["56:7197"] = "BARRY: That POKé-\nMON you caught…\011it's awesome!",
  ["56:71c4"] = "BARRY: É mais\nfácil vencer se\011você pegar um\011#MON inseto de\011nível alto.\012Mas eu acho que\neles levam outros\011pontos em\011consideração.",
  ["56:7232"] = "CINDY: Você\nvenceu? Isso é\011ótimo!\012Importa-se de\nprocurar #MON\011insetos comigo?",
  ["56:727f"] = "CINDY: Eu\nrealmente amo\011#MON insetos!",
  ["56:729f"] = "JOSH: Eu… Eu\nnão acredito que\011perdi na Caça de\011Insetos…",
  ["56:72d0"] = "JOSH: Eu soube que\nalguém venceu com\011um CATERPIE!",
  ["56:7302"] = "SAMUEL: Na próxima\nvez, eu vencerei.",
  ["56:7327"] = "SAMUEL: Droga. Eu\nachei que\011pontuaria mais…",
  ["56:7356"] = "KIPP: Você poderia\nme dar umas dicas?\012Quero estudar seu\nestilo.",
  ["56:7396"] = "KIPP: Eu estudo\nmuito, mas não é\011o bastante para\011vencer.",
  ["56:74dd"] = "Opa… Sua BOLSA\nestá cheia.\012Vamos guardar seu\nprêmio, mas\011somente por hoje.\012Libere espaço,\ne venha me ver\011depois.",
  ["56:754c"] = "{PLAYER}?\012Aqui está o prêmio que guardamos para você.",
  ["57:4122"] = "Oi! Sou WHITNEY!\012Todos viciaram em\n#MON, então eu\011viciei também!\012Os #MON são\nlindos!\012Quer batalhar?\nEntão te aviso--\011sou boa!",
  ["57:41a5"] = "Não…\012…Arrgh!\nVocê é mau!\012Não deveria ser\ntão sério! Sua…\011sua criança!",
  ["57:41f5"] = "Ahhhhh!\012Ahhhhh!\012…Sniff, hic…\n…Seu malvado!",
  ["57:4223"] = "…Sniff…\012What? What do you\nwant? A BADGE?\012Oh, right. I for-\ngot. Here's PLAIN-\011BADGE.",
  ["57:4278"] = "{PLAYER} foi pre-\nsenteado com uma\012INSÍGNIA DA PLANÍ-\nCIE DO GINÁSIO DA\012CIDADE GOLDENROD.",
  ["57:4290"] = "A INSÍGNIA DA PLA-\nNÍCIE deixa seu\012#MON usar SUPERFORÇA\nfora da batalha.\012Também acelera\nseus #MON.\012Oh, leve isso\ntambém!",
  ["57:4307"] = "É o ATRAÇÃO!\nFaz uso total do\012charme dos #-\nMONS.\012Não é perfeito pa-\nra uma linda como\011eu?",
  ["57:4365"] = "Ah, esse foi um\nbom choro!\012Venha me ver de\nnovo! Tchauzinho!",
  ["57:43a0"] = "Don't think I'm a\npushover!",
  ["57:43bb"] = "Droga… Achei que\nvocê era fraco…",
  ["57:43db"] = "In the world of\nPOKéMON, I wonder\012what's stronger:\nmale or female?",
  ["57:441b"] = "I like cute POKé-\nMON better than\011strong POKéMON.\012But I have strong\nand cute POKéMON!",
  ["57:4469"] = "Oh, não, não, não!",
  ["57:447a"] = "Estou tentando\nvencer WHITNEY,\011mas… É deprimente.\012Estou bem! Se\nperder, treinarei\012mais na próxima!",
  ["57:44de"] = "Oh, não. Você fez\nWHITNEY chorar.\012Está bem. Logo\nela parará. Ela\012sempre chora\nquando perde.",
  ["57:4537"] = "Oh, você é um lin-\ndo treinador!\012Gosto de você, mas\nnão facilitarei!",
  ["57:457e"] = "Vamos ver… Opa,\njá acabou?",
  ["57:4599"] = "Uau, você deve ser\nbom para me derro-\011tar. Não relaxe!",
  ["57:45c8"] = "Dê o seu melhor,\nou será derrotado!",
  ["57:45f7"] = "Não! Oh, MEOWTH,\nsinto muito!",
  ["57:4615"] = "Ensinei golpes ao\nMEOWTH para vencer\011qualquer tipo…",
  ["57:4644"] = "Ei! CAMPEÃO em\nprogresso!\012Nesse GINÁSIO\nestão treinadores\011de #MON\011normais.\012Recomendo-lhe usar\n#MON do tipo\011lutador.",
  ["57:46b1"] = "Você venceu?\nÓtimo! Estava\011ocupado admirando\011as damas daqui.",
  ["57:4791"] = "…poxa… Mudei-me\npara cá, mas não\012consigo vender\nminhas bicicletas.\012Por quê?\012Poderia usar uma\nBICICLETA e fazer\011propaganda para\011mim?",
  ["57:4802"] = "Sério? Ótimo!\012Dê-me seu nome e\nnúmero de telefo-\012ne, e te empresta-\nrei uma BICICLETA.",
  ["57:4852"] = "{PLAYER} pegou uma\nBICLICLETA empres-\012tada.",
  ["57:4869"] = "Minhas BICICLETAS\nsão ótimas! Pode\012ir a todo lugar\ncom elas.",
  ["57:48a2"] = "…poxa… Oh, pela\ngentileza das\011pessoas…",
  ["57:48f7"] = "É uma BICICLETA\nnova e brilhante!",
  ["57:49ad"] = "If you treat your\nPOKéMON nicely,\012they will love you\nin return.\012Oh? Let me see\nyour {STRBUF}…",
  ["57:4a06"] = "Ele está bem\nfeliz! Deve lhe\011amar muito.",
  ["57:4a36"] = "Eu sinto que ele\nconfia mesmo em\011você.",
  ["57:4a64"] = "É bem amigável com\nvocê. Ele parece\011estar feliz.",
  ["57:4a98"] = "É bem lindo.",
  ["57:4aa9"] = "Deve tratá-lo me-\nlhor. Ele não se\011apegou a você.",
  ["57:4adb"] = "Parece não gostar\nde você. Ele pare-\011ce triste.",
  ["57:4b0e"] = "Eu sempre perco as\nbatalhas, e meu\012POKÉMON acaba des-\nmaiando…\012Talvez seja por\nele não gostar de\011mim…",
  ["57:4b71"] = "Quando uso um item\nno meu POKÉMON,\011ele fica alegre!",
  ["57:4c7e"] = "BILL: Oi, {PLAYER}!\nFaça-nos um favor\011e leve esse EEVEE.\012Ele veio quando eu\nestava ajustando a\011CÁPSULA DO TEMPO.\012Alguém tem que\ncuidar dele, mas\012eu não gosto de\nficar saindo.\012Posso contar com\nvocê para isso,\011{PLAYER}?",
  ["57:4d49"] = "BILL: I knew it!\nWay to go, hero!\012You're the real\ndeal, dude!\012OK, I'm counting\non you. Take good\011care of it.",
  ["57:4db5"] = "{PLAYER} recebeu\nEEVEE!",
  ["57:4dc8"] = "BILL: O PROFESSOR\nELM diz que EEVEE\012pode evoluir em\nnovos modos des-\011conhecidos.",
  ["57:4e09"] = "Ei, espere. Você\nnão pode levar\011mais #MON.",
  ["57:4e34"] = "Oh… Agora o que\nfarei?",
  ["57:4e49"] = "BILL: I used to\nexperiment with a\011TELEPORTER.\012I ought to do a\nfollow-up.",
  ["57:4e93"] = "Oh, you collect\nPOKéMON? My son\011BILL is an expert.\012He had to leave\nfor the POKéMON\012CENTER in ECRUTEAK\nCITY.",
  ["57:4efa"] = "I am so glad to\nsee my son again.",
  ["57:4f1d"] = "Você é um trei-\nnador?\012Tenho um telefone\nútil para você.",
  ["57:4f58"] = "{PLAYER} gravou\no telefone do\011BILL.",
  ["57:4f72"] = "Meu irmaão fez\no sistema de guar-\011dar #MON no\012COMPUTADOR.\012Eu ia te dar\no telefone do\011BILL…",
  ["57:4fc5"] = "Você não pode\ngravar mais\011telefones.",
  ["57:4fe8"] = "Meu irmão mais\nvelho, BILL, fez\012o sistema de guar-\ndar #MON no\011COMPUTADOR.",
  ["57:50d7"] = "O trêm não veio…\012Já sei! Vou levar\nos passageiros nas\011minhas costas!\012Não vai funcionar.",
  ["57:512e"] = "Logo partiremos\npara SAFFRON.\012Você vai embarcar?",
  ["57:5164"] = "May I see your\nrail PASS, please?\012OK. Right this\nway, sir.",
  ["57:51a0"] = "Perdão. Voce não\ntem um PASSE.",
  ["57:51c3"] = "We hope to see you\nagain!",
  ["57:51de"] = "Nós chegamos em\nGOLDENROD.\012Esperamos vê-lo\nde novo.",
  ["57:5217"] = "Sou o PRESIDENTE.\012Meu sonho era\nfazer um trêm mais\012veloz que qualquer\n#MON.\012Ele realmente\ntorna JOHTO e\011KANTO próximos.",
  ["57:5311"] = "Oh, you're better\nthan WHITNEY.\012Do you know about\nthat moving tree?\012If you wet it with\na SQUIRTBOTTLE, it\011attacks.\012But since you\nhave some BADGES,\011you should be OK.",
  ["57:53b6"] = "Lalala lalalala.\nTome muita água,\011meu amor!",
  ["57:53e9"] = "When I watered\nthat moving tree\012on ROUTE 36, it\njumped!\012I think it must be\na POKéMON.\012But it would take\nsomeone like WHIT-\011NEY, our GYM LEAD-\011ER, to beat it.",
  ["57:5485"] = "Do you know about\nthe moving tree?\012If you water it,\nit jumps up in\011surprise!",
  ["57:5513"] = "The COLOSSEUM--\nupstairs at any\012POKéMON CENTER--is\nfor link battles.\012Battle records are\nposted on the\012wall, so I can't\nafford to lose.",
  ["57:5597"] = "Quantos tipos de\n#MON deve\011haver em todo o\011mundo.\012Há três anos, o\nPROFESSOR CARVALHO\011disse que havia\011150 tipos\011diferentes.",
  ["57:5614"] = "Um #MON de\nnível maior nem\011sempre vence.\012Afinal, ele deve\nter um tipo de\011desvantagem.\012Eu não penso que\nhá um simples\011#MON que seja o\011mais forte.",
  ["57:56fe"] = "Uma vez quando eu\nestava batalhando,\012meu #MON não\npodia usar golpes.\012Os PONTOS DE PO-\nDER, ou PP, de\012seus golpes tinham\nacabado.",
  ["57:576f"] = "Sometimes, a\nhealthy POKéMON\012may be unable to\nuse its moves.\012If that happens,\nheal it at a POKé-\011MON CENTER or use\011an item.",
  ["57:5a38"] = "Bem-vindo à LOJA\nDE DEPARTAMENTOS\011DE GOLDENROD.",
  ["57:5a5c"] = "A LOJA DE DEPAR-\nTAMENTOS tem bons\011produtos.\012Mas muitos itens\nsó estão disponí-\012veis na CASA DE\nJOGOS.",
  ["57:5abf"] = "Hoje vim comprar\nde novo!",
  ["57:5adf"] = "Mamãe é boa para\npechinchar.\012Ele sempre compra\ncoisas mais\011baratas.",
  ["57:5b25"] = "1F SERVICE COUNTER\0122F TRAINER'S\n   MARKET\0123F BATTLE\n   COLLECTION\0124F MEDICINE BOX\0125F TM CORNER\0126F ROOFTOP SQUARE",
  ["57:5cb7"] = "POKéGEAR can store\nup to ten phone\011numbers.\012It's hard to de-\ncide which numbers\011to keep.",
  ["57:5d0d"] = "Eu ganhei meu ABRA\nna CASA DE JOGOS.\012Agora é meu melhor\nparceiro.",
  ["57:5d49"] = "A LOJA DE DEPARTA-\nMENTOS me confima\012que GOLDENROD é\numa cidade grande.\012Os produtos daqui\nnão se encontram\011em outro lugar.",
  ["57:5dba"] = "Seu Companheiro\nde Viagem.\0122ª ANDAR-LOJA DO\nTREINADOR.",
  ["57:5e5e"] = "Eu, eu, estou\nmesmo impaciente!\012Uso RAPIDEZ X na\nbatalha para ace-\011lerar meu #MON.",
  ["57:5ea7"] = "Hey! When you bat-\ntle, do you use X\011SPECIAL?\012It's awesome. It\nreally jacks up\011the SPECIAL stats!",
  ["57:5f09"] = "Para Caçadores\nde Vitória.\0123ª ANDAR-ITENS\nPARA BATALHAS.",
  ["57:5f9d"] = "Ei. Eu adoro\n#MON fortes.\012Eu dou PROTEÍNA\na eles para melho-\011rar seus ATAQUES.",
  ["57:5fe7"] = "FERRO melhora a\nDEFESA do #MON.",
  ["57:6009"] = "Muitos #MON\nevoluem apenas se\012forem trocados via\nCabo Link.\012Conheço quatro:\nMACHOKE, KADABRA,\012HAUNTER e, hum,\nGRAVELER.\012Soube que há\noutros também.",
  ["57:60a2"] = "Deixe-nos Melhorar\nSeus #MON.\0124ª ANDAR-FARMÁCIA.",
  ["57:61d8"] = "Olá. Oh, seu\n#MON…",
  ["57:61ef"] = "É muito apegado\na você.\012Esse golpe deve\nser perfeito para\011vocês.",
  ["57:623b"] = "É adorável!\012Você deve ensiná-\nlo bons golpes TM.",
  ["57:626d"] = "Parece mau. Que\ntal esse TM para\011ele?",
  ["57:6297"] = "Certamente há TMs\nperfeitos para\012seus #MON.",
  ["57:62d6"] = "ITEM SECRETO.\012Com apenas um\npequeno bip, você\011ganha um item.",
  ["57:630e"] = "A opção ITEM\nSECRETO requer um\011Game Boy Color.",
  ["57:6342"] = "Aos domingos, uma\ndama vem para che-\011car os #MON.\012Ela até dá TMs!",
  ["57:6388"] = "Você não pode re-\nnomear um #MON\011trocado.\012O nome é reflexo\ndos sentimentos do\012treinador original\npor ele.",
  ["57:63f9"] = "Personalize seu\n#MON.\0125ª-ANDAR-LOJA DE\nTM.",
  ["57:6560"] = "A vending machine!\nHere's the menu.",
  ["57:6584"] = "Clang! A can of\n{STRBUF}\011popped out!",
  ["57:65a7"] = "Oops, not enough\nmoney.",
  ["57:65c0"] = "There's no more\nroom for stuff.",
  ["57:65e0"] = "Você ouve o\nCANAL SORTUDO?\012Se quiser ganhar,\ntroque #MON\012com muita gente\npara obter diver-\012sos NÚMEROS DE\nIDENTIFICAÇÃO.",
  ["57:665f"] = "Se estiver can-\nsado, consuma be-\011bidas da máquina\011de venda.\012Seu #MON vai\namá-la também.",
  ["57:66af"] = "Take a Break from\nShopping!\0126F ROOFTOP SQUARE",
  ["57:6ab5"] = "Welcome!\012We exchange your\ngame coins for\011fabulous prizes!",
  ["57:6af0"] = "Qual prêmio você\nquer?",
  ["57:6b0d"] = "{STRBUF}.\nVocê está certo?",
  ["57:6b22"] = "Aqui está!",
  ["57:6b30"] = "Perdão! Precisa\nde mais moedas.",
  ["57:6b4d"] = "Perdão. Não pode\nle7ar mais nada.",
  ["57:6b6e"] = "Certo. Acumule\nsuas moedas e\011volte depois!",
  ["57:6b9a"] = "Oh? You don't have\na COIN CASE.",
  ["57:6bba"] = "Sempre jogo nesta\nmáquina de roleta.\012Sempre paga mais\nque as outras, eu\011acho.",
  ["57:6c03"] = "Eu amo essa nova\nmáquina de roleta.\012É mais desafiadora\nque as de CELADON.",
  ["57:6c59"] = "A vida é um jogo.\nVou jogar cartas\011até eu despencar!",
  ["57:6c90"] = "Jogo de cartas…\012Gosto mais dele\nque dos outros\012jogos pois é mais\nfácil de ganhar.\012Mas o pagamento é\nbem menor.",
  ["57:6cfc"] = "Não pararei até\neu ganhar!",
  ["57:6d16"] = "Eu ensinei NEVASCA\nao meu #MON.\012Foi duro obter\nmoedas suficientes\012para ele, mas\nvaleu a pena.",
  ["57:6d72"] = "Não pude vencer\nnas roletas, nem\012no jogo de cartas…\012Fiquei tão furi-\noso que larguei\012meu PORTA MOEDA no\nSUBTERRÂNEO.",
  ["57:6f2c"] = "A FLORESTA ILEX é\ngrande. Cuidado!\011Não se perca.",
  ["57:6f5c"] = "A FLORESTA é\nobservada pelo seu\011protetor.\012Não faça travessu-\nras!",
  ["57:6ffe"] = "Oh, honey. You're\nmaking a POKéDEX?\012It must be hard if\nPOKéMON won't\012appear. Try using\nthis TM.",
  ["57:7057"] = "É o ODOR DOCE.\012Use-o em lugares\nonde apareçam\011#MON. \012Isso vai\natraí-los.",
  ["57:70a2"] = "BUTTERFREE: Freeh!",
  ["57:70b6"] = "Você viu\no santuário\011homenageando o\011protetor?\012Ele observa toda\nFLORESTA através\011do tempo.\012Acho que ele é\num #MON do tipo\011grama.",
  ["57:71b8"] = "Vovô o procurava.",
  ["59:400b"] = "I am the FISHING\nGURU, the elder of\011the FISHING BROS.\012Do you happen to\nknow FISHERMAN\012WILTON? He fishes\non ROUTE 44.\012He came through\nwith an amazing\011tip on the phone.\012Thanks to him, I\ncaught a whole lot\012of a rare POKéMON.\nWhat a day it was!",
  ["59:40fa"] = "É uma foto de\npessoas pescando…\012Elas estão se\ndivertindo…",
  ["59:4177"] = "Um #MON dormi-\nnhoco está descan-\011sando em frente à\011CAVERNA DIGLETT.\012É uma ótima chan-\nce para pegá-lo,\012mas como acordá-\nlo?",
  ["59:41ef"] = "Havia um #MON\ndorminhoco rela-\012xando em frente\nà CAVERNA DIGLETT.\012Mas parece que\nele sumiu.",
  ["59:4255"] = "O NAVIO VELOZ é um\nbom lugar para\012batalhar e encon-\ntrar treinadores.",
  ["59:4292"] = "Oh? Você tem IN-\nSÍGNIAS que nunca\011vi.\012Oh, entendi. Você\nas pegou em JOHTO.",
  ["59:43d8"] = "I'm the CHAIRMAN\nof the POKéMON FAN\011CLUB.\012I've raised over\n150 POKéMON.\012I'm very fussy\nwhen it comes to\011POKéMON.\012Did you visit just\nto hear about my\011POKéMON?",
  ["59:4468"] = "Bom!\nEscute então!\012Bom… meu RAPIDASH\nfavorito…\012É… lindo… amável…\npequeno…\011indomável… mais…\011incrível… oh…\011também acha?…\011Muito… selvagem…\011bonito… gentil…\011eu o amo!\012Abraçá-lo… quando…\ndorme… é quente e\011macio… Oh, e…\011espetacular…\011simplesmente\011divino…\011Opa! Olhe a\011hora! Tomei-lhe\011muito tempo!",
  ["59:4594"] = "Obrigado por me\nescutar. Quero que\011leve isso!",
  ["59:45c9"] = "É um DOCE RARO\nque fortalece o\011#MON.\012Prefiro fortalecer\nmeus #MON com\012batalhas, então\npode levá-lo.",
  ["59:4637"] = "Hello, {PLAYER}!\012Did you come see\nme about my POKé-\011MON again?\012No? Oh… I had more\ntales to tell…",
  ["59:468f"] = "Que pena…\012Volte se quiser\nescutar.",
  ["59:46c4"] = "Nosso PRESIDENTE é\nbem ativo quando o\011assunto é #MON…",
  ["59:46f7"] = "Adoro o modo que\nas CLEFAIRIES me-\012xem seus dedos\nquando tentam usar\012o METRÔNOMO.\nÉ tão adorável!",
  ["59:4756"] = "I love CLEFAIRY,\nbut I could never\012catch one. So I'm\nmaking do with a\012POKé DOLL that I\nfound.",
  ["59:47b1"] = "Oh, I see now. The\ngirl who lost this\012POKé DOLL is sad…\012OK. Could you take\nthis POKé DOLL\012back to that poor\nlittle girl?\012I'll befriend a\nreal CLEFAIRY on\012my own one day.\nNo worries!",
  ["59:4861"] = "{PLAYER} received\nPOKé DOLL.",
  ["59:4875"] = "Você verá. Ainda\nterei uma CLEFAIRY\012verdadeira como\namiga.",
  ["59:48af"] = "Sua BOLSA está\nlotada.",
  ["59:48ca"] = "Olhe meu querido\nBAYLEEF!\012A folha em sua\ncabeça é linda!",
  ["59:4908"] = "It's a CLEFAIRY!\nHuh?\012Oh, right. It's a\nCLEFAIRY POKé\011DOLL.",
  ["59:4940"] = "BAYLEEF: Li liif!",
  ["59:4953"] = "Vamos todos\nescutar aos outros\011treinadores\011educadamente.",
  ["59:4980"] = "Se alguém esnobar,\nserá esnobado!",
  ["59:4a17"] = "Você conhece o\nTREM ÍMÃ?\012É uma ferrovia que\nvai a GOLDENROD\011em JOHTO.",
  ["59:4a6d"] = "Quero ir a SAFFRON\npara ver o TREM\011ÍMÃ.",
  ["59:4ae2"] = "A EQUIPE ROCKET\nnão está mais em\011KANTO.\012Essa falta me\nalegra.",
  ["59:4b21"] = "Estou pensando em\nir às compras em\011SAFFRON.",
  ["59:4b8b"] = "Por muitos anos,\nDIGLETTS cavaram\011um grande túnel\011que vai a uma\011cidade distante.",
  ["59:4c99"] = "SURGE: Hey, little\nboy!\012I have to hand it\nto you. It may not\012be very smart to\nchallenge me, but\011it takes guts!\012When it comes to\nelectric POKéMON,\011I'm number one!\012I've never lost on\nthe battlefield.\012I'll zap you just\nlike I did my\011enemies in war!",
  ["59:4d8a"] = "SURGE: Arrrgh!\nYou are strong!\012OK, boy. You get\nTHUNDERBADGE!",
  ["59:4dc9"] = "{PLAYER} received\nTHUNDERBADGE.",
  ["59:4de3"] = "SURGE: A INSÍGNIA\nDO TROVÃO acelera\011o #MON.\012Considere-a como\nprova de que me\012derrotou. Use-a\ncom orgulho,\011ouviu?",
  ["59:4e55"] = "SURGE: Hey, boy!\nStill slugging and\011chugging away?\012My POKéMON and I\nare still at it!",
  ["59:4ea8"] = "Está aqui para\nvencer o TENENTE\011SURGE?\012Não se eu puder\nimpedir!",
  ["59:4ede"] = "Perdão, eu falhei,\nTENENTE SURGE,\011senhor!",
  ["59:4f02"] = "Quando ainda esta-\nva no exército,\012o TENENTE SURGE\nsalvou minha vida.",
  ["59:4f3a"] = "O TENENTE SURGE\nreconheceu meu\012potencial com\n#MON elétri-\011cos.\012Acha que pode\nme vencer?",
  ["59:4f89"] = "Oh, que chocante!",
  ["59:4f9d"] = "Se as armadilhas\ndo GINÁSIO funci-\012onassem, você es-\ntaria torrado…",
  ["59:4fd9"] = "Vou destruí-lo!\nPrepare-se para\011ser chocado!",
  ["59:500c"] = "Arghh! Superou\nmeus poderes…",
  ["59:5028"] = "Não se conforte\npor me derrotar…\012O TENENTE SURGE\né forte!",
  ["59:5069"] = "Ei! CAMPEÃO em\nprogresso!\012Você teve sorte\nagora.\012O TENENTE SURGE é\nbem cauteloso. Ele\012fez armadilhas por\ntodo GINÁSIO.\012Mas--he-he--elas\nnão estão ativas\011agora.\012Não terá problemas\npara chegar a ele.",
  ["59:5131"] = "Uau! Que batalha\nelétrica!\012Certamente me dei-\nxou nervoso.",
  ["59:5170"] = "Nada! Só há lixo\naqui.",
  ["59:5250"] = "Bem-vindo à CIDADE SAFFRON, lar do TREM ÍMÃ!\012…É o que eu digo normalmente,\011mas o TREM ÍMÃ não está funcionando agora.\012Não está recebendo energia porque há algo de errado\011com a USINA ELÉTRICA.",
  ["59:531d"] = "O TREM ÍMÃ é a\ncoisa mais famosa\011de SAFFRON.",
  ["59:53bb"] = "Oi!\012VERMELHO tem\nestado fora por um\011bom tempo.\012Ele não telefonou\ntambém.\012Logo, nem imagino\nonde ele está e\011o que está\011fazendo.\n \012Dizem que se não\nhá notícia é prova\011de que ele está\011bem, mas ainda me\011preocupo.",
  ["59:547c"] = "Preocupo-me se\nVERMELHO adoecer\011ou se machucar,\011mas ele é um\011homenzinho.\012Orgulho-me por\nele estar fazendo\011só aquilo que\011quer.",
  ["59:54e3"] = "Há programas aqui\nque não passam em\011JOHTO…",
  ["59:554b"] = "{PLAYER} jogou\nNINTENDO 64.\012É melhor ir, não\nhá tempo a perder!",
  ["59:5582"] = "Parece que não\né usado há um bom\011tempo…",
  ["59:562b"] = "DAISY: Oi! Meu\nirmão mais novo\011é o LÍDER DO\011GINÁSIO da CIDADE\011VERIDIANA.\012Mas ele sai tanto\nda cidade, que\011causa problemas\011aos treinadores.",
  ["59:56b1"] = "DAISY: Oi! Chegou\nem boa hora. Que\011tal um pouco de\011chá.\012Quer se juntar\na mim?\012Oh, seus #MON\nestão bem sujos.\012Gostaria que eu\ntratasse de um?",
  ["59:573f"] = "DAISY: De qual\ndeles devo\011tratar?",
  ["59:5761"] = "DAISY: Certo, vou\ndeixá-lo com bom\011visual rapidinho.",
  ["59:5791"] = "{STRBUF}\nparece contente.",
  ["59:57a5"] = "DAISY: Aqui está!\nTudo pronto.\012Vê? Não parece\nótimo.\012É um #MON\ntão lindo.",
  ["59:57f5"] = "DAISY: Sempre\ntomo chá nessa\011mesma hora.\012Junte-se a mim.",
  ["59:582f"] = "DAISY: Não quer\nque eu embeleze\011um? Certo, então\011só tomaremos cha.",
  ["59:5872"] = "DAISY: Oh, perdão.\nHonestamente,\011eu não posso\011embelezar um OVO.",
  ["59:5922"] = "CARVALHO: Ah,\n{PLAYER}!\012Foi bom você ter\npercorrido todo\011o caminho até\011KANTO.\012O que achou dos\ntreinadores daqui?\012Bem fortes, hã?",
  ["59:599d"] = "How is your POKé-\nDEX coming?\012Let's see…",
  ["59:59c3"] = "Se estiver por\naqui, espero que\011me visite de novo.",
  ["59:59f7"] = "CARVALHO: Uau!\nÉ excelente!\012Você coletou as\nINSÍGNIAS dos\011GINÁSIOS em KANTO.\011Parabéns!\012Eu estava certo a\nseu respeito.\012Vou lhe contar,\n{PLAYER}.\012Vou preparar uma\nviagem sua para\011o MONTE PRATA.\012O MONTE PRATA\né uma grande\011montanha que\011é casa de\011vários #MON\011selvagens.\012É muito perigoso\npara treinadores\011medianos, está\011fora dos limites.\012Mas podemos fazer\numa exceção em\011seu caso,\011{PLAYER}.\n\012Vá ao PLANALTO\nÍNDIGO. Pode\011chegar ao MONTE\011PRATA por lá.",
  ["59:5b9d"] = "CARVALHO: Hã? Não\nestá coletando\011INSÍGNIAS DOS\011GINÁSIOS DE KANTO?\012Os LÍDERES de\nGINÁSIO daqui\011são fortes como\011aqueles com quem\011batalhou em\011JOHTO.\012Recomendo que os\ndesafie.",
  ["59:5c37"] = "CARVALHO: Ah,\nestá coletando as\011INSÍGNIAS DOS\011GINÁSIOS DE KANTO.\012Deve ser difícil,\nmas a experiência\011certamente o\011ajudará.\012Venha me ver\nquando pegar\011todas.\012Vou lhe dar um\npresente.\012Continue treinando\nduro, {PLAYER}!",
  ["59:5cf6"] = "O programa de\nrádio do PROFESSOR\011não passa aqui em\011KANTO.\012É uma vergonha,\neu queria ouvi-lo.",
  ["59:5d54"] = "Thanks to your\nwork on the POKé-\011DEX, the PROF's\012research is coming\nalong great.",
  ["59:5da2"] = "Não conte a\nninguém, mas o\011SHOW DO CARVALHO\011não é um programa\011ao vivo.",
  ["59:5de5"] = "Aperte START\npara abrir o MENU.",
  ["59:5e04"] = "A opção SALVAR\nestá no MENU.\012Use-a de modo\nperiódico.",
  ["59:5e40"] = "Não há nada\naqui…",
  ["59:5e59"] = "There's an e-mail\nmessage on the PC.\012…\012PROF.OAK, how is\nyour research\011coming along?\012I'm still plugging\naway.\012I heard rumors\nthat {PLAYER} is\012making quite a\nname for himself.\012I'm delighted to\nhear that.\012ELM in NEW BARK\nTOWN 8-)",
  ["5a:400f"] = "NIDORAN, shake!",
  ["5a:4020"] = "NIDORAN: Gau gau!",
  ["5a:40cb"] = "BROCK: Uau, não é\ncomum termos um\011desafiante de\011JOHTO.\012Sou BROCK, o\nLÍDER DO GINÁSIO\011de PEWTER.\012Sou perito em\n#MON do tipo\011pedra.\012Meus #MON\nsão resistentes à\011maioria dos\011ataques físicos.\011Terá dificuldades\011para lhes causar\011qualquer dano.\012Vamos lá!",
  ["5a:41b6"] = "BROCK: Your POKé-\nMON's powerful at-\011tacks overcame my\011rock-hard defense…\012You're stronger\nthan I expected…\012Go ahead--take\nthis BADGE.",
  ["5a:4238"] = "{PLAYER} received\nBOULDERBADGE.",
  ["5a:4252"] = "BROCK: {PLAYER},\nobrigado. Gostei\011de batalhar com\011você, mesmo eu\011estando um pouco\011irritado.\012A INSÍGNIA DA\nPEDRA deixará seus\011#MON ainda\011mais fortes.",
  ["5a:42d5"] = "BROCK: O mundo\né grande. Ainda\011há vários\011treinadores fortes\011como você.\012Apenas espere e\nveja. Vou me\011tornar bem mais\011forte também.",
  ["5a:435d"] = "Os treinadores\ndesse GINÁSIO\011usam #MON do\011tipo pedra.\012Esse tipo tem\nalta DEFESA.\012As batalhas podem\ndurar um bom\011tempo.\012Você está pronto\npara isso?",
  ["5a:43ec"] = "Tenho que vencer\nessas batalhas…",
  ["5a:440a"] = "Ei, você!\nTreinador de\011JOHTO! BROCK é\011forte. Ele o\011punirá se você não\011levá-lo a sério.",
  ["5a:4469"] = "Ei! CAMPEÃO em\nprogresso! Você\011está bem mesmo.\011Está batalhando\011com os LÍDERES DE\011GINÁSIO DE KANTO?\012Eles são\npessoas fortes e\011dedicadas, como\011aqueles de JOHTO.",
  ["5a:4502"] = "Ei! CAMPEÃO em\nprogresso! Esse\011GINÁSIO não lhe\011de muito problema.\012O jeito\ncomo batalhou\011é realmente\011inspirador.\012Eu falo com\nseriedAde.",
  ["5a:45d3"] = "Oi! Olha só meu\nGYARADOS!\012Eu o criei desde\na forma MAGIKARP.\011Nem acredito na\011força que possui.",
  ["5a:4635"] = "Havia um estranho\nhomem idoso que\011vendia MAGIKARP.\012Ele dizia que as\nMAGIKARPS do\011LAGO dA RAIVA são\011excelentes.",
  ["5a:46fc"] = "…Isso, e o GINÁSIO\nem CINNABAR se\011foi. Fiquei\011chocada mesmo.\012…Sim? Estou no\ntelefone. Saia\011daqui!",
  ["5a:4758"] = "JIGGLYPUFF: Puu\npupuu.",
  ["5a:4770"] = "A maioria dos\n#MON adormece\011se ouvem o\011JIGGLYPUFF cantar.\012Há vários golpes\nque podem ser\011usados somente\011enquanto o #MON\011dorme.",
  ["5a:485a"] = "Gosto de dormir\ncom o rádio\011ligado…\011…Zzzz…",
  ["5a:4a24"] = "Na LIGA #MON,\nvocê será testado\011pela ELITE QUATRO.\012Você tem que\nderrotar todos\011eles.\012Se você perder,\nterá que começar\011tudo de novo!",
  ["5a:4aa1"] = "Espere.\012Você vai encarar o\ndesafio da LIGA\011#MON agora?\012Isso não vai\nacontecer.\012Meu #MON super\nbem treinado vai\011derrotá-lo.\012{PLAYER}!\nEu o desafio!",
  ["5a:4b41"] = "ABRA? Aabra…",
  ["5a:4b50"] = "…Droga… Ainda não\nposso vencer…\012Eu… tenho que\npensar mais em\011meus #MON.\012Humph! Tente não\nperder!",
  ["5a:4ba9"] = "…\012Nossa…\nCom meus\011parceiros, serei\011o CAMPEÃO!",
  ["5a:4be1"] = "Ah! Você está\ndesafiando a\011ELITE QUATRO?\012Tem certeza de\nque está pronto?\012Se precisar de\nmais treino, meu\011ABRA pode\011ajudá-lo.\012Ele pode\nTELEPORTÁ-lo para\011casa.\012Deseja ir para\ncasa agora?",
  ["5a:4c93"] = "Certo, certo.\nAgora imagine sua\011casa…",
  ["5a:4cbd"] = "Certo, certo. A\nmelhor sorte para\011você!",
  ["5a:4cdf"] = "…\012Certo, eu perdi…",
  ["5a:4ddd"] = "Bem-vindo à LIGA\n#MON, {PLAYER}.\012Deixe-me\napresentar-me.\011Eu sou WILL.\012Eu treinei ao\nredor do mundo,\011tornando meus\011#MON psíquicos\011fortes.\012E, por último,\neu fui aceito na\011ELITE QUTRO.\012Eu só consigo\nficar melhorando.\012Perder não existe\ncomo opção!",
  ["5a:4ed8"] = "Eu… Eu não…\nacredito…",
  ["5a:4ef0"] = "Mesmo que eu tenha\nderrotado, eu não\011mudarei meu curso.\012Continuarei\nbatalhando até\011eu superar todos\011os treinadores!\012Agora, {PLAYER},\nande e experimente\011a verdadeira\011ferocidade da\011ELITE QUATRO.",
  ["5a:503f"] = "Fwahahahaha!\012Eu sou KOGA da\nELITE QUATRO.\012Vivo nas sombras,\nsou um ninja!\012Meu estilo\nintricado vai\011confundi-lo e\011destruí-lo!\012Confusão, sono,\nveneno…\012Prepare-se para\nser vítima da\011minha técnica\011sinistra!\012Fwahahahaha!\012#MON não se\nresumem a força\011bruta--em breve\011você verá o\011motivo!",
  ["5a:5155"] = "Ah!\nVocê provou o seu\011valor!",
  ["5a:5176"] = "Eu o submeti a\ntudo que pude.\n \012Mas meus esforços\nfalharam. Eu devo\011melhorar minhas\011técnicas.\012Vá à próxima sala,\ne teste as suas\011habilidades!",
  ["5a:52aa"] = "Eu sou BRUNO da\nELITE QUATRO.\012Sempre treino ao\nextremo porque\011eu acredito em\011nosso potencial.\012É assim que\nficamos fortes.\012Você poderá\nresistir ao\011nosso poder?\012Hm? Não vejo medo\nem você. Parece\011determinado.\011Perfeito para\011batalhar!\012Pronto, {PLAYER}?\nVocê se curvará\011ao nosso poder\011supremo!\012Hoo hah!",
  ["5a:53cf"] = "Por quê? Como\npudemos perder?",
  ["5a:53e8"] = "Como perdi, não\ntenho direito de\011dizer nada…\012Vá enfrentar seu\npróximo desafio!",
  ["5a:54d3"] = "Eu sou KAREN da\nELITE QUATRO.\012Você é {PLAYER}?\nQue divertido.\012Adoro #MON\ndo tipo escuro.\012Acho-os selvagens,\nideais para\011apelar. E eles\011são tão fortes.\n\012Acha que pode\ncombatê-los?\011Apenas tente me\011divertir.\012Vamos lá.",
  ["5a:55a4"] = "Bem, você é bom\nmesmo. Gosto disso\011em treinadores.",
  ["5a:55d5"] = "#MON fortes.\012#MON fracos.\012É apenas uma\npercepção egoísta\011das pessoas.\012Treinadores\nrealmente\011habilidosos\011devem tentar\011vencer com seus\011favoritos.\012Gosto de seu\nestilo. Entendeu o\011que é importante.\012Vá--o CAMPEÃO\nestá esperando.",
  ["5a:5816"] = "LANCE: Estive\nesperando por\011você.\012{PLAYER}!\012Eu sabia que\nvocê, com sua\011técnica, poderia\011conseguir chegar\011aqui.\012Não há necessidade\nde palavras agora.\012Vamos batalhar\npara determinar\011quem de nós é o\011mais forte.\012Como treinador\nmais poderoso e\011como CAMPEÃO da\011LIGA #MON…\012Eu, LANCE, o\nmestre de dragões,\011aceito o seu\011desafio!",
  ["5a:5953"] = "…Acabou.\012Mas é\num sentimento\011estranho.\012Não estou nervoso\npor perder.\011De fato, estou\011feliz.\012Feliz pois\ntestemunhei o\011ascensão do novo\011grande CAMPEÃO!",
  ["5a:59e1"] = "…Nossa.\012Você ficou forte\nmesmo, {PLAYER}.\012Seus #MON\nresponderam à\011sua força e à\011sua natureza\011persistente.\012Como treinador,\nvocê continuará\011a se fortalecer\011com seus #MON.",
  ["5a:5a8c"] = "MARY: Oh, não!\nJá acabou!\012PROFESSOR CARVA-\nLHO, se não fosse\011tão lento…",
  ["5a:5aca"] = "PROF.OAK: Ah,\n{PLAYER}!\012It's been a long\nwhile.\012You certainly look\nmore mature.\012Your conquest of\nthe LEAGUE is just\011fantastic!\012Your dedication,\ntrust and love for\012your POKéMON made\nthis happen.\012Your POKéMON were\noutstanding too.\012Because they be-\nlieved in you as a\012trainer, they per-\nsevered.\012Congratulations,\n{PLAYER}!",
  ["5a:5bf6"] = "MARY: Vamos entre-\nvistar o mais\011novo CAMPEÃO!",
  ["5a:5c26"] = "LANCE: Isso está\nficando um pouco\011barulhento…\012{PLAYER}, poderia\nvir comigo?",
  ["5a:5c70"] = "MARY: Oh, espere!\nNão fizemos a\011entrevista!",
  ["5a:5d51"] = "LANCE: It's been a\nlong time since I\011last came here.\012This is where we\nhonor the LEAGUE\012CHAMPIONS for all\neternity.\012Their courageous\nPOKéMON are also\011inducted.\012Here today, we\nwitnessed the rise\012of a new LEAGUE\nCHAMPION--a\012trainer who feels\ncompassion for,\012and trust in, his\nPOKéMON.\012A trainer who\nsucceeded through\012perseverance and\ndetermination.\012The new LEAGUE\nCHAMPION who has\012all the makings\nof greatness!\012{PLAYER}, allow me\nto register you\012and your partners\nas CHAMPIONS!",
  ["5b:41b3"] = "Partiremos em\nbreve. Por favor\011embarque.",
  ["5b:41de"] = "Perdão. Você não\npode embarcar\011agora.",
  ["5b:41fa"] = "Bem-vindo ao NAVIO\nVELOZ S.S.ÁQUA.\011Você vai embarcar\011hoje?",
  ["5b:4238"] = "May I see your\nS.S.TICKET, sir?",
  ["5b:4259"] = "We hope to see you\nagain!",
  ["5b:4274"] = "{PLAYER} flashed\nthe S.S.TICKET.\012That's it.\nThank you, sir!",
  ["5b:42a9"] = "{PLAYER} tried to\nshow the S.S.\011TICKET…\012…But no TICKET!\012Sorry!\nYou may board only\012if you have an\nS.S.TICKET.",
  ["5b:4310"] = "O NAVIO VELOZ\nsairá na próxima\011Segunda.",
  ["5b:4336"] = "O NAVIO VELOZ\nsairá na próxima\011Sexta.",
  ["5b:435c"] = "SHELLDERS são\nfáceis de capturar\011aqui mas não em\011outros lugares.",
  ["5b:439d"] = "Quantas VARAS\nvocê tem?\012VARAS distintas\ncapturam distintos\011#MON.",
  ["5b:43de"] = "O S.S.ÁQUA usa\njatos para\011deslizar sobre a\011água!",
  ["5b:440a"] = "Há muitos #MON\nem KANTO.\012Eu queria ir lá…",
  ["5b:443f"] = "Não queremos que\nvocê caia no mar,\011logo você não pode\011entrar.",
  ["5b:466e"] = "Partiremos em\nbreve. Por favor\011embarque.",
  ["5b:4699"] = "Perdão. Você não\npode embarcar\011agora.",
  ["5b:46b5"] = "Bem-vindo ao NAVIO\nVELOZ S.S.ÁQUA.\011Você vai embarcar\011hoje?",
  ["5b:46f3"] = "May I see your\nS.S.TICKET, sir?",
  ["5b:4714"] = "We hope to see you\nagain!",
  ["5b:472f"] = "{PLAYER} flashed\nthe S.S.TICKET.\012That's it.\nThank you, sir!",
  ["5b:4764"] = "{PLAYER} tried to\nshow the S.S.\011TICKET…\012…But no TICKET!\012Sorry!\nYou may board only\012if you have an\nS.S.TICKET.",
  ["5b:47cb"] = "O NAVIO VELOZ\nsairá na próxima\011Quarta.",
  ["5b:47f2"] = "O NAVIO VELOZ\nsairá no próximo\011Domingo.",
  ["5b:4818"] = "Você veio de\nJOHTO?\012Soube que muitos\n#MON raros\011vivem por lá.",
  ["5b:49ad"] = "O NAVIO VELOZ\nS.S.ÁQUA está a\011caminho da CIDADE\011VERMILION.\012Vamos avisar\nquando chegarmos\011lá.",
  ["5b:4a0d"] = "O NAVIO VELOZ\nS.S.ÁQUA está a\011caminho da CIDADE\011OLIVINE.\012Vamos avisar\nquando chegarmos\011lá.",
  ["5b:4a6b"] = "Aqui está sua\ncabine.\012Se seus #MON\nse ferirem,\011descanse na cama.\012Isso vai\ncurá-los.",
  ["5b:4ac1"] = "Aqui está sua\ncabine.\012Você pode curar\nseus #MON ao\011dormir na cama.\012O navio vai chegar\nenquanto você\011estiver dormindo.",
  ["5b:4b32"] = "Todos passageiros\nsão treinadores.\012Estão todos\nansiosos para\011batalhar em suas\011cabines.",
  ["5b:4b84"] = "Whoa!\012Excuse me, son.\nI was in a hurry!\012My granddaughter\nis missing!\012She's just a wee\ngirl. If you see\012her, please let me\nknow!",
  ["5b:4c04"] = "FAST SHIP S.S.AQUA\nhas arrived in\011OLIVINE CITY.",
  ["5b:4c35"] = "FAST SHIP S.S.AQUA\nhas arrived in\011VERMILION CITY.",
  ["5b:4dba"] = "Vou a KANTO testar\nminhas técnicas.",
  ["5b:4de0"] = "Eu quis vencer!",
  ["5b:4df2"] = "Treinadores de\nJOHTO podem\011batalhar com\011LÍDERES DE GINÁSIO\011DE KANTO.",
  ["5b:4e2a"] = "Estou treinando\npara ser um\011CAMPEÃO!",
  ["5b:4e4c"] = "O que nos difere\ntanto?",
  ["5b:4e6e"] = "Um dia eu ainda\nvou vencê-lo!",
  ["5b:4e8d"] = "Você conhece LILY?\nÉ uma grande DJ\011em KANTO.",
  ["5b:4eb8"] = "Gyaaaah!",
  ["5b:4ec2"] = "LILY's nice, but\nMARY's the best!\012I want to check\nout JOHTO's radio\011stations!",
  ["5b:4f0e"] = "Você está só?\nVamos batalhar\011então!",
  ["5b:4f30"] = "É muito serviço\npara mim!",
  ["5b:4f4b"] = "Queria saber se\nhá alguma montanha\011boa de escalar em\011KANTO.",
  ["5b:4f89"] = "Sim, sou um\nmarinheiro. Certo.\012Não estava à toa!\012Essa cabine estava\nvaga, então só\011tirei um rápido\011cochilo.\012Ah, esqueça!\nVamos batalhar!",
  ["5b:500e"] = "Perdão! É tudo\nculpa minha!",
  ["5b:5028"] = "Para ser\nmarinheiro, tenho\011que usar a força.\011É exaustivo!",
  ["5b:5068"] = "Oh, não. Perdi\nalgo que é muito\011importante.",
  ["5b:509a"] = "Eu… eu não\nposso achá-lo…",
  ["5b:50ae"] = "I give up. Son,\nyou don't have to\012look. Just forget\nabout it!",
  ["5b:50ec"] = "Legal!\nSorte!",
  ["5b:50fc"] = "Que azar!\nEu perdi!",
  ["5b:5112"] = "Achei uma linda\nmoeda aqui.\012Alguém deve tê-la\nperdido…",
  ["5b:5270"] = "Vou a KANTO para\nfazer shows de\011sopro de fogo!",
  ["5b:52a4"] = "Ihh…A chama está\nfraca…",
  ["5b:52be"] = "Acho que fogo é\nfraco no mar.\012Isso não importa?\nSério?",
  ["5b:52fa"] = "Visitarei minha\navó para capturar\011insetos!",
  ["5b:5329"] = "Ooh, wow. You're\ntough, dude!",
  ["5b:5347"] = "Você pode achar\nmuitos #MON\011nas árvores de\011JOHTO!",
  ["5b:5379"] = "Estou tentando\nesquecer meus\011problemas. Vamos\011batalhar.",
  ["5b:53a4"] = "Meu coração\nsofre…",
  ["5b:53b5"] = "Viajar é ótimo\npara curar um\011coração partido.\012Mas a viagem no\nNAVIO VELOZ é\011curta para isso.",
  ["5b:5418"] = "Vou publicar\nminhas músicas na\011ESTAÇÃO DE RÁDIO\011DE GOLDENROD.",
  ["5b:5456"] = "Nossa!\nDistorção total!",
  ["5b:5470"] = "Falando na\nESTAÇÃO DE RÁDIO,\011qua é o número\011sortudo dessa\011semana?",
  ["5b:54af"] = "Uma cama\nconfortável!\n\012Hora de dormir…",
  ["5b:54cc"] = "Ah, refrescado e\ncurado!",
  ["5b:54e9"] = "FAST SHIP S.S.AQUA\nhas arrived in\011OLIVINE CITY.",
  ["5b:551a"] = "FAST SHIP S.S.AQUA\nhas arrived in\011VERMILION CITY.",
  ["5b:570e"] = "Uau! Obrigado por\nvir.\012Manter essa garota\nse divertindo\011foi exaustivo.",
  ["5b:5760"] = "O que acha\ndo passeio no\011S.S.ÁQUA?\012Ele praticamente\npatina nas ondas.",
  ["5b:57aa"] = "Hello, son…\nI can't find my\011granddaughter.\012If she's on the\nship, that's OK.\012But what if she\nfell overboard?\012She's an energetic\nchild, so she may\012be bugging some-\none. I'm worried…",
  ["5b:585a"] = "{PLAYER}, não é?\n\012Soube que você\ndivertiu minha\011neta.\012Quero agradecê-lo\npor isso.",
  ["5b:58b2"] = "Já sei! Eu\ngostaria que você\011levasse isso!",
  ["5b:58d5"] = "Estamos viajando\naro redor do\011mundo.",
  ["5b:58f7"] = "CAPITÃO, brinque\ncomigo por favor?\012Estou com tédio.\nQuero brincar\011mais!",
  ["5b:5936"] = "Oi! Vai brincar\ncomigo?\012…Oh!\012Vovô está\npreocupado comigo?\012Tenho que ir!\012Tenho que achar\no vovô!",
  ["5b:599b"] = "Vovô, aqui estou!\nEstava brincando\011com o CAPITÃO e\011com esse rapaz!",
  ["5b:59dd"] = "Diverti-me muito\nbrincando!",
  ["5b:59f9"] = "Hey, son! Want to\nbattle with me?",
  ["5b:5a1c"] = "Você é forte!",
  ["5b:5a2b"] = "Você está viajando\nsozinho?\012Sua mãe não está\npreocupada?",
  ["5b:5a5e"] = "Acha que sou um\nbebê? Não é justo!",
  ["5b:5a84"] = "Oh! We lost!",
  ["5b:5a92"] = "Bebê é um nome\nrude para nós\011garotas!",
  ["5b:5ab9"] = "Não sou um bebê!\012Não é bom dizer\nisso a uma dama!",
  ["5b:5aea"] = "Oh! We lost!",
  ["5b:5af8"] = "Às vezes, garotos\nsão mais espertos\011que homens!",
  ["5b:5b25"] = "Ssh! Meu cérebro\nestá captando\011sinas de rádio!",
  ["5b:5b51"] = "…Eu ouvi algo!",
  ["5b:5b67"] = "Já sei. Você pode\nouvir rádio de\011JOHTO no NAVIO\011VELOZ.",
  ["5b:5b9e"] = "O que você acha?\nMeus #MON\011são lindos,\011certo?",
  ["5b:5bce"] = "Oh, não! Meus\nlindos #MON!",
  ["5b:5bec"] = "Devo ir ao\nSALÃO #MON\011e consertar o\011visual deles!",
  ["5b:5c1f"] = "Vou comprar\nna LOJA DE\011DEPARTAMENTOS e\011então…",
  ["5b:5c4d"] = "O que eu ia\nfazer?",
  ["5b:5c66"] = "Oh, sim! Tenho\nque buscar meus\011#MON no\011CRIATÓRIO!",
  ["5b:5c97"] = "What kinds of POKé\nBALLS do you have\011with you?",
  ["5b:5cc4"] = "Espere! Pare!\nNão! Por favor!",
  ["5b:5cdf"] = "Você deve usar\nas BOLAS certas\011para cada\011situação.",
  ["5b:5d15"] = "FAST SHIP S.S.AQUA\nhas arrived in\011VERMILION CITY.",
  ["5b:5f4b"] = "Hey, guy. Could I\nget you to look\011for my buddy?\012He's goofing off\nsomewhere, that\011lazy bum!\012I want to go find\nhim, but I'm on\011duty right now.",
  ["5b:5fd7"] = "Oh, nossa…\012O CAPITÃO ficará\nnervoso…",
  ["5b:5ffe"] = "Thanks, guy!\nI chewed him out\012good so he'll quit\nslacking off!",
  ["5b:603d"] = "Uma garotinha?\012Eu devo tê-la\nvisto por aqui.",
  ["5b:606d"] = "A sala de jantar\né acima.\012As Escadas no\nfinal o levam à\011cabine do CAPITÃO.",
  ["5b:60bd"] = "Ninguém me vence\nquando estou no\011recreio.",
  ["5b:60ea"] = "Vencendo ou não,\no recreio acabou!",
  ["5b:6108"] = "Acho que não\nposso vencer sem\011ser sério.",
  ["5b:6133"] = "Estou tão\nentediada. Quer\011batalhar?",
  ["5b:6151"] = "Uau! Você é muito\nforte!",
  ["5b:6169"] = "SAFFRON, CELADON…\nSoube que há\011várias cidades\011grandes em KANTO.",
  ["5b:61a7"] = "Urrf…\nEstou enjoado!",
  ["5b:61ba"] = "Não posso me mover\nmais…",
  ["5b:61d2"] = "Chega de navios\npara mim. Na\011próxima vez irei\011de TREM ÍMÃ.",
  ["5b:6210"] = "É aqui que\nnós marinheiros\011trabalhamos!",
  ["5b:6230"] = "Perdi jogando\nem casa…",
  ["5b:624a"] = "Recebemos\ndiferentes\011passageiros da\011CIDADE VERMILION\011para a CIDADE\011OLIVINE.",
  ["5b:628c"] = "Embora estamos\nno mar, não posso\011pescar.\012Isso é chato!\nVamos batalhar!",
  ["5b:62d8"] = "Eu… não estou\nchateado mais…",
  ["5b:62f2"] = "Planejo pescar no\npíer de VERMILION.",
  ["5b:6317"] = "Estou fortalecendo\nminhas pernas ao\011forçá-las contra\011o balanço do\011navio!",
  ["5b:6355"] = "Não pude achar\no REI CARATÊ em\011JOHTO.\012Ele deve treinar\nem uma caverna em\011algum lugar.",
  ["5b:636e"] = "Não pude achar\no REI CARATÊ em\011JOHTO.\012Ele deve treinar\nem uma caverna em\011algum lugar.",
  ["5b:63c9"] = "Sou um marinheiro!\012Mas estou\ntreinando\011#MON, daí\011posso ser o\011CAMPEÃO!",
  ["5b:640c"] = "Minha falta de\ntreino é óbvia…",
  ["5b:642f"] = "Oito INSÍGNIAS!\nElas provam que\011você derrotou\011os LÍDERES DE\011GINÁSIO. Você\011certamente é bom!",
  ["5b:6486"] = "Não ponha um dedo\nem meus alunos!",
  ["5b:64a9"] = "Aaack!",
  ["5b:64b1"] = "Estamos em\nexcursão para as\011RUÍNAS fora de\011VIOLETA.",
  ["5b:64e4"] = "Você conhece as\nRUÍNAS ALFA?",
  ["5b:6504"] = "Yaargh!",
  ["5b:650d"] = "Rádios recebem\nsinais estranhos\011nas RUÍNAS.",
  ["5b:653f"] = "Há muitos painéis\nestranhos nas\011RUÍNAS ALFA.",
  ["5b:6576"] = "Estava cansado!",
  ["5b:6586"] = "Eu li que há quatro\ndaqueles painéis\011de pedra.",
  ["5b:667f"] = "FAST SHIP S.S.AQUA\nsails to KANTO on\012Mondays and Fri-\ndays.",
  ["5b:66ed"] = "O NAVIO VELOZ\nsai às Quartas e\011aos Domingos de\011toda semana.",
  ["5b:680b"] = "Shaoooh!",
  ["5b:6882"] = "When the sun goes\ndown, CLEFAIRY\011come out to play.",
  ["5b:693b"] = "Shaoooh!",
  ["5c:400f"] = "I was hoping to\nbuy some SAFARI\012ZONE souvenirs,\nbut it's closed…",
  ["5c:4050"] = "A neta do PATRÃO\nda ZONA DO SAFÁRI\011vive na cidade.",
  ["5c:424f"] = "Fufufufu…\012I'm sorry to dis-\nappoint you…\012I'm only joking!\012I'm the real deal!\012JANINE of FUCHSIA\nGYM, that's me!",
  ["5c:42bb"] = "JANINE: Você\né bem forte.\011Definitivamente\011venceu…\012Eis a INSÍGNIA DA\nALMA. Leve-a.",
  ["5c:4305"] = "{PLAYER} received\nSOULBADGE.",
  ["5c:431c"] = "JANINE: Você é\ntão forte! Tenho\011um presente\011especial!\012É o TÓXICO, um\npoderoso veneno\011que corta de pouco\011em pouco o HP da\011vítima.",
  ["5c:438e"] = "JANINE: Eu\nrealmente vou me\011aplicar e melhorar\011minhas técnicas.\012Quero ser melhor\nque o meu pai e\011que você!",
  ["5c:4400"] = "Fufufu!\012Sou JANINE, a\nLÍDER DO GINÁSIO!\012Não, não sou!\nPeguei você,\011otário!",
  ["5c:4440"] = "Eu o enganara…",
  ["5c:4453"] = "Como saberá quem\né a LÍDER de\011verdade?",
  ["5c:4480"] = "Enganei você!\nHahaha!",
  ["5c:4495"] = "Ooh… Perdi…\nVocê não é fraco…",
  ["5c:44b3"] = "Bem? Meu disfarce\nnão era perfeito?",
  ["5c:44d5"] = "Sou JANINE!\012Como sabia que\nera eu?\012Vamos batalhar!",
  ["5c:450b"] = "Droga! Eu queria\nvencer!",
  ["5c:4526"] = "Você deve estar\nse cansando.",
  ["5c:4542"] = "Wahahaha!\012You betcha, dude.\nI'm JANINE!",
  ["5c:456a"] = "Meu disfarce\nestava bom, não é?",
  ["5c:458b"] = "Hey, dude. Was my\ndisguise cute or\011what, huh?",
  ["5c:45ba"] = "Ei, CAMPEÃO em\nprogresso!\012Opa! Dê uma olhada\nao seu redor.\011Todas treinadoras\011se parecem com a\011LÍDER JANINE.\012Qual delas é a\nJANINE de verdade?",
  ["5c:4646"] = "Essa foi uma\ngrande batalha,\011treinador de\011JOHTO!",
  ["5c:46e4"] = "Meu avô está na\nCASA do meu irmão\011BILL na PENÍNSULA\011CERULEANA.",
  ["5c:471a"] = "I saw these weird,\nslow POKéMON on\011CYCLING ROAD.",
  ["5c:47b5"] = "Hey! You have a\nbrand new kind of\011POKéDEX.\012Did PROF.OAK give\nthat to you?",
  ["5c:47fd"] = "Fiquei chocada\nno GINÁSIO.\012Todas as garotas\nde lá pareciam ser\011idênticas.",
  ["5c:484f"] = "Sou JANINE!\nAbracadabra…\011Puf!",
  ["5c:486f"] = "Vê? Pareço com\nela agora!",
  ["5c:4907"] = "Meu avô é o\nPATRÃO da ZONA DO\011SAFÁRI.\012Pelo menos era…\012Ele decidiu ir\npara umas férias\011e foi através dos\011mares por ele\011mesmo.\012Parou de comandar\na ZONA DO SAFÁRI\011desde então.",
  ["5c:49b2"] = "Várias pessoas se\ndesapontaram\011quando a ZONA\011DO SAFÁRI fechou,\011mas o vovô é tão\011teimoso…",
  ["5c:4a0b"] = "É uma foto de um\nhomem idoso que\011está cercado por\011#MON.",
  ["5c:4a47"] = "É uma foto\nde uma grande\011planície com\011grama e com\011#MON raros se\011divertindo.",
  ["5c:4ac2"] = "You're working on\na POKéDEX? That's\012really something.\nDon't give up!",
  ["5c:4b31"] = "Oh, querido. Você\nme achou.\012Favor não contar\na ninguém sobre\011mim.\012Vou lhe dar isso\npor guardar meu\011segredo. Certo?",
  ["5c:4c13"] = "É difícil ser uma\ncelebridade.\012Em todo lugar que\nvou as pessoas\011me perseguem.\012Só quero ser\ndeixada sozinha…",
  ["5c:4c81"] = "It's tough being a\ntop celebrity.\012Everywhere I go,\npeople chase me.\012I just want to be\nleft alone…",
  ["5c:4ce3"] = "FEAROW: Feero!",
  ["5c:4fa4"] = "Bem-vindo ao\nCOLISEU DO CLUBE\011CABO.\012Pode batalhar com\num amigo aqui.\012Você gostaria de\nbatalhar?",
  ["5c:4ffe"] = "Welcome to CABLE\nCLUB TRADE CENTER.\012You may trade your\nPOKéMON here with\011a friend.\012Would you like to\ntrade?",
  ["5c:5068"] = "Bem-vindo à\nCÁPSULA DO TEMPO\011DO CLUBE CABO.\012Pode viajar ao\npassado e trocar\011seus #MON.\012Você gostaria de\ntrocar através do\011tempo?",
  ["5c:50e2"] = "Seu amigo não\nestá pronto.",
  ["5c:50fd"] = "Antes de conectar,\nvocê deve salvar\011o seu jogo.",
  ["5c:5130"] = "Aguarde.",
  ["5c:513e"] = "A conexão foi\ncancelada devido à\011inatividade.\012Favor contactar\nseu amigo e voltar\011depois.",
  ["5c:519a"] = "Please come again.",
  ["5c:51f2"] = "Não pode se\nconectar ao\011passado aqui.",
  ["5c:5213"] = "Your friend chose\na different room.",
  ["5c:5238"] = "Por favor entre.",
  ["5c:5258"] = "Sorry--{STRBUF}\ncan't be taken.",
  ["5c:5275"] = "You can't take the\n{STRBUF} with a\011{STRBUF}.",
  ["5c:529c"] = "You can't take the\n{STRBUF} that\011has MAIL with you.",
  ["5c:52cd"] = "Perdoe-me, a\nCÁPSULA DO TEMPO\011está sendo\011ajustada.",
  ["5c:52fc"] = "Perdoe-me, a\nMÁQUINA DE TROCA\011está sendo\011ajustada.",
  ["5c:532c"] = "Perdoe-me, A\nMÁQUINA DE BATALHA\011está sendo\011ajustada.",
  ["5c:535d"] = "Olá! Você é\n{PLAYER}, certo?\012Eu tenho algo\npara você.",
  ["5c:5391"] = "Aqui está!",
  ["5c:539f"] = "Esperamos servi-lo\nde novo.",
  ["5c:53bc"] = "Oh, você não tem\nlugar para isso.\012Pare em qualquer\nCENTRO #MON no\011mundo para\011receber o item.",
  ["5c:541a"] = "Não? É muito\nestranho…",
  ["5c:553d"] = "Seu amigo está\npronto.",
  ["5c:55be"] = "Seu amigo está\npronto.",
  ["5d:401f"] = "Ao norte de\nLAVENDER está o\011TÚNEL DE ROCHA.\011Atravesse-o para\011chegar à USINA ELÉTRICA.",
  ["5d:4072"] = "There's a radio\nprogram that plays\011POKé FLUTE music.\012Oh? Ah, your radio\nneeds an EXPN CARD\011to tune into it.",
  ["5d:40db"] = "The RADIO STATION\ncan't broadcast\012because the POWER\nPLANT is down.",
  ["5d:411e"] = "Se a USINA ELÉTRICA não\011funcionasse, o\011TREM IMÃ também\011não funcionaria…\012Isso também\nsignifica que\011a TORRE DE RÁDIO\011não poderia\011realizar transmis-\011sões…",
  ["5d:4222"] = "O SENHOR FUJI mora\naqui, mas não está\011agora.\012Deve estar\nna CASA DA ALMA.",
  ["5d:4271"] = "Umas pessoas de\ncoração ruim\011pararam de cuidar\011de seus #MON.\012O vovô pega os\npobres #MON\011sem casa e cuida\011deles.",
  ["5d:42e7"] = "PSYDUCK: Gu-guwa?",
  ["5d:42fa"] = "NIDORINO: Gyun!",
  ["5d:430b"] = "PIDGEY: Pijji!",
  ["5d:437e"] = "LAVENDER é uma\npequena e quieta\011cidADe no pé das\011montanhas.\012Ficou mais agitada\ndesde a construção\011da TORRE DE RÁDIO.",
  ["5d:445a"] = "O REPELENTE é\nnecessário se você\011for explorar uma\011caverna.\012Apesar de gostar\nde explorar, eu\011ainda não o fiz\011em todas as\011cavernas.",
  ["5d:44dd"] = "I heard about a\ncraftsman who\012makes custom POKé\nBALLS in the JOHTO\012town of AZALEA. I\nwish I had some.",
  ["5d:4586"] = "SENHOR FUJI:\nBem-vindo.\012Hmm… Você\nparece criar\011seus #MON de\011maneira gentil e\011amável.\012Amantes de\n#MON vêm aqui\011para prestar\011homenagens aos\011#MON mortos.\012Por favor, ofereça\ncondolências às\011almas dos #MON\011mortos.\012Tenho certeza que\nisso vai deixá-las\011felizes.",
  ["5d:4680"] = "Há outras covas\nde #MON aqui,\011eu acho.\012Há várias câmaras\nem que só o SENHOR\011FUJI pode entrar.",
  ["5d:46e4"] = "Vim com minha\nmãe para visitar\011covas de #MON…",
  ["5d:470e"] = "Os #MON que\nviveram comigo…\012Eu gosto deles\ncomo meus netos…",
  ["5d:47f2"] = "Bem-vindo!\nFique à vontade\011para checar todo\011esse andar.",
  ["5d:482d"] = "Perdão, mas você\nsó pode visitar o\011andar de baixo.\012Desde que a TORRE\nDE RÁDIO de JOHTO\011foi dominada por\011uma gangue\011criminosa, temos\011reforçado nossa\011segurança.",
  ["5d:48c3"] = "Várias pessoas\ntrabalham duro na\011TORRE DE RÁDIO.\012Devem dar\nseu melhor para\011transmitir bons\011shows.",
  ["5d:492e"] = "Oh, não, não, não!\012Estivemos fora\ndo ar desde que a\011USINA ELÉTRICA\011parou.\012Todo meu Esforço\npara iniciar essa\011estação seria\011inútil se eu não\011transmitisse.\012Estaria arruinado!",
  ["5d:49d4"] = "Ah! Então foi\nvocê {PLAYER} quem\011resolveu o\011problema da USINA\011ELÉTRICA?\012Graças a você,\nnão perdi meu\011trabalho.\012E lhe digo,\nsalvou minha vida!\012Leve isso como\nagradecimento.",
  ["5d:4a74"] = "Com isso, poderá\nsintonizar nos\011programas de rádio\011daqui de KANTO.\012Hahahaha!",
  ["5d:4ac6"] = "Hey there, fellow!\012I am the super\nMUSIC DIRECTOR!\012Huh? Your POKéGEAR\ncan't tune into my\012music programs.\nHow unfortunate!\012If you get an EXPN\nCARD upgrade, you\012can tune in. You'd\nbetter get one!",
  ["5d:4b83"] = "Hey there, fellow!\012I am the super\nMUSIC DIRECTOR!\012I'm responsible\nfor the gorgeous\012melodies that go\nout over the air.\012Don't be square.\nGrab your music\011off the air!",
  ["5d:4c26"] = "1F RECEPTION\n2F SALES\0113F PERSONNEL\0114F PRODUCTION\0115F DIRECTOR'S\011   OFFICE",
  ["5d:4c70"] = "Perk Up POKéMON\nwith Mellow Sounds\012of the POKé FLUTE\non CHANNEL 20",
  ["5d:4d5c"] = "Já foi à\nCIDADE LAVENDER?\012Há uma alta\nTORRE DE RÁDIO lá.",
  ["5d:4df2"] = "Sou o irmão mais\nnovo do GURU DA\011PESCA.\012Vejo que você\ngosta de pescar.\012E não tenho a\nmenor dúvida\011disso!\012Então? Sei que\nacertei.",
  ["5d:4e72"] = "Sim, sim. Como\neu pensei!\012Ei, fã da pesca!\nLeve isso, é a\011SUPER VARA.",
  ["5d:4ebf"] = "Tente pescar em\nqualquer lugar\011que tenha água.\012Lembre-se,\nvocê pode\011capturar #MON\011diferentes usando\011VARAS diferentes.",
  ["5d:4f2f"] = "Está escrito\nEMERGÊNCIA.",
  ["5d:4ff8"] = "Eu, eu estou\nchocado!\012Um garoto de sua\nidade com olhos\011penetrantes e\011cabelo longo veio\011aqui.\012Ele me assustou\ne eu dei meu\011#MON premiado a\011ele.\012Eu ainda tenho um\nsobrando. E se\011ele voltar?\012Você parece forte.\nPoderia cuidar\011do meu #MON por\011enquanto?",
  ["5d:50e2"] = "Oh, obrigado!\012Cuide bem dele,\npor favor!",
  ["5d:5110"] = "{PLAYER} recebeu um\n#MON.",
  ["5d:5124"] = "Sua equipe #MON\nestá cheia.",
  ["5d:513e"] = "Oh, não… O que\nfarei se ele\011voltar?",
  ["5d:5165"] = "Hi! How's my POKé-\nMON?\012I think I'm safe\nnow, so may I have\011it back?",
  ["5d:51a6"] = "Thank you!",
  ["5d:51b2"] = "Ei, meu #MON\nnão está com você.",
  ["5d:51d8"] = "Meu #MON passou\na gostar de você.\012Tudo bem, pode\nficar com ele.\012Mas prometa\ntratá-lo bem!",
  ["5d:5234"] = "Oh, não, não…\nÉ o mesmo que ser\011roubado.",
  ["5d:5261"] = "Para os #MON,\na felicidade é\011estar com a\011pessoa que os\011tratem bem.",
  ["5d:53ee"] = "HAHAHAH!\012Então você chegou\naqui!\012Deixe-me te\ncontar, sou forte!\011Meus #MON\011esmagarão pedras\011e quebrarão ossos!\012Veja isso!",
  ["5d:5464"] = "CHUCK: Urggh!\n…\012Oooarrgh!",
  ["5d:547f"] = "E aí! Está\nassustado agora?\012O quê? Não tem\nnada a ver com\011#MON?\012É verdade!\012Vamos lá! Vamos\nbatalhar!",
  ["5d:54eb"] = "Quê? Hã? Eu perdi!\012Muito bem! Você\nmerece a INSÍGNIA\011DA TEMPESTADE!",
  ["5d:552a"] = "{PLAYER} received\nSTORMBADGE.",
  ["5d:5542"] = "A INSÍGNIA DA\nTEMPESTADE faz\011todos #MON até\011o NÍVEL 70 lhe\011obedecerem, mesmo\011os trocados.\012Também permite seu\n#MON usar o\011VOAR quando não\011estiver em uma\011batalha.\012Ei, leve isso\ntambém!",
  ["5d:55cf"] = "É o SOCODINÂMICO.\012Ele nem sempre\nacerta, mas quando\011consegue, causa\011confusão!",
  ["5d:5625"] = "HAHAHA! Eu gostei\nde batalhar com\011você.\012Mas derrota é\nderrota. Daqui\011para frente,\011treinarei 24 horas\011por dia!",
  ["5d:568c"] = "Meus #MON e eu\nsomos ligados pela\011amizade.\012Nosso laço nunca\nserá quebrado!",
  ["5d:56de"] = "Isso não é real!",
  ["5d:56ef"] = "Você parece ter um\nlaço forte com\011seus #MON\011também!",
  ["5d:5723"] = "Nós, lutadores\nmarciais, não\011tememos nada!",
  ["5d:5745"] = "Foi chocante!",
  ["5d:5756"] = "#MON lutadores\ntêm medo dos\011psíquicos…",
  ["5d:577f"] = "Palavras são\ninúteis. Deixe seu\011punho falar!",
  ["5d:57b5"] = "Eu perdi! Estou\ncalado!",
  ["5d:57ce"] = "Meus raivosos\npunhos destruirão\011seus #MON!",
  ["5d:57f7"] = "Eu fui vencido!",
  ["5d:5809"] = "My POKéMON lost…\nMy pride is shat-\011tered…",
  ["5d:58dd"] = "Did you meet the\nPOKéMANIAC?\012He's always brag-\nging about his\011rare POKéMON.",
  ["5d:5923"] = "The POKéMON GYM\ntrainers here are\011macho bullies.\012If I stick around,\nthey might come\011after me.\012Here's some ad-\nvice: the GYM\012LEADER uses the\nfighting-type.\012So you should\nconfound him with\011psychic POKéMON.\012Wipe out his POKé-\nMON before they\012can use their\nphysical strength.",
  ["5d:5a2a"] = "{PLAYER}! Você\nvenceu! Posso\011dizer só de te\011olhar!",
  ["5d:5ac9"] = "Eu adoro mostrar\nos #MON que eu\011criei. E você?\012Eu vou entrar em\nmuitas batalhas,\011e mostrar meus\011#MON!",
  ["5d:5b52"] = "{PLAYER} recebeu\nPOÇÃOSECRETA.",
  ["5d:5b6c"] = "Minha POÇÃOSECRETA\né muito forte.\012Eu só ofereço\nem caso de\011emergência.",
  ["5d:5bf5"] = "You have magnifi-\ncent POKéMON with\011you.\012How about a photo\nfor a souvenir?",
  ["5d:5c3e"] = "Certo! Sorria\nagora!",
  ["5d:5c52"] = "Oh, isso é tão\nruim. Eu achei que\011seria uma boa\011lembrança…",
  ["5d:5cb8"] = "Você veio de\nOLIVINE?\012Você se lembra das\nquatro ilhas que\011tem no caminho?\012Eu soube que uma\nmística criatura\011aquática se\011esconde nelas.",
  ["5d:5d3b"] = "Eu soube que só se\npode vê-lo se\011tiver a ASA DE\011PRATA.\012Parece ter o\nmesmo cheiro da\011criatura.",
  ["5d:5da5"] = "The whirlpools\naround the islands\012must be caused by\nthe sea creature.",
  ["5e:4011"] = "Olá! Bem-vindo\nà LOJA DE\011DEPARTAMENTOS DE\011CELADON!\012O que há em\ncada andar está\011na parede.",
  ["5e:4057"] = "Esta LOJA DE\nDEPARTAMENTOS é da\011mesma linha\011daquela da CIDADE\011GOLDENROD.\012Elas foram\nrenovadas ao mesmo\011tempo.",
  ["5e:40cb"] = "É minha primeira\nvez aqui.\012É tão grande…\012Tenho medo de me\nperder.",
  ["5e:410c"] = "1F: SERVICE\n    COUNTER\0122F: TRAINER'S\n    MARKET\0123F: TM SHOP\0124F: WISEMAN GIFTS\0125F: DRUG STORE\0126F: VENDING\n    MACHINES",
  ["5e:41ed"] = "Tornei-me\ntreinador\011recentemente.\012Meu filho me\nincentivou a\011fazê-lo.\012Estou\nimpressionado pelo\011acervo de itens\011úteis.",
  ["5e:4262"] = "Meu pai está\ntendo dificuldades\011para aprender\011nomes de itens\011e como eles\011supostamente são\011usados…",
  ["5e:42c0"] = "Ótimos itens para\ntreinadores!\0122ª ANDAR-LOJA DO\nTREINADOR.",
  ["5e:4377"] = "I can't decide\nwhich POKéMON I\012should use this TM\non…",
  ["5e:43aa"] = "Uh-oh! Troquei meu\n#MON sem\011retirar a\011MELHORA dele.",
  ["5e:43eb"] = "Beleza! Finalmente\nconsegui um\011PORYGON!\012Não sou bom nas\nroletas e não\011conseguiria moedas\011suficientes…\012…Hã?\012O PORYGON trocado\nse tornou um\011#MON diferente!",
  ["5e:4485"] = "A LOJA DE TM\nvende golpes\011raros.",
  ["5e:44a9"] = "3ª ANDAR-LOJA DE\nTM.\012Fortaleça seu\n#MON!",
  ["5e:4545"] = "Vim aqui comprar\numa CARTA SURFE\011para enviá-la a\011minha namorada.",
  ["5e:4579"] = "Este é o único\nlugar em que você\011pode comprar a\011CARTA AMÁVEL.",
  ["5e:45b0"] = "PISTA DE CICLISMO\012A Subida Começa\nAqui.",
  ["5e:4647"] = "Quero comprar\nitens que melhorem\011o estado dos\011#MON, mas não\011tenho dinheiro\011suficiente…",
  ["5e:4696"] = "Quero usar o PP\nMAIS para aumentar\011o PP dos golpes.\011Mas ele não é\011vendido.",
  ["5e:46da"] = "Using items on\nthem makes POKé-\011MON happy.\012They hate certain\nitems, though…",
  ["5e:4724"] = "5ª ANDAR-FARMÁCIA.",
  ["5e:486c"] = "A vending machine!\nHere's the menu.",
  ["5e:4890"] = "Clang!\012{STRBUF}\npopped out.",
  ["5e:48aa"] = "Oops, not enough\nmoney…",
  ["5e:48c3"] = "There's no more\nroom for stuff…",
  ["5e:48e3"] = "Uma máquina de\nvenda com roleta\011de prêmio…\012Não se vê mais\ndessas por aí.",
  ["5e:492c"] = "Aww! Não há jogos\naqui!\012Eu queria brincar…",
  ["5e:495a"] = "6F: ROOFTOP SQUARE\nVENDING MACHINES",
  ["5e:4a32"] = "Meus queridos\n#MON me\011acompanham, logo,\011não me sinto só.\012MEOWTH até traz\ndinheiro para cá.",
  ["5e:4a8c"] = "MEOWTH: Meow!",
  ["5e:4a9b"] = "CLEFAIRY: Clef\ncleff!",
  ["5e:4ab2"] = "NIDORAN: Kya\nkyaoo!",
  ["5e:4ac7"] = "MANSÃO CELADON\nSUÍTE DO GERENTE.",
  ["5e:4b55"] = "{PLAYER} ligou o\nCOMPUTADOR.\012…\012Alguém estava\nescrevendo um\011e-mail.\012…Espero que você\nvenha visitar\011KANTO.\012Acho que ficará\nsurpreso com as\011mudanças das\011coisas por aqui.\012Você também verá\nvários #MON\011que não são\011nativos em JOHTO.\012Ao PRODUTOR\012…",
  ["5e:4c48"] = "GAME FREAK\nSALA DE ENCONTRO.",
  ["5e:4cea"] = "Is that right?\012I'm the GAME\nDESIGNER!\012Filling up your\nPOKéDEX is tough,\011but don't give up!",
  ["5e:4d41"] = "Wow! Excellent!\nYou completed your\011POKéDEX!\012Congratulations!",
  ["5e:4d7f"] = "O ARTISTA GRÁFICO\nvai imprimir um\011DIPLOMA para você.\012Você deveria\nexibi-lo.",
  ["5e:4dd0"] = "Sou o ARTISTA\nGRÁFICO.\012Eu o desenhei!",
  ["5e:4df4"] = "I'm the GRAPHIC\nARTIST.\012Oh, you completed\nyour POKéDEX?\012Want me to print\nout your DIPLOMA?",
  ["5e:4e4c"] = "Avise-me se você\nquiser ter seu\011DIPLOMA impresso.",
  ["5e:4eb1"] = "Quem, eu? Sou o\nPROGRAMADOR.\012Jogue as máquinas\nde roleta!",
  ["5e:4ee6"] = "As GÊMEAS não\nsão adoráveis?\012JASMINE é bela\ntambem.\012Oh, eu as amo!",
  ["5e:4f27"] = "GAME FREAK\nSALA DE PRODUÇÃO.",
  ["5e:4f44"] = "É um dEsenho\ndetalhado de uma\011bela garota.",
  ["5e:4f6e"] = "É o programa do\njogo. Bagunçá-lo\011pode causar erros\011no jogo!",
  ["5e:4fb2"] = "It's crammed with\nreference materi-\011als. There's even\011a POKé DOLL.",
  ["5e:50ad"] = "Let me recount a\nterrifying tale…",
  ["5e:50d0"] = "Porém, não é\ntão assustadora\011enquanto está de\011dia.\012Volte após o\npôr-do-sol, certo?",
  ["5e:5129"] = "Era uma vez, um\ngarotinho que\011tinha ganhado uma\011nova BICICLETA…\012Ele queria\ntestá-la de\011qualquer jeito…\012Ele estava se\ndivertindo tanto\011que nem notou o\011pôr-do-sol…\012Enquanto voltava\npara casa na\011noite escura,\011a bicicleta de\011repente ficou\011lenta!\012Os pedais ficaram\npesados!\012Quando parou\nde pedalar, a\011bicicleta começou\011a escorregar para\011trás.\012Como se\nela estivesse\011amaldiçoada e\011tentando jogá-lo\011na escuridão!\012…\012SHRIEEEEK!\012O garoto estava\nsubindo a PISTA\011DE CICLISMO!\012…\nBa-dum ba-dum!\012Por ter escutado\ntão pacientemente,\011poderá levar isso,\011o TM03!",
  ["5e:5339"] = "TM03 é o\nAMALDIÇOAR.\012É um golpe\nterrível que reduz\011o HP da vítima\011lentamente.",
  ["5e:53b4"] = "ERIKA é a mestra\nde #MON grama.\012Ela vai fazê-lo\nsofrer se não\011ficar bem atento.",
  ["5e:5405"] = "O esconderijo da\nEQUIPE ROCKET é\011no porão da CASA\011DE JOGOS.\012Oh, espere. Isso\nfoi há três anos.",
  ["5e:5571"] = "Bem-vindo!\012Você pode trocar,\nao lado, suas\011moedas por prêmios\011fabulosos.",
  ["5e:55b6"] = "As máquinas de\njogo são uma obra\011de arte.",
  ["5e:55e3"] = "É essa máquina\nque quero.\012Ela me limpou\nontem, então ela\011deverá pagar algum\011dia.",
  ["5e:5636"] = "Acho que essa\nmáquina de jogo\011pagará…\012As chances variam\nentre elas.",
  ["5e:567d"] = "Gahahaha!\012As moedas\ncontinuam a cair!\012Hm? O que, garto?\nQuer jogar?\012Dividirei minha\nsorte com você!",
  ["5e:56e6"] = "Gahahaha!\012Sinto-me bem ao\nfazer boas coisas\011a outras pessoas!",
  ["5e:572b"] = "Ei, você não tem\num PORTA MOEDA.\012Como poderei\nlhe dar algumas\011moedas, garoto?",
  ["5e:577a"] = "Ei, seu PORTA\nMOEDA está cheio,\011garoto.\012Você deve estar\nvencendo bastante\011também.",
  ["5e:57c6"] = "Ei! CAMPEÃO em\nprogresso!\012Está jogando as\nmáquinas também?\012Tento ganhar\nmoedas suficientes\011para obter\011#MON.\012Mas não tenho\nmuitas moedas\011ainda…",
  ["5e:584e"] = "Hmmm… Há mais\nchances para a\011linha do PIKACHU.\012Mas… O que faço?",
  ["5e:5894"] = "Ei!\012Debaixo desse\npôster…\012Não há nada!",
  ["5e:58c2"] = "Ei!\012Debaixo desse\npôster…\012Não há nada!",
  ["5e:58f0"] = "Há um esqueiro\naqui.",
  ["5e:5908"] = "Um refrigerante…\012Alguém deve tê-lo\ndeixado…\012Hã? Está vazio!",
  ["5e:5c59"] = "I wanted MR.MIME,\nbut I was short by\011100 coins…",
  ["5e:5c8a"] = "Nossa…\012Tenho que ficar\ncalmo…\012Não posso me\nirritar, pois\011posso perder todo\011meu dinheiro.",
  ["5e:5cdf"] = "Bem-vindo!\012Trocamos suas\nmoedas por prêmios\011fabulosos!",
  ["5e:5d15"] = "Qual prêmio você\nquer?",
  ["5e:5d32"] = "OK, so you wanted\na {STRBUF}?",
  ["5e:5d4e"] = "Aqui está!",
  ["5e:5d5c"] = "Você não\ntem moedas\011suficientes.",
  ["5e:5d79"] = "You have no room\nfor it.",
  ["5e:5d93"] = "Oh. Volte com\nmoedas por favor!",
  ["5e:5db5"] = "Oh? You don't have\na COIN CASE.",
  ["5e:5ec9"] = "ERIKA: Olá…\nTempo adorável,\011não é?\012É tão agradável…\012Tenho medo de\nadormecer…\012Meu nome é ERIKA.\nSou a LÍDER DO\011GINÁSIO DE\011CELADON.\012…Oh? Veio de lá\nde JOHTO, foi o\011que disse? Que\011ótimo…\012Oh. Desculpe-me,\nnão percebi que\011você queria me\011desafiar.\012Muito bem, mas eu\nnão perderei.",
  ["5e:5fdf"] = "ERIKA: Oh!\nAdmito a derrota…\012Você é\nincrivelmente\011forte…\012Darei-lhe\na INSÍGNIA\011ARCO-ÍRIS…",
  ["5e:6037"] = "{PLAYER} obteve uma\nESCAMA RUBRA.",
  ["5e:6051"] = "ERIKA: Foi uma\npartida magnífica.\012Senti-me\ninspirada. Quero\011que você leve\011esse TM.\012É o GIGA DRENO.\012É um golpe\nmaravilhoso que\011drena metade do\011dano que causa e\011fornece ao seu\011#MON.\012Por favor, use\nisso se lhe\011agradar…",
  ["5e:6130"] = "ERIKA: Perder\ndeixa um gosto\011amargo…\012Mas saber que há\nfortes treinadores\011me incentiva a\011melhorar…",
  ["5e:619d"] = "Wait! Only girls\nare allowed here!",
  ["5e:61c1"] = "Oh, bleah!",
  ["5e:61cd"] = "We don't dislike\nboys or anything.\012But there are\ncertain subjects\012that only girls\ncan talk about.",
  ["5e:622f"] = "Oh, uma batalha?\nEstou um pouco\011assustada, mas\011está certo!",
  ["5e:625b"] = "Oh! É isso?",
  ["5e:626a"] = "Oh, olha todas\nsuas INSÍGNIAS.\011Sem dúvida eu\011perderia!",
  ["5e:62a1"] = "Estava olhando\nessas flores ou\011eu?",
  ["5e:62ce"] = "Que irritante!",
  ["5e:62dd"] = "Que tal se eu me\ntornasse uma dama\011como ERIKA?",
  ["5e:630e"] = "Mostraremos-lhe\ngolpes #MON\011que ERIKA nos\011ensinou!",
  ["5e:633e"] = "Oh… We lost…",
  ["5e:634c"] = "ERIKA vai vencê-lo\npor nós!",
  ["5e:636d"] = "Vamos proteger\nERIKA!",
  ["5e:638b"] = "Não pudemos\nvencer…",
  ["5e:639c"] = "ERIKA é muito,\nmuito forte!",
  ["5e:64ba"] = "Oi!\012Estamos fazendo\num concurso de\011comer.\012Não podemos\nservi-lo agora.\011Perdão.",
  ["5e:6505"] = "…Snarfle, chew…",
  ["5e:6516"] = "Não fale comigo!\012Vai quebrar minha\nconcentração!",
  ["5e:6546"] = "…Gulp… Chew…",
  ["5e:6554"] = "Prefiro quantidade\nà qualidade!\012Fico feliz quando\ncheio!",
  ["5e:658a"] = "Munch, munch…",
  ["5e:6599"] = "A comida é boa\naqui, mas a de\011GOLDENROD é a\011melhor que existe.",
  ["5e:65dd"] = "Crunch… Crunch…",
  ["5e:65ee"] = "Ninguém aqui lhe\ndará um pORTA\011MOEDA. Você deve\011procurar em JOHTO.",
  ["5e:6630"] = "Crunch… Crunch…\012Posso ficar\ncomendo!",
  ["5e:6654"] = "Mais, CHEFE!",
  ["5e:6661"] = "Concurso de Comer!\nSem limite de\011tempo!\012Uma batalha sem\nfim! Quem comer\011mais não pagará\011nada!",
  ["5e:66c3"] = "{PLAYER} found a\n{STRBUF}.",
  ["5e:66d5"] = "Mas {PLAYER} não\ntem mais espaço…",
  ["5e:6757"] = "Se você descer na\nPISTA DE CICLISMO,\011vai chegar na\011CIDADE FUCHSIA.",
  ["5e:67e6"] = "Aqui começa a\nPISTA DE CICLISMO.\012É só descida,\nlogo, é pura\011adrenalina.\012É um ótimo tipo\nde sentimento que\011não se sente em\011navios ou em\011trens.",
  ["5e:6874"] = "Ei! Opa! Pare!\012Você não pode\ncruzar a PISTA DE\011CICLISMO sem uma\011BICICLETA.",
  ["5e:690a"] = "Levo meu trabalho\nde GUARDA a sério!\012Ei! Você tem uma\n#DEX!\012Certo. Você pode\nir.",
  ["5e:6970"] = "I take my GUARD\njob seriously.\012Hey! You have a\nPOKéDEX.\012OK. You can go\nthrough.",
  ["5e:6a0a"] = "Expresse-se com\npresentes!\0124ªANDAR-PRESENTES\nDO SÁBIO.",
  ["5e:6a2b"] = "6ª ANDAR-PRAÇA\nDA COBERTURA\012MÁQUINAS DE VENDA.",
  ["5f:4057"] = "BLUE: Yo! Finally\ngot here, huh?\012I wasn't in the\nmood at CINNABAR,\012but now I'm ready\nto battle you.\012…\012You're telling me\nyou conquered all\011the GYMS in JOHTO?\012Heh! JOHTO's GYMS\nmust be pretty\011pathetic then.\012Hey, don't worry\nabout it.\012I'll know if you\nare good or not by\012battling you right\nnow.\012Ready, JOHTO boy?",
  ["5f:4188"] = "AZUL: O quê?\012O que fez para\neu perder para\011você?\012…\012Tsc, está certo…\nEi, leve isso,\011é a INSÍGNIA DA\011TERRA.",
  ["5f:41e9"] = "{PLAYER} received\nEARTHBADGE.",
  ["5f:4201"] = "AZUL: …\012Certo, eu estava\nerrado. Você é\011realmente bom.\012Você é um ótimo\ntreinador.\012Mas um dia\neu ainda vou\011derrotá-lo.\012Não se esqueça\ndisso!",
  ["5f:4285"] = "AZUL: Ouça,\ncara.\012É melhor não\nperder até que\011eu o vença.\011Entendeu?",
  ["5f:42c8"] = "Ei, CAMPEÃO em\nprogresso.\012Como vai você?\nParece que está\011encrencado.\012O LÍDER DO GINÁSIO\né um cara que\011batalhou com o\011CAMPEÃO há três\011anos.\012Ele é dureza.\012Dê na batalha\ntudo que você\011tiver!",
  ["5f:437a"] = "Cara, você é\nrealmente forte…\012Essa foi uma\nmagnífica batalha\011inspiradora.\012Trouxe lágrimas\naos meus olhos.",
  ["5f:442e"] = "Do you put a lot\nof thought into\012naming your\nPOKéMON?\012Giving them good\nnicknames adds to\012the fun of trading\nwith others.",
  ["5f:44a5"] = "Eles são SPEARY,\num SPEAROW,\012e RATTEY, um\nRATTATA.",
  ["5f:44d8"] = "SPEARY: Ch-chun!",
  ["5f:44ea"] = "RATTEY: Kikiii!",
  ["5f:4559"] = "Bem-vindo à CASA\nDO TREINADOR, o\011lugar mais novo\011e agitado em\011VIRIDIANA.\012Nós abrimos\nsomente para\011treinadores.\012Você pode\nbatalhar contra\011o melhor dos\011melhores no andar\011de baixo.",
  ["5f:45ff"] = "VIRIDIANA é a\ncidade mais\011próxima do\011PLANALTO ÍNDIGO.\012Construíram\nesse lugar\011porque vários\011treinadores passam\011por aqui ao irem\011ao PLANANTO\011ÍNDIGO.",
  ["5f:468f"] = "Eles fazem\nbatalhas de\011prática no andar\011de baixo.\012Adoraria ver como\nbatalha bem um\011treinador vindo\011de JOHTO.",
  ["5f:46f7"] = "Acho que não é\npossível ser o\011CAMPEÃO até que\011você vá a todos\011os lugares e\011batalhe com todos\011tipos de pessoa.\012O CAMPEÃO de\nPALLET viajou por\011todas as cidades\011e vilas em KANTO.",
  ["5f:47a3"] = "Nossa… Estou\ndescansando de\011batalhas #MON.",
  ["5f:47ce"] = "Batalhas de\nprática são\011feitas na SALA\011DE TREINAMENTO\011abaixo.\012Treinadores\nhabilidosos são\011convidados a\011participar.",
  ["5f:4837"] = "Não há regras ou\nregulamentos para\011partidas práticas.\011Como nas batalhas\011reais, vale tudo!",
  ["5f:489b"] = "…O que é isso?\nUma estratégia?\012Essa escrita se\nparece com marcas\011de ONIX…\012Está completamente\nilegível…",
  ["5f:49fa"] = "Oi. Bem-vindo\na nossa SALA DE\011TREINAMENTO.\012Pode batalhr com\num treinador por\011dia.",
  ["5f:4a44"] = "{STRBUF} é\nseu oponente de\011hoje.",
  ["5f:4a61"] = "Você gostaria de\nbatalhar?",
  ["5f:4a7c"] = "Por favor vá por\naqui.\012Você pode começar\nlogo.",
  ["5f:4ab0"] = "Perdão. Só aqueles\ntreinadores que\011vão batalhar agora\011podem entrar.",
  ["5f:4af7"] = "I'm sorry, sir.\nThis would be your\012second time today.\nYou're permitted\012to enter just once\na day.",
  ["5f:4b57"] = "Perdi…\nDroga…",
  ["5f:4b66"] = "Viajei para cá\npara então poder\011batalhar com você.",
  ["5f:4bd3"] = "O LÍDER DE GINÁSIO\ndaqui é todo\011legal.",
  ["5f:4bf9"] = "Já foi a CINNABAR?\012É uma ilha que\nfica ao sul daqui.",
  ["5f:4c8c"] = "Onde estará o\nLÍDER DE GINÁSIO\011DE VIRIDIANA?\012Eu queria\ndesafiá-lo.",
  ["5f:4cd4"] = "Não há TREINADORES\nDE GINÁSIO no\011GINÁSIO DE\011VIRIDIANA.\012O LÍDER diz que\nsua política é\011vencer sem ajuda\011de subordinados.",
  ["5f:4d4a"] = "Soube que\no GINÁSIO em\011CINNABAR se foi.\012O que acontecerá\na BLAINE, O LÍDER\011DO GINÁSIO.",
  ["5f:4da7"] = "Meu sonho é\nser um LÍDER DE\011GINÁSIO.",
  ["5f:4e44"] = "Oi! Uau, Estou\nfeliz por vê-lo.\012É o primeiro\nvisitante a vir\011em um longo tempo.\012Estou super-feliz!\012Vou lhe dar um\npresentinho.",
  ["5f:4ec4"] = "É uma PEPITA.\012Não posso lhe dar\numa pepita da\011sabedoria, então\011vai essa mesmo!",
  ["5f:4f34"] = "Você é {PLAYER}?\012Eu trabalho\ncomo AJUDANTE\011DO PROFESSOR\011CARVALHO.\012Eu nem fazia\nidéia de que você\011estava por aqui.\012O LABORATÓRIO DO\nPROFESSOR CARVALHO\011é aqui perto, na\011CIDADE PALLET.",
  ["5f:5008"] = "Só treinadores que\nprovaram seu valor\011podem passar.",
  ["5f:503e"] = "Você não tem todas\nas INSÍGNIAS DE\011GINÁSIO DE JOHTO.\012Perdão, mas não\nposso deixá-lo\011entrar.",
  ["5f:5093"] = "Oh! The eight\nBADGES of JOHTO!\012Please, go right\nahead, sir!",
  ["5f:50d0"] = "Esse caminho leva\nao MONTE PRATA.\012Verá #MON\nextremamente for-\011tes lá.",
  ["5f:5116"] = "Para a LIGA\n#MON, você está\011indo?\012A ELITE QUATRO é\ntão forte que\011assusta, e eles e\011tão prontos para\011você!",
  ["60:43f7"] = "ELM: {PLAYER}!\nThere you are!\012I needed to ask\nyou a favor.\012I have an acquain-\ntance called MR.\011POKéMON.\012He keeps finding\nweird things and\012raving about his\ndiscoveries.\012Anyway, I just got\nan e-mail from him\012saying that this\ntime it's real.\012It is intriguing,\nbut we're busy\012with our POKéMON\nresearch.\012Could you look\ninto it for us?\012I'll give you a\nPOKéMON for a\011partner.\012They're all rare\nPOKéMON that we\011just found.\012Go on. Pick one!",
  ["60:4590"] = "Se um #MON\nselvagem surgir,\011deixe seu #MON\011batalhar com ele!",
  ["60:45c2"] = "ELM: Espere!\nAonde está indo?",
  ["60:45e3"] = "ELM: Você quer\no CYNDAQUIL, um\011#MON do tipo\011fogo?",
  ["60:460e"] = "ELM: Você quer\no TOTODILE, um\011#MON do tipo\011água?",
  ["60:463a"] = "ELM: Então, gostou\nda CHIKORITA, um\011#MON grama?",
  ["60:4668"] = "ELM: Pense com\ncuidado.\012Seu parceiro é\nmuito importante.",
  ["60:46a2"] = "ELM: Eu acho\nque é um ótimo\011#MON!",
  ["60:46c8"] = "{PLAYER} received\n{STRBUF}!",
  ["60:46db"] = "MR.POKéMON lives\nnear CHERRYGROVE,\011the next city.\012It's almost a\ndirect route to\011there.",
  ["60:472f"] = "If your POKéMON is\nhurt, you should\012heal it with this\nmachine.",
  ["60:476c"] = "Oh, here's my\nphone number.\012Call me if some-\nthing comes up.",
  ["60:47a9"] = "{PLAYER} obteve o\ntelefone de ELM.",
  ["60:47c3"] = "MR.POKéMON goes\neverywhere and\011finds rarities.\012Too bad they're\njust rare and\011not very useful…\012{PLAYER}, I'm\ncounting on you!",
  ["60:4835"] = "Contém um #MON\npego pelo\011PROFESSOR ELM.",
  ["60:485d"] = "O que será que\nisso faz?",
  ["60:4877"] = "Heal POKéMON?",
  ["60:4883"] = "ELM: {PLAYER}, isso\né terrível…\012Oh, sim, qual\nfoi a grande\011descoberta do\011SENHOR #MON?",
  ["60:48c8"] = "{PLAYER} entregou o\nOVO ESTRANHO ao\011PROFESSOR ELM.",
  ["60:48ef"] = "ELM: Isso?",
  ["60:48fb"] = "Mas… Isso é um\nOVO #MON?\012Se for, será uma\ngrande descoberta!",
  ["60:4936"] = "ELM: What?!?\012PROF.OAK gave you\na POKéDEX?\012{PLAYER}, is that\ntrue? Th-that's\011incredible!\012He is superb at\nseeing the poten-\011tial of people as\011trainers.\012Wow, {PLAYER}. You\nmay have what it\012takes to become\nthe CHAMPION.\012You seem to be\ngetting on great\011with POKéMON too.\012You should take\nthe POKéMON GYM\011challenge.\012The closest GYM\nwould be the one\011in VIOLET CITY.",
  ["60:4a85"] = "…{PLAYER}. The\nroad to the\012championship will\nbe a long one.\012Before you leave,\nmake sure that you\011talk to your mom.",
  ["60:4af2"] = "ELM: Não desista!\nEu te ligarei se\011eu aprender algo\011sobre aquele OVO!",
  ["60:4b33"] = "ELM: {PLAYER}? Você\nnão encontrou meu\011assistente?\012Ele deveria\nte encontrar\011possuindo o OVO no\011CENTRO #MON\011da CIDADE VIOLETA.\012Você deve não ter\nvisto ele. Tente\011achá-lo lá.",
  ["60:4bd1"] = "ELM: Ei, o OVO\nteve alguma\011alteração?",
  ["60:4bf6"] = "{PLAYER}? Eu pensei\nque o OVO chocara.\012Onde está o\n#MON?",
  ["60:4c28"] = "ELM: {PLAYER}, você\nparece ótimo!",
  ["60:4c41"] = "O quê?\nEsse #MON!?!",
  ["60:4c55"] = "O OVO chocou!\nEntão, os #MON\011nascem de OVOS…\012Não, talvez nem\ntodos os #MON.\012Uau, ainda há\nmuita pesquisa a\011ser feita.",
  ["60:4cd2"] = "Obrigado, {PLAYER}!\nVocê está nos aju-\011dando a desvendar\011os mistérios dos\011#MON!\n\012Eu quero que você\nleve esse pre-\011sente nosso.",
  ["60:4d43"] = "That's an\nEVERSTONE.\012Some species of\nPOKéMON evolve\012when they grow to\ncertain levels.\012A POKéMON holding\nthe EVERSTONE\011won't evolve.\012Give it to a POKé-\nMON you don't want\011to evolve.",
  ["60:4ded"] = "ELM: {PLAYER}, eu\nte ligarei se algo\011acontecer.",
  ["60:4e1b"] = "…poxa… Aquele\n#MON roubado.\012Como será que\nele estar?\012Dizem que um\n#MON treinado\012por genta má\nse torna igual.",
  ["60:4e86"] = "ELM: Oi, {PLAYER}!\nGraças a você, a\n \012pesquisa está\nótima!\012Eu quero que\naceite esse pre-\011sente meu.",
  ["60:4ee7"] = "The MASTER BALL is\nthe best!\012It's the ultimate\nBALL! It'll catch\012any POKéMON with-\nout fail.\012It's given only to\nrecognized POKéMON\011researchers.\012I think you can\nmake better use of\012it than I can,\n{PLAYER}!",
  ["60:4fa4"] = "ELM: {PLAYER}!\nAí está você!\012Liguei porque eu\ntenho algo para\011você.\n \012Vê? É uma PASSAGEM\nde navio.\012Agora pode captu-\nrar #MON em\011KANTO.",
  ["60:5020"] = "O navio parte da\nCIDADE OLIVINE.\012Você já sabia\ndisso, {PLAYER}.\012Aliás, você\nviajou por tudo\011com seu #MON.\012Dê meus cumprimen-\ntos ao PROFESSOR\011CARVALHO em KANTO!",
  ["60:50e9"] = "{PLAYER}, eu quero\nque tenha isso\011para sua missão.",
  ["60:5116"] = "Há apenas dois de\nnós, então estamos\011sempre ocupados.",
  ["60:5146"] = "Havia um barulho\nlá fora…\012Quando fomos\nolhar, alguém\011roubou um #MON.\012É inacreditável\nque alguém tenha\011feito aquilo!\012…poxa… Aquele\n#MON roubado.\012Como ele deve\nestar.\012Dizem que um\ntreinado por\012gente má se\ntorna igual.",
  ["60:5229"] = "{PLAYER}!\012Use these on your\nPOKéDEX quest!",
  ["60:524b"] = "To add to your\nPOKéDEX, you have\011to catch POKéMON.\012Throw POKé BALLS\nat wild POKéMON\011to get them.",
  ["60:52a1"] = "Soube que um POKé-\nMON foi roubado\011aqui…\012Eu estava colhendo\ninformações do\011PROFESSOR ELM.\012Aparentemente, foi\num jovem rapaz de\011longos cabelos\011rubros…\012O quê?\012Você batalhou com\num treinador\011assim?\012Você conhece o\nnome dele?",
  ["60:5371"] = "OK! So {RIVAL}\nwas his name.\012Thanks for helping\nmy investigation!",
  ["60:53ae"] = "A janela está\naberta.\012Uma boa brisa\nestá soprando.",
  ["60:53e2"] = "Ele quebrou por\naqui!",
  ["60:53fd"] = "{PLAYER} abriu um\nlivro.\012Dica de Viagem 1:\012Aperte START para\nabrir o MENU.",
  ["60:543b"] = "{PLAYER} abriu um\nlivro.\012Dica de Viagem 2:\012Grave sua viagem\ncom o SALVAR!",
  ["60:5477"] = "{PLAYER} abriu um\nlivro.\012Dica de Viagem 3:\012Abra sua BOLSA e\naperte SELECT para\011mover itens.",
  ["60:54c6"] = "{PLAYER} abriu um\nlivro.\012Dica de Viagem 4:\012Cheque os golpes\nde seu #MON.\012Aperte o botão A\npara mover golpes.",
  ["60:5521"] = "OBSERVAÇÕES NA\nEVOLUÇÃO #MON\012…Está dito na\ntela…",
  ["60:5719"] = "Oh, {PLAYER}…!\nNosso vizinho,\011PROFESSOR ELM,\011procurava por\011você.\012Ele disse que\nqueria um favor\011seu.\012Oh! Eu quase me\nesqueci!\012Sua #MON GEAR \nchegou da oficina \011de reparos. Aqui\011está ela!",
  ["60:57d2"] = "POKéMON GEAR, or\njust POKéGEAR.\012It's essential if\nyou want to be a\011good trainer.\012Oh, the day of the\nweek isn't set.\012You mustn't forget\nthat!",
  ["60:5857"] = "Nós estamos no\nHORÁRIO DE VERÃO?",
  ["60:5878"] = "Volte depois para\najustar seu\011relógio para o\011HORÁRIO DE VERÃO.\012A propósito, você\nsabe usar o\011CELULAR?",
  ["60:58e0"] = "Don't you just\nturn the POKéGEAR\012on and select the\nPHONE icon?",
  ["60:591c"] = "I'll read the\ninstructions.\012Turn the POKéGEAR\non and select the\011PHONE icon.",
  ["60:5965"] = "Os telefones\nficarão guardados\011na memória.\012Apenas escolha a\npessoa desejada.\012Nossa, não é\nsimples?",
  ["60:59ca"] = "O PROFESSOR ELM\nestá te esperando.\012Apresse-se,\nquerido(a)!",
  ["60:59fa"] = "Então, o que o PROFESSOR ELM queria?\012…\012Isso parece bem\ndesafiador.\012 Mas, deve se\norgulhar pois as\011pessoas confiam\011em você.",
  ["60:5a6c"] = "{PLAYER}, faça-o!\012Sempre estarei\npor perto!",
  ["60:5a92"] = "Especialidade da\nMamãe!\012HAMBURGER VULCÃO\nCINNABAR!",
  ["60:5abc"] = "O fogão está\nlimpinho. Mamãe\011adora limpeza.",
  ["60:5ae9"] = "Vamos ver o que\nhá na geladeira…\012ÁGUA FRESCA e\nLIMONADA GOSTOSA!",
  ["60:5b28"] = "Há um filme na TV:\nEstrelas surgem\011no céu enquanto\011dois garotos andam\011de trêm…\012É melhor eu ir\ntambém!",
  ["60:5c5c"] = "PROF.OAK'S POKéMON\nTALK! Please tune\011in next time!",
  ["60:5c8d"] = "CANAL #MON!",
  ["60:5c9c"] = "This is DJ MARY,\nyour co-host!",
  ["60:5cbc"] = "POKéMON!\nPOKéMON CHANNEL…",
  ["60:5d64"] = "O PIKACHU é um\n#MON evoluído.\012As descobertas do\nPROFESSOR ELM me\011fascinam.\012Ele é tão famoso\npor suas pesquisas\011na evolução\011#MON.\012…poxa…\012Gostaria de ser\numa pesquisadora\011como ele…",
  ["60:5e09"] = "PROF.OAK'S POKéMON\nTALK! Please tune\011in next time!",
  ["60:5e3a"] = "CANAL #MON!",
  ["60:5e49"] = "This is DJ MARY,\nyour co-host!",
  ["60:5e69"] = "POKéMON!\nPOKéMON CHANNEL…",
  ["60:5eb8"] = "Hi, {PLAYER}! My\nhusband's always\012so busy--I hope\nhe's OK.\012When he's caught\nup in his POKéMON\012research, he even\nforgets to eat.",
  ["60:5f2c"] = "Quando eu crescer,\nvou ajudar meu\011pai!\n \012Eu vou ser um\ngrande professor\011#MON!",
  ["60:5fdc"] = "#MON. De onde\neles vieram? \012Para onde\neles vão?\012Por que ninguém\ntestemunhou um\011nascimento de\011#MON?\012Eu queria saber!\nVou dedicar minha\011vida ao estudo\011#MON!\012…\012Esses são os\npensamentos do\011nosso PROFESSOR\011ELM!",
  ["60:610b"] = "Seus #MON\nparecem estar\011cansados.\012Você deve dar um\ndescanso a eles.",
  ["60:6149"] = "Pronto!\012Seus #MON\nparecem bons!\012Continue assim!",
  ["60:61b7"] = "Há algo escrito\naqui.\012Deseja ler?",
  ["60:61e0"] = "Aos meus irmãos e\nirmãs:\012Temos orgulho\nem servir\011os treinadores\011#MON.\012Quando eles\nconversarem com\011você, dê-lhes\011algo útil.\012Com amor, MÔNICA\012Continuar lendo?",
  ["60:6277"] = "Segunda, MÔNICA\nROTA 40\012Terça, TUSCANY\nROTA 29\012Quarta, WESLEY\nLAGO DA RAIVA\012Quinta, ARTHUR\nROTA 36\012Sexta, FRIEDA\nROTA 32\012SáBado, SANTOS\nVILA BLACKTHORN\012Domingo, SUNNY\nROTA 37.",
  ["60:6384"] = "Aonde está indo\ncom os #MON?\012LIGA #MON?\012Seus #MON são\nleais a você o\011bastante para\011vencerem?\012Deixe-me ver…",
  ["60:63e9"] = "Ah! Seus #MON\nconfiam muito em\011você.\012É ótimo ver um\nbom treinador.\012Ei. Eis um\npresente para sua\011jornada.",
  ["60:644d"] = "O TM37 é o AREIAL.\012É um golpe que\ncausa danos\011em ambos\011batalhadores.\012É apenas\npara treinadores\011avançados.\012Use-o se tiver\ncoragem.\012Boa sorte!",
  ["60:64dd"] = "Se não confiarem\nmais pouco em\011você, vai ser\011difícil ganhar.\012Confiança é o laço\nque une #MON\011a treinadores.",
  ["60:657f"] = "Você não pode\nsubir as beiras.\012Mas você pode\npulá-las para\011pegar um atalho.",
  ["60:65cb"] = "Diferentes tipos\nde #MON\011aparecem por aqui.\012Se quiser\ncapturá-los, terá\011que procurar em\011todos lugares.",
  ["61:400d"] = "Olá!\012O REI CARATÊ,\nmestre do GINÁSIO\011DE LUTA, está em\011uma caverna em\011JOHTO treinando.",
  ["61:4061"] = "Tudo que vai\nvolta!",
  ["61:4081"] = "Inimigos em todos\nos lados!",
  ["61:4180"] = "SABRINA: Sabia\nque você viria…\012Há três anos\ntive uma visão de\011sua chegada.\012Quer a minha\nINSÍGNIA.\012Não gosto de\nbatalhar, mas é\011meu dever como\011LÍDER de conferir\011INSÍGNIAS àqueles\011que provarem o\011seu valor.\012Como você quer,\nvou mostrá-lo meus\011poderes psíquicos!",
  ["61:4295"] = "SABRINA: Seu\npoder…\012É bem maior do\nque eu vi…\012Talvez seja\nimpossível prever\011totalmente o\011que o futuro\011guarda…\012Certo, você venceu\ne mereceu a\011INSÍGNIA DA LAMA.",
  ["61:4336"] = "{PLAYER} received\nMARSHBADGE.",
  ["61:434e"] = "SABRINA: A\nINSÍGNIA DA\011LAMA libera\011seus poderes\011sobrenaturais…\012Mesmo tendo\nfalhado na\011precisão da\011previsão de seu\011poder, o que eu\011sei é verdade.\012Você se tornará um\ncelebrado a amado\011CAMPEÃO!",
  ["61:440d"] = "SABRINA: Seu\namor pelos seus\011#MON superou\011meus poderes\011psíquicos…\012O poder do amor,\neu acho, também\011é um tipo de poder\011psíquico…",
  ["61:448a"] = "O poder de todos\nque derrotou vem\011para mim!",
  ["61:44bc"] = "Forte…\nMuito forte…",
  ["61:44d5"] = "Qual é a fonte de\nseu poder?",
  ["61:44f8"] = "O poder psíquico\né o poder de sua\011alma.",
  ["61:4522"] = "Sua alma tem mais\npoder que a minha!",
  ["61:4547"] = "Você fortaleceu\nsua alma, não\011apenas suas\011habilidades.",
  ["61:457e"] = "Fufufufu…\nVejo claramente.\012Posso ver dentro\nde sua alma!",
  ["61:45b5"] = "Mesmo te lendo,\neu perdi…",
  ["61:45d7"] = "Droga! Esqueci\nque previ que eu\011perderia para\011você.",
  ["61:460d"] = "O GINÁSIO DE\nLUTA ao lado já\011foi o GINÁSIO\011dessa cidade.",
  ["61:4643"] = "Não fui páreo…",
  ["61:4654"] = "O REI CARATÊ, o\nmestre do GINÁSIO\011DE LUTA, foi\011destruído pela\011SABRINA.",
  ["61:46a2"] = "Ei, CAMPEÃO em\nprogresso!\012Um treinador\nhabilidoso como\011você não precisa\011ser informado\011de como lidar\011com #MON\011psíquicos, certo?\012Espero muito de\nvocê! Boa sorte!",
  ["61:4741"] = "Essa foi\noutra fantástica\011batalha!",
  ["61:486d"] = "Há uma grande\nTORRE DE RÁDIO\011em LAVENDER.",
  ["61:4894"] = "Quero me\nfortalecer, mas\011não sou boa\011ainda…\012Poderia me mostrar\ncomo, um dia?",
  ["61:493b"] = "There's a huge\nPOWER PLANT north\011of LAVENDER TOWN.",
  ["61:496e"] = "Acabei de\natravessar o\011TÚNEL DE ROCHA.\012Havia uma\nconfusão na USINA\011ELÉTRICA.",
  ["61:49c9"] = "Cavernas se\ndesmoronam\011facilmente.\012Muitas cavernas\nsumiram no\011passado, como\011aquela que fica\011fora de CERULEANA.\012Para um ANDARILHO\navançado, essa\011informação é\011básica.",
  ["61:4a60"] = "PRÉDIO DE\nESCRITÓRIO da\011CORPORAÇÃO SILPH\011e ESTAÇÃO DO\011TREM ÍMÃ são\011pontos turísticos\011em SAFFRON.",
  ["61:4b33"] = "…\012…\012…\012…Já sei!\012Você queria isso!",
  ["61:4b56"] = "TM29 is PSYCHIC.\012It may lower the\ntarget's SPECIAL\011abilities.",
  ["61:4c45"] = "Perdão, mas o\nTREM ÍMÃ não está\011funcionando agora.",
  ["61:4c79"] = "Partiremos\nem breve para\011GOLDENROD.\012Você vai embarcar?",
  ["61:4cb3"] = "May I see your\nrail PASS, please?\012OK. Right this\nway, sir.",
  ["61:4cef"] = "Perdão, mas você\nnão tem o PASSE.",
  ["61:4d11"] = "We hope to see you\nagain.",
  ["61:4d2c"] = "Chegamos a\nSAFFRON.\012Esperamos vê-lo\nde novo.",
  ["61:4d63"] = "O TREM ÍMÃ é um\nsuper moderno\011transporte fer-\011roviário que usa\011eletricade e\011ímãs para\011atingir incríveis\011velocidades.\012Mas, se não houver\neletricidade…",
  ["61:4dfa"] = "Nossa…\012Quantas vezes eu\njá atravessei o\011caminho entre\011KANTO e JOHTO?",
  ["61:4e44"] = "Antes da ESTAÇÃO\nDO TREM ÍMÃ ser\011construída, havia\011uma casa aqui.\012Uma garotinha\nchamada DUPLICA\011morava aqui.",
  ["61:4eb9"] = "Oi. Você tem\num PASSE de trem?\011Eu tenho um.\011Todas pessoas em\011SAFFRON que andam\011de TREM ÍMÃ têm\011PASSES.",
  ["61:4f9c"] = "Welcome. This is\nSILPH CO.'s HEAD\011OFFICE BUILDING.",
  ["61:4fcf"] = "Só funcionários\npodem subir.\012Mas como você\nveio de muito\011longe, receba essa\011lembrancinha.",
  ["61:5041"] = "É o produto\nmais novo da\011CORPORAÇÃO SILPH.\012Não se vende em\nlugar algum ainda.",
  ["61:50cd"] = "My daughter likes\nto mimic people.\012Her mimicry has\nearned her the\012nickname COPYCAT\naround here.",
  ["61:512e"] = "Minha filha é tão\negocêntrica…\012Ela tem poucos\namigos.",
  ["61:516c"] = "She recently lost\nthe POKé DOLL that\012a boy gave her\nthree years ago.\012Ever since then,\nshe's gotten even\011better at mimicry…",
  ["61:51e4"] = "BLISSEY: Bliisii!",
  ["61:52f1"] = "{PLAYER}: Hi! Do\nyou like POKéMON?\012{PLAYER}: Uh, no, I\njust asked you.\012{PLAYER}: Huh?\nYou're strange!",
  ["61:533f"] = "DUPLICA: Hmm?\nChega de mímica?\012É o que mais\ngosto de fazer!",
  ["61:537b"] = "{PLAYER}: Hi!\nI heard that you\012lost your favorite\nPOKé DOLL.\012{PLAYER}: If I find\nit, you'll give me\011a rail PASS?\012{PLAYER}: I'll go\nfind it for you.\012You think you lost\nit when you went\011to VERMILION CITY?",
  ["61:542d"] = "DUPLICA: Perdão?\012Não deveria\ndecidir o que você\011deve fazer?\012Mas estou muito\npreocupada. E se\011alguém achá-la?",
  ["61:5496"] = "COPYCAT: Yay!\nThat's my CLEFAIRY\011POKé DOLL!\012See the tear where\nthe right leg is\012sewn on? That's\nproof!",
  ["61:54f9"] = "Certo. Eis o PASSE\nDO TREM ÍMÃ como\011prometi!",
  ["61:552b"] = "DUPLICA: É o PASSE\npara o TREM ÍMÃ.\012O rapaz\nda compania\011ferroviária me\011deu quando\011derrubaram nossa\011velha casa para\011fazer a ESTAÇÃO.",
  ["61:55af"] = "{PLAYER}: Oi!\nMuito\nobrigado pelo\011PASSE de trem!\012{PLAYER}: Perdão?\012{PLAYER}: É legal\nassim copiar todos\011meus movimentos?",
  ["61:560c"] = "DUPLICA: Claro!\nÉ demais!",
  ["61:562d"] = "DODRIO: Gii giii!",
  ["61:5640"] = "ESPELHO, ESPELHO\nMEU, EXISTE ALGUÉM\011MAIS JUSTO DO QUE\011EU?",
  ["61:567b"] = "Esse é um\n#MON raro! Hã?\012É só um boneco…",
  ["61:5702"] = "Eeyaaaah!\012Sinto uma sombra\nsinistra te\011combrindo.\012Leve isso para\nexpulsá-la!",
  ["61:5766"] = "Você estava em\nperigo mortal,\011mas está protegido\011agora.",
  ["61:57ff"] = "Minha avó\nexpulsa o que ela\011acredita ser\011espíritos do mau.\012Perdoe-me se ela\nassustou você.",
  ["61:5851"] = "Você está coleci-\nonando INSÍGNIAS\011DOS GINÁSIOS DE\011KANTO?",
  ["61:5888"] = "Várias cidades em\nJOHTO têm longas\011histórias.\012Eu adoraria\nvisitá-las!",
  ["62:402c"] = "They're fresh out\nof POKé BALLS!\012When will they get\nmore of them?",
  ["62:406b"] = "POKé BALLS are in\nstock! Now I can\011catch POKéMON!",
  ["62:4098"] = "Quando caminhava\nna grama, um\011#MON inseto\011envenenou meu\011#MON! \012Continuei andando,\nporém meu #MON\011desmaiou. \012É recomendável que\ntenha um ANTÍDOTO\011com você.",
  ["62:4182"] = "Que bom. Posso\nguardar quantos\011#MON eu quiser\011e é de graça.",
  ["62:41c0"] = "Qualquer treinador\npode usar o\011COMPUTADOR.",
  ["62:41e9"] = "O CENTRO DE\nCOMUNICAÇÃO acima\011acabou de ser\011feito.\012Mas eles ainda\nestão fazendo\011ajustes.",
  ["62:423e"] = "O CENTRO DE\nCOMUNICAÇÃO acima\011acabou de ser\011feito.\012Já troquei\n#MON lá!",
  ["62:42e2"] = "Você está vendo\ncomo se sai sendo\011um treinador\011#MON?\012Recomendo-lhe\nvisitar os\011GINÁSIOS #MON\011em JOHTO e coletar\011INSÍGNIAS.",
  ["62:435d"] = "Quando eu crescer,\nserei um LÍDER DE\011GINÁSIO!\n \012Faço meus #MON\nbatalharem com os\011do meu amigo para\011fortalecê-los!",
  ["62:4405"] = "Quando era jovem,\neu fui um incrível\011treinador!\012Aqui vai um\nconselho: Capture\011muitos #MON!\012Trate-os com toda\ngentileza!",
  ["62:44bb"] = "Os #MON ganham\nexperiência nas\011batalhas e mudam\011suas formas.",
  ["62:44f4"] = "Os #MON mudam?\012Eu ficaria chocada\nse um mudasse!",
  ["62:457a"] = "Você sabe, os\n#MON comem\011GRÃOS.\012Bem, meu #MON\nficou mais\011saudável ao comer\011um GRÃO.\012Ei. Dividirei um\ncom você!",
  ["62:45e4"] = "Cheque as árvores\npara obter GRÃOS.\012Eles caem delas.",
  ["62:4755"] = "Olá, olá! Você\ndeve ser {PLAYER}.\012O PROFESSOR ELM\ndisse que você\011viria.",
  ["62:4797"] = "É isso que quero\nque o PROFESSOR\011ELM examine.",
  ["62:47c1"] = "{PLAYER} received\nMYSTERY EGG.",
  ["62:47da"] = "Conheço um casal\nque comanda o\011CRIATÓRIO #MON.\012Eles me deram esse\nOVO.\012Fiquei intrigado,\nentão enviei uma\011carta ao PROFESSOR\011ELM.\012Para a evolução\n#MON, o\011PROFESSOR ELM é a\011autoridade.",
  ["62:4881"] = "Até o PROFESSOR\nCARVALHO reconhece\011isso.",
  ["62:48a6"] = "Se o que acho\nfor certo, o\011PROFESSOR ELM\011saberá.",
  ["62:48dc"] = "Você está voltando\nao PROFESSOR ELM?\012Ei. Seu #MON\ndeve descansar um\011pouco.",
  ["62:4923"] = "Eu dependo de\nvocê!",
  ["62:4939"] = "A vida é ótima!\nSempre há coisas\011para descobrir!",
  ["62:4974"] = "OAK: Aha! So\nyou're {PLAYER}!\012I'm OAK! A POKéMON\nresearcher.\012I was just visit-\ning my old friend\011MR.POKéMON.\012I heard you were\nrunning an errand\012for PROF.ELM, so I\nwaited here.\012Oh! What's this?\nA rare POKéMON!\012Let's see…\012Hm, I see!\012I understand why\nPROF.ELM gave you\012a POKéMON for this\nerrand.\012To researchers\nlike PROF.ELM and\012I, POKéMON are our\nfriends.\012He saw that you\nwould treat your\012POKéMON with love\nand care.\012…Ah!\012You seem to be\ndependable.\012How would you like\nto help me out?\012See? This is the\nlatest version of\011POKéDEX.\012It automatically\nrecords data on\012POKéMON you've\nseen or caught.\012It's a hi-tech\nencyclopedia!",
  ["62:4bbb"] = "{PLAYER} received\nPOKéDEX!",
  ["62:4bcd"] = "Go meet many kinds\nof POKéMON and\012complete that\nPOKéDEX!\012But I've stayed\ntoo long.\012I have to get to\nGOLDENROD for my\011usual radio show.\012{PLAYER}, I'm\ncounting on you!",
  ["62:4c65"] = "Hm? Essa ESCAMA!\nO que é isso? Um\011GYARADOS vermelho?\012Que raro! Eu, eu\na quero…\012{PLAYER}, se\nimporta em\011trocá-la?\012Posso oferecer\nesse DIVIDE EXP.\011que o PROFESSOR\011CARVALHO me deu.",
  ["62:4cfc"] = "Que pena. Isso\nparece ser muito\011raro.",
  ["62:4d32"] = "Está empacotado\ncom revistas\011estrangeiras.\012Nem dá para ler\nseus títulos…",
  ["62:4d73"] = "É um grande\ncomputador. Hmm.\011Está quebrado.",
  ["62:4d9b"] = "Uma grande pilha\nde moedas\011estranhas!\012Talvez sejam de\num outro país…",
  ["62:4e29"] = "Hi, guy!\nDid you visit\011SPROUT TOWER?",
  ["62:4e4f"] = "Eu vim de longe.\nÉ melhor eu ligar\011para casa!",
  ["64:558e"] = "Sou o HOMEM DO\nCRIATÓRIO. Quer\011que eu crie um\011#MON para você?",
  ["64:55bd"] = "Sou o HOMEM DO\nCRIATÓRIO. Você\011conhece os OVOS?\012Eu estava criando\num #MON com\011minha esposa,\011como vê.\012Ficamos chocados\nao acharmos um\011OVO!\012Como isso é\nincrível!\012Então, quer que\ncrie um #MON?",
  ["64:566a"] = "Sou a DAMA DO\nCRIATÓRIO.\012Devo criar um\n#MON para você?",
  ["64:56a0"] = "Sou a DAMA DO\nCRIATÓRIO. Você\011conhece os OVOS?\012Meu marido e eu\nestávamos criando\011#MON, como\011vê.\012Ficamos chocados\nao acharmos um\011OVO!\012Como isso é\nincrível!\012Devo criar um\n#MON para você?",
  ["64:575e"] = "O que devo criar\npara você?",
  ["64:577c"] = "Oh? Mas você só\ntem um #MON.",
  ["64:579d"] = "Perdão, mas não\naceito um OVO.",
  ["64:57bf"] = "Remova a CARTA\nantes e venha\011me ver.",
  ["64:57e4"] = "Se me der isso,\ncom que você\011vai batalhar?",
  ["64:5815"] = "OK. I'll raise\nyour {STRBUF}.",
  ["64:5830"] = "Volte aqui depois.",
  ["64:5849"] = "Are we geniuses or\nwhat? Want to see\011your {STRBUF}?",
  ["64:587b"] = "Your {STRBUF}\nhas grown a lot.\012By level, it's\ngrown by {NUM}.\012If you want your\nPOKéMON back, it\011will cost ¥{NUM}.",
  ["64:58e9"] = "Perfeito! Aqui\nestá seu #MON.",
  ["64:5904"] = "{PLAYER} got back\n{STRBUF}.",
  ["64:5917"] = "Huh? Back already?\nYour {STRBUF}\012needs a little\nmore time with us.\012If you want your\nPOKéMON back, it\011will cost ¥100.",
  ["64:5987"] = "You have no room\nfor it.",
  ["64:59a1"] = "You don't have\nenough money.",
  ["64:59be"] = "Oh, fine then.",
  ["64:59ce"] = "Come again.",
  ["64:59db"] = "Ainda não…",
  ["64:59e5"] = "Ah, é você!\012Estamos criando\nseu #MON, e\012minha nossa,\nestamos surpresos!\012Seu #MON botou\num OVO!\012Não sabemos como\naconteceu, mas seu\012#MON o botou.\nVocê o quer?",
  ["64:5a8a"] = "{PLAYER} recebeu\no OVO!",
  ["64:5a9f"] = "Cuide bem dele.",
  ["64:5ab6"] = "Tudo bem. Vou\nmantê-lo.\011Obrigado!",
  ["64:5ad7"] = "Você não tem\nespaço em sua\011equipe. Volte\011depois.",
  ["65:4751"] = "Huh?\012",
  ["65:475b"] = "{STRBUF} came\nout of its EGG!",
  ["65:4778"] = "Give a nickname to\n{STRBUF}?",
  ["65:4793"] = "It's {STRBUF}\nthat was left with\011the DAY-CARE LADY.",
  ["65:47c4"] = "It's {STRBUF}\nthat was left with\011the DAY-CARE MAN.",
  ["65:47f4"] = "Está energizado\nnas bordas.",
  ["65:480f"] = "It has no interest\nin {STRBUF}.",
  ["65:482d"] = "It appears to care\nfor {STRBUF}.",
  ["65:484c"] = "It's friendly with\n{STRBUF}.",
  ["65:4866"] = "It shows interest\nin {STRBUF}.",
  ["65:4883"] = "Não há CARTAS\naqui.",
  ["65:4899"] = "A CARTA apagada\nfoi guardada.",
  ["65:48b9"] = "A BOLSA está\ncheia.",
  ["65:48cc"] = "A mensagem da\nCARTA será\011apagada.\012Deseja continuar?",
  ["65:48f1"] = "Já está segurando\num item.",
  ["65:4911"] = "Um OVO não pode\nsegurar uma CARTA.",
  ["65:492d"] = "A CARTA foi movi-\nda da CAIXA DE\011CARTAS.",
  ["65:4993"] = "Há um #MON se-\ngurando uma CARTA.\012Por favor remova\na CARTAL.",
  ["65:544a"] = "Remova a CARTA\nprimeiro.",
  ["65:54fd"] = "A CARTA perderá\nsua mensagem.\011Deseja continuar?",
  ["65:5522"] = "MAIL detached from\n{STRBUF}.",
  ["65:553d"] = "Não há espaço para\nremover a CARTA.",
  ["65:5561"] = "Enviar a CARTA\nremovida para\011seu COMPUTADOR?",
  ["65:5584"] = "Sua CAIXA DE\nCARTAS DO PC\011está cheia.",
  ["65:559f"] = "A CARTA foi en-\nviada para seu\011COMPUTADOR.",
  ["65:5624"] = "Hello! Sorry to\nkeep you waiting!\012Welcome to the\nworld of POKéMON!\012My name is OAK.\012People call me the\nPOKéMON PROF.",
  ["65:5693"] = "This world is in-\nhabited by crea-\011tures that we call\011POKéMON.",
  ["65:56d3"] = "Olá! Desculpe-me\npor mantê-los es-\011perando!\012Bem-vindo ao mundo\ndos POKéMONS!\012Meu nome é\nCARVALHO.\012As pessoas me cha-\nmam de PROFESSOR\011#MON.",
  ["65:573f"] = "Mas nós não sa-\nbemos tudo sobre\011os #MON ainda.\012Ainda há muitos\nmistérios para se-\011rem resolvidos.\012É por isso que eu\nestudo #MON\011todos os dias.",
  ["65:57b7"] = "Então, como era\nmesmo o seu nome?",
  ["65:57dd"] = "{PLAYER}, você\nestá preparado?\012Sua própria histó-\nria #MON está\011prestes a começar.\012Você vai encarar\nmomentos diverti-\011dos e duros desa-\011fios.\012Um mundo de sonhos\ne aventuras com\012#MON o espera!\nVamos lá!\012Nos veremos mais\ntarde!",
  ["65:5c61"] = "Quantos?",
  ["65:5c6c"] = "{NUM} {STRBUF}(S)\nwill be ¥{NUM}.",
  ["65:5c8c"] = "Olá, querido.\012Eu vendo ervas\nmedicinas baratas.\012São boas, porém\nbastante amargas.\012Seus #MON po-\ndem não gostar\011delas.\012Hehehehe…",
  ["65:5d07"] = "Quantos?",
  ["65:5d12"] = "{NUM} {STRBUF}(S)\nwill be ¥{NUM}.",
  ["65:5d32"] = "Obrigada, querido.\nHehehehe…",
  ["65:5d4e"] = "Oh? Sua BOLSA está\ncheia, querido.",
  ["65:5d6c"] = "Hehehe… Você não\ntem dinheiro sufi-\011ciente.",
  ["65:5d8e"] = "Volte de novo,\nquerido. Hehehehe…",
  ["65:5dab"] = "Olá! Se importa\nem ver alguns\011produtos?\012Eu vendo itens\nraros que ninguém\012tem--mas apenas\num de cada.",
  ["65:5e14"] = "{STRBUF} costs\n¥{NUM}. Want it?",
  ["65:5e31"] = "Obrigada.",
  ["65:5e3a"] = "Uh-oh, your PACK\nis chock-full.",
  ["65:5e5b"] = "Você já comprou\nisso. Não tenho\011mais esse produto.",
  ["65:5e8c"] = "Opa, você está com\npouco dinheiro.",
  ["65:5eaa"] = "Volte aqui outra\nhora.",
  ["65:5ec3"] = "O que foi?\nPrecisa de\011remédio?",
  ["65:5ee2"] = "Quantos?",
  ["65:5eed"] = "{NUM} {STRBUF}(S)\nwill cost ¥{NUM}.",
  ["65:5f0f"] = "Muito obrigada!",
  ["65:5f1d"] = "Você não possui\nmais espaço.",
  ["65:5f3c"] = "Hã? Esse dinheiro\nnão é suficiente.",
  ["65:5f5a"] = "Tudo bem.\nAté mais tarde.",
  ["65:5f76"] = "Você não tem nada\npara vender.",
  ["65:5f97"] = "Quantos?",
  ["65:5fa2"] = "I can pay you\n¥{NUM}.\012Is that OK?",
  ["65:5fc6"] = "Bem-vindo! Posso\najudá-lo?",
  ["65:5fe4"] = "Aqui está.\nObrigado!",
  ["65:5ffe"] = "You don't have\nenough money.",
  ["65:601b"] = "Você não pode\ncarregar mais\011itens.",
  ["65:603b"] = "Perdão, não posso\ncomprar isto de\011você.",
  ["65:605d"] = "Please come again!",
  ["65:6071"] = "Posso fazer algo\npor você?",
  ["65:6092"] = "Got ¥{NUM} for\n{STRBUF}(S).",
}
